CREATE TABLE IF NOT EXISTS legal_documents (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  "originalTitle" TEXT,
  "documentType" TEXT NOT NULL CHECK ("documentType" IN ('constitution','act','regulation','schedule_only')),
  "yearBs" NUMERIC NOT NULL,
  "yearAd" NUMERIC NOT NULL,
  "totalPages" INTEGER NOT NULL CHECK ("totalPages" >= 0),
  nodes JSONB NOT NULL
);

INSERT INTO legal_documents (id,title,"originalTitle","documentType","yearBs","yearAd","totalPages",nodes) VALUES (
  $LEGAL_ab96e86c97ce3a$doc_national_criminal_procedure_code_2074_2017$LEGAL_ab96e86c97ce3a$,
  $LEGAL_ab96e86c97ce3a$The National Criminal Procedure (Code) Act, 2017$LEGAL_ab96e86c97ce3a$,
  NULL,
  $LEGAL_ab96e86c97ce3a$act$LEGAL_ab96e86c97ce3a$,
  2074,
  2017,
  264,
  $LEGAL_ab96e86c97ce3a${"id":"doc_national_criminal_procedure_code_2074_2017","title":"The National Criminal Procedure (Code) Act, 2017","originalTitle":null,"documentType":"act","yearBs":2074,"yearAd":2017,"totalPages":264,"nodes":[{"tier":1,"nodeType":"preamble","identifier":"Preamble","title":"Introductory matter","content":"(Revised)\nThe National Criminal Procedure (Code) Act, 2017\nDate of Authentication:\n16 October 2017\nAct Number 37 of the year 2017\nAn Act Made To Amend And Consolidate Laws Relating to\nProcedures of Criminal Cases\nPreamble:\nWhereas, it is expedient to make the procedural law simplified and\ntimely, by amending and consolidating the laws in force relating to\nprocedures on investigation, prosecution, filing, proceeding, hearing and\nadjudication of crim inal cases and other procedures related thereto, and\nexecution of judgments on such cases;\nNow, therefore, the Legislature -Parliament referred to in clause (1)\nof Article 296 of the Constitution of Nepal has enacted this Act.","children":[]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-1","title":null,"content":"Preliminary","children":[{"tier":2,"nodeType":"rule","identifier":"1","title":"Short title and commencement","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"This A ct may be cited as the\n\"National Criminal Procedure (Code) Act, 2017\".","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Section 1 92 of this Act shall commence on such date as\nappointed by the Government of Nepal by a notification in the Nepal\nGazette, and the other Sections, on 17 August 2018.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"2","title":"Definitions","content":"Unless the subject or the context o therwise requires, in\nthis Code,-\n(a) \"court\" means the Supreme Court, High Court or District\nCourt, and this term also includes any other court, judicial\nbody or authority empowered by law to proceed, hear and\nadjudicate any specific type of criminal cases;\n(b) \"investigating authority\" means an authority designated under\nthis Act or competent authority under law to make\ninvestigation into any offence, and this term also includes an\ninvestigation team formed to investiga te into any specific\noffence;\n(c) \"Penal Code\" means the National Penal (Code) Act, 2017;\n(d) \"complaint\" means a plaint to be filed in a court, and this term\nalso includes a charge -sheet in relation to an y offence under\nSchedule-1 or Schedule -2, and a rep ort thereon in relation to\nany other case;\n(e) \"offence\" means an act punishable by the Penal Code or other\nAct;\n(f) \"law\" means a law for the time being in force;\n(g) \"grave offence\" means an y offence punishable by a sentence\nof imprisonment for a term of more tha n three and less than\nten years;\n(h) \"heinous offence\" means any offence punishable by a sentence\nof imprisonment for life or for a term of more than ten years,\n(i) \"place\" means a house, shed, cow shed, elephant shed or tent,\nand this term also includes a motor vehicle, vessel, aircraft,\nand other place or means of similar nature;\n(j) \"judge\" means the auth ority of a court to proceed, hear and\nadjudicate a case, and this term also includes an authority\ncompetent to proceed, hear and adjudicate a criminal case;\n(k) \"police office\" means a police office authorized to investigate\ninto any offence set forth in Schedule-1;\n(l) \"criminal case\" means a case related to an o ffence under\nSchedule-1, Schedule -2, Schedule -3 or Schedule -4, and this\nterm also includes any other case, except a case on any of the\nfollowing matters:","children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A case related to a legal right, status, post, family\nrelationship or property,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Establishment of relationship, or divorce,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Fee, remuneration, salary, allowance or wage,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Partition, succession, donation, gift, will,\nguardianship, curatorship, parental authority,\nadoption,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Any right or claim under any contract, quasi -\ncontract or unlawful enrichment,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Any right or claim relating to tort, quasi -tort or\ndefective product,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Servitude,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"Compensation, or","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"Any other right or liability of civil nature.\n(m) \"case\" means a criminal case;\n(n) \"adjudicating authority\" means an authority empowered by\nlaw to proceed, hear and adjudicate a case, and this term also\nincludes, in the case of a person taken in custody, a court\nnearby the place where the person is taken in custody;\n(o) \"Local Level\" means a Vil lage Body ( Gownpalika) or\nMunicipality;\n(p) \"government attorney\" means the Attorney General, Deputy\nAttorney General, Joint Attorney, Deputy Attorney, District\nAttorney or Assistant District Attorney, and this term also\nincludes an officer designated by the Attorney General to act\nin the capacity of government attorney.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"3","title":"Special legal provisions, if any, made not to be affected","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If a\nseparate Act provides for special provisions on the prosecution ,\ninvestigation, trial, hearing, execution of judgment s or any other\nproceeding of, or jurisdiction to try case s on, any specific offence,\nsuch matters shall be governed by such Act and shall not be affected\nby any provision contained in this Act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"This Act shall govern t he matters of procedures on\nwhich special legal provisions have not been made pursuant to sub-\nsection (1).","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-2","title":null,"content":"Provisions Relating to Information on Commission of, and\nInvestigation into, Offences","children":[{"tier":2,"nodeType":"rule","identifier":"4","title":"First information report or information on commission of","content":"offence to be given: (1) A person who knows that any offence set\nforth in Schedule -1 has been committed or is being committed or is\nlikely to be committed shall, as soon as possible, make a first\ninformation report in writing or give information on such of fence,\nverbally or through electronic means, along with whatever proof or\nevidence which is in his or her possession or which he or she has\nseen or known, to the nearby police office in the form referred to in\nSchedule-5.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a person making a first information report or giving\ninformation referred to in sub-section (1) does not give such\ninformation in writing, the concerned police employee shall set down\nall matters of information given by the person in the form referred to\nin Schedule-5, read out the same to, and cause it to be signed by, that\nperson.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a person makes in person a first information report or\ngives information referred to in sub -section (1) to the concerned\npolice office, or sends such information throu gh any person or\nelectronic means, such po lice office shall register such report or\ninformation and give that person a receipt thereof, in the f orm\nreferred to in Schedule-6. If any person gives information through\nelectronic means, acknowledgement of rece ipt of such information\nshall be given through the same means.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained in sub -section (1),","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"or (3), if the police receives any report or information about the\ncommission of any offence set forth in Schedule -1 from any othe r\nsource or on his or her own, the police shall prepare a report along\nwith the details set forth in Schedule-5.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The police office shall enter the first information report,\ninformation referred to in this Section or the report referred to in sub-\nsection (4) in a register in the form referred to in Schedule-7.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Any first information report or information received\npursuant to sub -section (1) shall be forwarded to the separate\ninvestigating authority, if any , specified by law in relatio n to such\nreport or information, and, failing the specification of such separate\ninvestigating authority, to the concerned district police office.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"A person wishing to give information about any offence\nset forth in Schedule -2 shall give such information, in the form\nreferred to in Schedule -5, to the office or authority empowered to\ninvestigate into that offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"The concerned office or authority shall register the\ninformation received pursuant to sub -section (7) and give a receipt\nthereof, in the form referred to in Schedule -6, to the person who\ngives such information.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"If it is not possible to immediately register the\ninformation referred to in sub -section (7) in the concerned office or\nauthority, such information may also be given to the nearby police\noffice.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"The concerned police office shall, if it receives any\ninformation pursuant to sub -section (9), register such information\npursuant to sub-section (5) and forward it to the concerned office or\nauthority not later than three days for action.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"5","title":"Complaint against refusal to register first information report or","content":"information: (1) If the concerned police office refuses to register a\nfirst information report made or information given pursuant to sub -\nsection (1) of Section 4, the person making or giving such fir st\ninformation report or information may make a complaint setting out\nsuch matter, accompanied by the first information report or\ninformation, to the concerned d istrict government attorney o ffice or\nthe police office higher in level than the police office required to\nregister such first information report or information.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a complaint referred to in sub -section (1) is received,\nthe concerned d istrict government attorney o ffice or police office\nshall maintain records thereof and forward such first info rmation\nreport or information to the concerned police office for necessary\naction.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The concerned police office shall, in accordance with\nsub-section (3) of Section 4, register and take action on the first\ninformation report or information received pu rsuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":".","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the office or authority referred to in sub -section (7) of\nSection 4 refuses to register any information referred to in that sub -\nsection, the person giving such information may make a complaint\nsetting out the matter, accompanied by the information of offence, to\nthe Chief District Officer of the concerned district.\nProvided that where the Chief District Officer himself or\nherself is designated as the investigating authority and refuses to\nregister such information, such co mplaint may be made to the\nMinistry of Home Affairs.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Upon receipt of any complaint referred to in sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":", the concerned Chief District Officer or the Ministry of Home\nAffairs shall decide, within three days, as to whether or not to\nregister such information, and give direction to the concerned office\nto take, or cause to be taken, action accordingly.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Upon receipt of any direction referred to in sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":", the concerned office or authority shall take action in pursuance\nof the direction.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"6","title":"Arrangements to be made to prevent evidence from being","content":"concealed or destructed and prevent offender from escaping: (1)\nIf any police office or police employee gets information that any\noffence set forth in Schedule -1 has been committed or is being\ncommitted or is likely to be committed, such office or employee\nshall, as promptly as possible, make necessary and effective\narrangements in order to prevent the offender from committing the\noffence or prevent any evidence related to the offence from being\ndisappeared or destructed and prevent the offender from going away\nor escaping.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If there is a likelihood of the concealment or destruction\nof any evidence related to the offence or the escaping or going away\nof the offender where immediate actio n is not taken pursuant to sub -\nsection (1), such police office or employee may take necessary action\nin that behalf, even by entering the area of another police office, as\nper necessity.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In the event of a need for taking any action by entering\nthe area of another police office pursuant to sub -section (2), such\npolice office or employee shall give information thereof to the\nconcerned police office or body and the higher police office.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the concerned authority comes to know, on his or her\nown initiative or on information made by any one, that any offence\nset forth in Schedule-2 has been committed or is being committed or\nis likely to be committed, such authority shall take action referred to\nin sub-section (1) or (2).\nProvided that if any police empl oyee receives information\nabout such offence and the concerned investigating authority is not\navailable for the time being , such police employee shall take action\nreferred to in sub -section (1) and send the statements of such action,\ntogether with the pers on, if any arrested, to the investigating\nauthority.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Any police employee or investigating authority may ask\nany body, authority or person to render assistance in preventing the\ndisappearance or destruction of any evidence related to the offence\nor in a rresting the offender; and it shall be the duty of such body,\nauthority or person to render necessary assistance wherever such\nassistance is so asked for.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If a police employee sees a person committing an\noffence in his or her presence or at a time when the police employee\nis there in sea rch of clues upon receipt of a notice, information or\nclue that such offence has been committed or is being committed or\nis likely to be committed, the police employee shall immediately\narrest the person committing such offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"The police employee shall take possess ion of exhibits\nand other proof s, evidence or thing s related to the offence, if any,\nfound on the spot and execute a deed thereon, as required, in the\npresence of the eye witnesses, if any, present on the spot.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"Such thing, place or spot shall be protected as it is until\nthe completion of the execution of such deed pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":".","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"Where it is not possible to immediately seize or take\npossession of the exhibits and other evidence or things related to the\noffence obtained pursuant to sub -section (7), the concerned police\nemployee may make a request to the Local Level or any other office\nto safely retain such exhibits or th ings, and the concerned Level or\noffice shall, when so requested, take custody of such exhibits or\nevidence and give a receipt thereof.\nProvided that the goods not related to the offence shall be\nimmediately returned to the concerned person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"7","title":"Information to be given to concerned police office","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If the any\npolice office knows, from the contents of information received by it\nin relation to any offence set forth in Schedule -1or on its own\ninitiative, that such offence has been committed or is being\ncommitted or is likely to be committed in the area of another police\noffice, such police office shall, as soon as possible, send such\ninformation to the concerned police office, and inform the informant\nto appear in the concerned police office, as required.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nif there is a possibility that the offender may escape and any exhibits\nor evidence related to the offence may disappear due to the non -\navailability of the investigating authority for the time being be cause\nof geographical remoteness or any other cause, the competent\ninvestigating officer of the concerned police office receiving such\ninformation shall make preliminary investigation into the offence\ncommitted in such area and send details of such investi gation to the\nconcerned police office.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Such authority shall, prior to making preliminary\ninvestigation pursuant to sub -section (2), give information to the\nconcerned police office and the one level higher police office.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"8","title":"Collection of proof and evide nce upon making investigation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Upon receipt of any information that a n offence set forth in\nSchedule-1 has been committed or is being committed or is likely to\nbe committed, the concerned police office shall, as soon as possible,\ndesignate a police emp loyee whose rank is at least assistant sub -\ninspector as the investigating authority and give information thereof\nto the concerned government attorney office and the higher police\noffice; and the investigating authority so designated shall conduct\ninvestigation into such offence.\nProvided that a police employee whose rank is at least police\ninspector shall be designated to investigate into any of the following\noffences:\n(a) Offences set forth in Chapter -1, Chapter -12, Chapter -\n17, Section 219 of Chapter -18, Sections 230, 231, 232,\nsub-section (4) of Section 233, Section 235, sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"of Section 238 of Chapter -19, Section 244 of\nChapter-20, Sections 256, 257 and 258 of Chapter 22,\nof Part-2 of the Penal Code,\n(b) Offences related to narcotic drugs, human trafficking\nand transportation and foreign exchange,\n(c) Any other offence so specified by the Government of\nNepal by a notification in the Nepal Gazette, taking into\naccount the gravity of the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The investigating authority shall, in conducting\ninvestigation under this Section, prepare a deed on the scene of crime\ncontaining the following matters, as far as practicable, in such\nmanner as to demonstrate the actual description of the offence and\nthe place where the offence was committed:\n(a) The date and time when the offence was committed,\n(b) The address, description and sketch of the place where\nthe offence was committed,\n(c) The circumstance of such place and its connection with\nthe offence or offender,\n(d) The exhibits or evidence found or seen at or around the\nplace where the offence was committed, and any other\nsignificant matters related to the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"After preparing a deed on the scene of offence pursuant\nto sub -section (2), the investigating authority may, as far as\npracticable, take a photograph of such place and of any finger print\nor foot print, mark or other exhibits seen or found at such place or\nany other important matter that may be helpful in establishing the\nguilt.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In preparin g a deed on the scene of crime pursuant to\nsub-section (2), thumb impressions as well as identity disclosing\ndetails of the offender or accused person, if present, shall also be\ntaken.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The investigating authority shall take possession of the\nexhibits, evidence, object or article related to the o ffence, if any\nfound.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"The authority taking possession of any exhibits,\nevidence, object or article pursuant to sub -section (5) shall give a\nreceipt thereof to the concerned person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Investigation into any of the offences set forth in\nSchedule-2 shall be conducted by the authority, if any, specified by\nlaw to that effect, and, failing the specification of such authority, by\nthe concerned chief district officer or officer level employee\ndesignated by him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"The authority specified pursuant to sub-section (7) shall,\nin conducting investigation into such offence, fulfill the procedures\nset forth in sub-sections (2), (3), (4), (5) and (6).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"In conducting investigation into any offence committed\non the same occasion pursuant to this Chapter, inv estigation into all\ncases that may be instituted from the acts done on such occasion\nshall be conducted at the same time.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"9","title":"Power to arrest person related to offence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The police or\ninvestigating authority may arrest any person related to an offence if\nsuch person is found or caught in the course of committing the\noffence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, in the course of investigation into any offence, it is\nnecessary to arrest any person immediately in accordance with this\nChapter, an application, along with the reason for such arrest, and the\ndetails disclosing the identity of the person to be arrested, as far as\npracticable, shall be made to the adjudicating authority for\npermission to issue a warrant of arrest.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If an application is made pursuant to sub-section (2) and\nthe reason for arrest appears to be reasonable, the adjudicating\nauthority may, on the same application, give permission to issue a\nwarrant of arrest.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The form of a warrant of arrest shall be as referred to in\nSchedule-8.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The order referred to in sub -section (3) shall not be\ndisclosed until the person to be arrested is arrested.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Notwithstanding anything contained in sub -section (2),\nif a person who is not arrested at once or there is a reasonable ground\nto believe that such person may a bscond, escape or destroy the\nevidence, exhibits or proof, such person shall be arrested\nimmediately upon issuing an urgent warrant of arrest in the form\nreferred to in Schedule -9, and the matter shall be submitted to the\nadjudicating authority, along with the person so arrested, for\npermission.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If any person is arrested upon issuing an urgent warrant\nof arrest pursuant to sub -section (6), no other investigation related\nproceedings related to such offence may be initiated without\nobtaining permission from the adjudicating authority.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If the police is not available for th e time being at the\ntime of commission of any offence, any person wh o is present at the\ntime of commission of that offence or who is eye witness thereto\nmay prevent the person committing such offence from going away or\nescaping and hand him or her over to the nearby police office.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"If it is necessary to arrest a person pursuant to sub -\nsection (1) or (6), such person shall, prior to arresting him or her, be\ninformed of the cause n ecessitating his or her arrest and reminded,\npersuaded and ordered to surrender himself or herself.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"If, in spite of the remainder, persuasion or order under\nsub-section (9), any person does not surrender himself or herself but\nmakes attempt to evade, escape or avoid arrest or confronts or\nattempts to confront in any manner, with or without the use of force,\nthe police employee may use necessary force to arrest him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"If a woman is to be arrested pursuant to this Section, the\nwoman shall be arrested by a female police as far as possible.\nProvided that if a female police is not available for the time\nbeing to arrest such woman, nothing shall bar the arresting of such\nwoman by a male police employee in such manner as to respect her\nphysical sensitivity and as not to undermine her dignity or prestige.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(12)","title":null,"content":"A person who is arrested pursuant to this Section or his\nor her body may be searched.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(13)","title":null,"content":"If there is a reasonable ground to suspect that any\nperson to be arrested pursuant to this Section is residing in any house\nor place, that person may be arrested by making search of such house\nor place.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(14)","title":null,"content":"If a person is arrested upon making search pursuant to\nsub-section (13), the body of such person may also be searched.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(15)","title":null,"content":"The person who arrests s uch person or investigating\nauthority shall take custody of any evidence related document or\nexhibits, evidence or any other thing found during the search made\npursuant to sub-section (12) or (13), and give a receipt thereof.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(16)","title":null,"content":"Notwithstanding anythin g contained elsewhere in this\nSection, if any person commits any offence under Schedule -1 or\nSchedule-2 in the presence of any police employee or authority or in\nany government office, the concerned police employee, authority or\nchief of office may, as required, arrest such person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"10","title":"Preliminary investigation report to be forwarded","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The\ninvestigating authority or police employee designated to investigate\ninto any of the offences set forth in Schedule -1 or Schedule -2 shall\nconduct preliminary investiga tion immediately after a first\ninformation report or information as to the commission of such\noffence has been registered pursuant to Section 4.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Such investigating authority or police employee shall,\nafter the commencement of the preliminary investiga tion pursuant to\nsub-section (1), forward a report thereof to the district government\nattorney office within three days.\nExplanation: For the purposes of this Chapter , the term\n\"preliminary investigation\" means the description of the scene of\noffence, deed on the scene of crime , search or seizure deed or deed\nof examination of corpse in the case of homicide , and, in the case of\nother offence, report, deed or other necessary description required to\nbe prepared depending on the nature of such offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The government attorney may, upon receipt of a\npreliminary report pursuant to sub -section (1), give necessary\ninstruction, accompanied by the reasons, to the investigating\nauthority if the attorney thinks, on studying the report, that it is\nexpedient to give such instruction to conduct further investigation\ninto any matter in connection with the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"It shall be the duty of the concerned investigating\nauthority to comply with the instruction given pursuant to sub -\nsection (3).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"11","title":"Power to abate deceptive, false or fabricated information","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If,\nalso upon inquiring into the concerned person or informant in\nrelation to the first information report or report received as to any\noffence set forth in Schedule -1 or Schedule -2, it appears that it is\nunnecessary or meaningless to conduct investigation into such\noffence by the reason that such report or information is deceptive,\nfalse or fabricated, the concerned police office shall send a report\nsetting out that matter to the concerned government attorne y office\nnot later than three days in general cases.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Upon receipt of a report pursuant to sub -section (1), the\nconcerned gove rnment attorney office may abate the investigation\ninto such offence for the time being subject to the conducting of\ninvestigation as and when additional evidence is found if there is no\nreasonable ground to conduct such investigation immediately or give\ndirection, accompanied by the reason, to the investigating authority\nto conduct further investigation if, upon studyin g the nature of\ncommission of offence on that occasion, it thinks appropriate to\nconduct investigation immediately.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the government attorney office gives direction to\nconduct investigation pursuant to sub -section (2), the concerned\ninvestigating authority shall conduct investigation into such offence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"12","title":"Power to form special team to conduct investigation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained elsewhere in this Chapter, if the\nInspector General of Police or the pertinent superior authority of the\ninvestigating authority is of the opinion that it is appropriate to form\na separate investigating team to conduct investigation into any\noffence set forth in Schedule -1 or Schedule -2 of this Act by the\nreason that such investigation cannot be conducted by th e designated\ninvestigating authority alone in view of the gravity of that offence,\nthe Inspector General of Police or such superior authority may form\nan investigating team consisting of his or her subordinate employees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything con tained in sub -section (1),\nif it is required to form an investigating team consisting of other\npersons also, in addition to his or her subordinate employees, the\npertinent superior authority of such investigating authority or the\nInspector General of Polic e may, in consultation with the Attorney\nGeneral on that matter, form an investigating team consisting of\nexperts as well, and cause such investigation to be conducted by that\nteam.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If an investigating team is formed pursuant to sub -\nsection (1) or (2) , such team shall conduct investigation, in exercise\nof the powers conferred to the investigating authority under this\nChapter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If an investigating team is formed pursuant to sub -\nsection (1) or (2), the concerned investigating authority shall hand\nover to such team the details of investigation conducted by him or\nher.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The investigating team formed pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"or (2) shall conduct investigation and submit its report to the\nconcerned government attorney and give information thereof to the\nconcerned police office, as well.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If, upon receipt of a report pursuant to sub -section (5),\nthe government attorney considers it necessary to give necessary\ndirection to conduct further investigation on any matter related to the\noffence, he or she may give necessary direction, accompanied by the\nreason therefor, to the investigating team.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"It shall be the duty of the concerned investigating team\nto comply with the direction given by the government attorney\npursuant to sub-section (6).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"13","title":"To hol d in detention","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A person who is arrested in accordance\nwith this Chapter shall be held in detention.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person shall be detained pursuant to sub -section (1),\nonly upon serving on such person a warrant for detention in the form\nreferred to in Schedule-10, setting out the place where such person\nwas arrested and the reason for holding in detention.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If any person is detained pursuant to sub -section (1),\nthere shall be prepared his or her records containing, inter alia, his or\nher name, surname, age, address including street, father's name,\nmother's name, citizenship certificate or other identity card, if any,\ndisclosing his or her identity, and failing such certificate or car d,\ndriving license, passport, telephone number, if any, and duplicate\ncopies of similar documents setting out his or her real identity.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"For the purposes of sub -section (3), the investigating\nauthority may, as required, also take his or her photograph and\nthumb impressions of both hands, with palms.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"After the preparatio n of the records pursuant to sub -\nsection (3), the concerned police office or investigating authority\nshall give information, based on such records, about his or her\ndetention to the person specified by the person held in detention to\nreceive such information.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If a person arrested pursuant to this Section intends to\nconsult a law practitioner, the investigating authority shall allow him\nor her to consult such law practitioner.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"14","title":"Period during which one may be held in detention for","content":"investigation, and p rocedures relating thereto: (1) After a person\nhas been arrested under this Chapter for investigation into any\noffence, the person shall be produced before the adjudicating\nauthority as soon as possible within twenty-four hours.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No person shall be held in detention in contravention of\nsub-section (1).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If it is necessary to hold a ny person in detention for a\nperiod exceeding that set forth in sub -section (1), the investigating\nauthority shall make an application for remand, accompanied by the\nreasons and grounds for such detention, to the adjudicating authority\nthrough the government attorney office.\nExplanation: For the purposes of this Section, the period\nrequired for the journey from the place of arrest to the police office\nor from the police office to the court for the purpose of producing the\nperson arrested before the adjudicating authority within twenty-four\nhours shall not be counted.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The application made by the investigating authority to\nthe adjudicating authority pursuant to sub -section (3) shall clearly\nstate the charge made against the detained person, grounds of such\ncharge, reason for detaining him or her for investigation and details\naccording to his or her deposition, if made.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A person who is produced fo r a remand for detention\npursuant to sub -section (2) may, if he or she so wishes, make an\napplication to the adjudicating authority for the physical examination\nof his or her body.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If the investigating authority requests for a remand for\ndetention of a person pu rsuant to sub -section (3 ), the adjudicating\nauthority may remand such person in detention for a maximum\nperiod of twenty -five da ys at one time or several times if, upon\nstudying the relevant documents and also upon hearing the pleadings\nof the l egal practitioner concerned, if considered necessary, the\nadjudicating authority thinks that it is necessary to keep on detaining\nsuch person for investigation.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Notwithstanding anything contained in sub -section (6),\nboth the investigating authority and the government attorney may\nsubmit to the adjudicating authority a report, along with the reason,\nthat investigation into any offence related to assault on the President,\nespionage, giving provocation to the desertion of a soldier, waging\nwar against the State of Nepal, assistance to the army of a state\ninvolved in a war against Nepal, explosives, kidnapping or hostage-\ntaking, out of the offences under Schedule -1, cannot be completed\nwithin the period given under sub-section (6).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If a report referred to in sub-section (7) is submitted, the\nadjudicating authority may, having regard to the status of\ninvestigation, remand the accused person in detention for a\nmaximum of additional fifteen days at one time or several times.\nProvided that no person accused of any offence may be held in\ndetention for a period exceeding the term of imprisonment that is\nimposable on him or her if he or she is held guilty thereof.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"In issuing a remand order pursuant to sub-section (6) or","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":", the adjudic ating authority shall execute a memorandum,\naccompanied by the reasons therefor.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if the investigating authority , in view of the nature of the\noffence, thinks it reasonable to conduct investigation without holding\nin detention a woman with pregnancy of more than seven months, a\nchild, and a person over 75 years of age, such authority may conduct\ninvestigation by remanding such woman, child or person on\nrecognizance, and executing a memorandu m to that effect,\naccompanied by the reasons therefor.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"15","title":"Power of investigating authority to release person held in","content":"detention: (1) If it does not appear necessary or appropriate to keep\non detaining a person held in detention in the course of investigation\nunder this Act, the investigating authority may, with the consent of\nthe government attorney or by executing a memorandum,\naccompanied by the reasons therefor , where it is not possible to\nobtain such consent for the time being, remand such pe rson on\nbail/bond or guarantee or personal guarantee furnished by any\nreliable person or on recognizance to appear on appointed days.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In remanding any person on bail/ bond, or on\nrecognizance to appear on appointed days pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":", a deed shall be caus ed to be executed by the person so released,\ncovenanting that he or she shall appear when it becomes necessary to\ninstitute the case against him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A person who furnishes personal guarantee pursuant to\nsub-section (1) shall cause the person released on his or her personal\nguarantee to appear at such time as appointed by the investigating\nauthority or government attorney office.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If a person who furnishes personal guarantee fails to\ncause such person to appear at the time appoint ed pursuant to sub -\nsection (3), he or she shall be liable to a fine of five thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Where investigation has been conducted by remanding a\nperson on recognizance to appear on appointed days, the\ninvestigating authority shall give information th ereof to the\ngovernment attorney and the higher police office.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"16","title":"Deposition and interrogation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The investigating authority may\ntake deposition from the accused in relation to any offence under\nSchedule-1 or Schedule -2 in the presence of the governmen t\nattorney.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In taking deposition pursuant to sub -section (1), the\ngovernment attorney shall have the right to ask necessary matter as\nrequired to be set out in relation to the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The investigating authority shall interrogate , as\nnecessary, any person, who is believed, based on a reasonable\nground, to have knowledge of any important matter in connection\nwith any offence under Schedule-1 or Schedule-2.\nProvided that if it is required to interrogate any child or any\nperson who is physically incom petent, such child or person may be\ninterrogated at his or her abode.\nExplanation: For the purposes of this Section, the term\n\"physically incompetent\" means a physically incompetent person\nsuch as one who cannot make movement, who is with visual\nimpairment or who is of elderly age.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The investigating authority shall, if interrogation is\nmade pursuant to sub -section (3), record the matters interrogated in\nthe form referred to in Schedule -11 and attach the same with the\nconcerned case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If it is necessary to have a document executed by a child\nor physically incompetent person pursuant to this Section, it shall be\nexecuted in presence of his or her guardian or other person available.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If any person who is to make deposition or be\ninterrogated pursuant to this Section is not able to present before the\ninvestigating authority for the reason of physical il lness or it is not\nappropriate to cause his or her presence before such authority for the\nreason of his or her security, the investigating authorit y may take\nstatement of or interrogate such person through video conference.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"The investigating authority shall, if statement is taken or\ninterrogation made pursuant to sub -section (6), arrange for\nmaintaining the records thereof.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"17","title":"To answer question asked","content":"The concerned person shall assist in\ninvestigation by giving answer, to the best of his or her knowledge,\nto any question asked by the investigating authority in connection\nwith any offence being investigated under this Chapter.\nProvided that no person shall be compelled to give any answer\nwhich might be of self-incriminatory nature.","children":[]},{"tier":2,"nodeType":"rule","identifier":"18","title":"Power to make search","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If, in conducting investigation into any\noffence under Schedule-1 or Schedule -2, the investigating authority\nhas a reasonable ground to s uspect that any document, exhibit,\nevidence, accused or other person connected with such offence is in\nany place, the authority may search such person or place and seize\nsuch document, exhibit or evidence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Prior to making a search pursuant to sub -section (1),\nthere shall be served on the person residing for the time being in the\nhouse to be searched a notice in writing, accompanied by the reason\nfor making search, in the form referred to in Schedule-12.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In making a search pursuant to sub -section (1), it shall\nbe made upon executing a deed in the form referred to in Schedule-\n13.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The investigating authority shall get the concerned\nhouse owner or person to search him or her as well , prior to entering\ninto such place in order to make search pursuant to sub-section (1).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"In making a search of a house or room where only\nwomen reside or stay pursuant to sub -section (1), such search shall\nbe made by entering into such house or room, being accompanied by\nanother wamen also, as far as possible.\nProvided that in searching the body of a woman, such search\nshall be caused to be made by a female police or by any other\nwoman if such police is not available for the time being.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"The employee making search shall prepare a deed in\nduplicate containing the description of the objects connected with the\noffence found during search, the scene and circumstance thereof,\ngive one copy of the deed to th e concerned person and retain the\nother copy in the case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If a person or place to be searched is located in the area\nunder jurisdiction of another police office, the investigating authority\nmay make a request in writing to such police office to make search\nof such person or place.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If a request is made pursuant to sub-section (7), a police\nemployee of that police office whose rank is at least assistant sub -\ninspector of police shall search such person or place, prepare a deed\nreferred to in sub-section (1) and send it to the authority making such\nrequest.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"Notwithstanding anything contained in sub -section (7),\nif the investigating authority thinks that any evidence could be\nconcealed or destroyed in the event of making a request in writing to\nsuch police office, the investigating authority himself or herself may\ngo to the place or site where the p erson to be searched is staying and\nsearch such person or place pursuant to this Section and shall give\ninformation thereof to the concerned office or police office.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"If the authority making search pursuant to t his Section\nwishes to take with him or her any object connected with the offence\nand found in the course of making search, he or she may do so only\nafter giving a receipt thereof to the concerned person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"Except where there is a reasonable ground to believe\nthat any exhibit or evidence may be concealed or destroyed or the\nsuspected person may flee or escape if search of any place is not\nmade immediately, the search of a house owned by any person shall\nbe made any time from the sunrise to the sunset.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(12)","title":null,"content":"Where the authority making search seeks an entry into\nany house or place in the course of making a search pursuant to this\nSection, the owner of the house or place or the person who has taken\ncharge of such house or place or any other person residing there for\nthe time being shall allow such authority to enter into such house or\nplace, by opening its gate or door or in any other manner, and if such\nentry is denied, the authority making search may enter into the house\nor place by breaking the key, if any, or breaking or demolishing only\nsuch parts of the windows, doors, roofs , walls etc. of such house or\nplace as may be necessary to enter into such house or place and in\nsuch manner as to cause minimal loss or damage as far as possible.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(13)","title":null,"content":"If, for any reason, it is not possible for a person who has\nentered into any house or place to exit from it in a normal way after\nmaking search pursuant to this Section, the person may exit from it\nby breaking or demolishing any such part of its windows, doors,\nroofs, walls etc. as may be necessary to exit from it and in such\nmanner as to cause minimal loss or damage as far as possible.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(14)","title":null,"content":"Search must be made without carrying any objects other\nthan the clothes put on by the authority making search and any\nemployee deputed to assist the authority in making search and the\npersons in whose presence the search is made pursuant to sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"of Section 16 and the items to be used in the operation of search;\nand the concerned person may, if he or she so wishes, s earch the\nbody of any such authority, employee or other persons prior to the\ncommencement of the operation of search.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(15)","title":null,"content":"The authority who is competent to search any person,\nhouse or place pursuant to this Section shall, prior to making such\nsearch, show his or her identity card to the concerned house owner,\nplace owner or person to ensure that he or she is the authority\ncompetent to make such search.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"19","title":"Requirement of presence in executing deeds","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The investigating\nauthority shall, in preparing a d eed on the scene of crime, describing\nthe real and actual facts of the scene of such offence, prepare it in\naccordance with sub-sections (2), (3) and (4) of Section 8.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In preparing a deed on the scene of crime pursuant to\nsub-section (1) or searching any person, object or place or examining\nthe corpse, in the case of homicide, or, in the case of commission of\nany other offence, in preparing necessary deeds depending on the\nnature of such offence, such deed or deeds shall be executed in the\npresence of at least two local people available at that place and one\nmember of the Local Level or if no such member i s available, one\nemployee of the government office, if any, and the accused persons\nwho are found out as well as the informant.\nProvided that such de ed on the scene of crime shall not be\nconsidered as unduly executed by the reason only that it has not been\nexecuted in the presence of the accused or the informant.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In making a search of any place under the ownership or\ncharge of a person, the search shall be made in the presence of such\nperson also, if available.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"20","title":"Examination of corpse to be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If information is received\nthat a person is dead due to culpable homicide or accident or suicide\nor in an unusual situation or in any other suspicio us circumstance,\nthe investigating author ity shall immediately go to the place where\nthe corpse is located and examine the corpse.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In examining the corpse pursuant to sub -section (1), a\ndeed containing, as far as practicable, the following matters , in the\nform referred to in Schedule-14, and take photographs of the corpse\nand the concerned scene in a manner to describe the actual situation\nof the corpse:\n(a) The identifying description of the corpse,\n(b) The ci rcumstances of the place where the corpse is\nlocated and of the corpse,\n(c) If any wound, injury, bruise, abrasion or mark is seen on\nthe corpse, the description of each wound, injury,\nbruise, abrasion or mark including the part where such\nwound, injury, bruise, abrasion or ma rk is seen, the\nnumber, length, breadth, depth and description thereof,\n(d) Description of the instrument causing such death and\nthe related description seen on the corpse, other than\nthose mentioned in clause (c),\n(e) Any such other sign or symptom seen on the corpse that\ncould be helpful in finding out the cause of death,\n(f) Description of other significant matters, if any.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The concerned investigating authority shall, upon\nexamining the corpse pursuant to sub -section (1), send the corpse to\na government medical doctor or an expert designated in that behalf\nby the Government of Nepal or a licensed medical doctor for post -\nmortem, at the government expenses.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The Government of Nepal shall make available to the\nconcerned police office such expenses as required for post -mortem\npursuant to sub-section (3).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A report of post -mortem conducted pursuant to sub -\nsection (3) shall be prepared in the form referred to in Schedule-15.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Notwithstanding anything contained in sub -section (3),\nif, after the execution of the deed on examination of the corpse\npursuant to sub -section (1), it does not appear , from such\nexamination of corpse, that the death was caused as a result of the\ncommission of any offence or in a suspicious circumstance , and the\ninvestigating authority concludes that the post mortem of the corpse\nis not nec essary, he or she shall execute a memorandum thereon,\nsetting out the reasons for the same, in the presence of distinguished\nlocal persons and retain the memorandum in the case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If it is not possible or seems impossible to examine the\ncorpse because of the corpse being decayed or rotted, the concerned\ninvestigating authority shall execute a deed setting out that matter, in\nthe presence of local distinguished persons.\nProvided that if, in spite of the corpse being decayed or rotten,\nthere is a situation that the cause of death can be found out by other\nexamination of the corpse or any of its parts , such other scientific\nexamination may be carried out.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"After the completion of post mortem or execution of the\ndeed pursuant to sub -section (6 ), the concerned police employee\nshall hand over the corpse to the successor to the deceased and get a\nreceipt from the latter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"If the successor refuses to receive the corpse pursuant to\nsub-section (8) or no successor is present or the successor cannot be\nidentified, the concerned police employee shall perform the last rites\nand rituals of the corpse at government expenses.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"If the investigating authority deem s it appropriate to be\naccompanied by the concerned expert in the course of examining the\ncorpse or conducting post mortem or collecting any other proof or\nevidence, he or she may also be accompanied by such expert.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"If the expert or medical doctor exa mining a corpse or\nconducting the post mortem pursuant to this Section thinks that it is\nnecessary to conduct the post mortem by a team consisting of more\nthan one expert in order to find out the real cause of death or the\ninvestigating authority thinks th at it is necessary to have the pos t\nmortem conducted by a team of experts in order to find out the cause\nof death of a person, the post mortem may be conducted by such\nteam.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"21","title":"Examination of physical evidence to be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If the\ninvestigating authority thinks, in view of the nature of any offence,\nthat evidence related to that offence can be obtained if the\nexamination of the blood, semen , hair or any other part of body of\nthe concerned person or arms, thing or object, DNA or any other\nmatter is conduc ted in order to find out the offender, he or she may\ncause the examination of such blood, semen, hair or other part of\nbody, arms, thing, object, DNA or any other physical evidence to be\nconducted by a government medical doctor or recognized laboratory.\nProvided that if it is required to examine any bodily organ of a\nwoman, such examination shall be caused to be conducted by any\nfemale doctor, if available, and by a male doctor in the presence of a\nwoman if such female doctor is not available.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The concerned person shall assist the investigating\nauthority in the provision of a sample of blood, semen, hair or organ,\narms or object required for the examination pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":".","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The concerned doctor or laboratory shall prepare a\nreport of examination conducted pursuant to sub-section (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"22","title":"Examination of injury","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If any person sustains any injury,\nwound, bruise, abrasion etc. on his or her body in an incident that\nhappened because of hurt and makes application for the examination\nof injury or the investigating authority so requests, the government\ndoctor or health worker shall examine his or her injury, wound,\nbruise, abrasion etc. and prepare a report of such examination in the\nform referred to in Schedule-16.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, in addition to that mentioned in sub -section (1), a\nperson held in detention in the course of investigation or any other\nperson on his or her behalf makes an application, accompanied by\nthe reasonable ground, stating that evidence may be found, upon the\nexamination of his or her body, that he or she has been subjected to\nhurt or torture or an y other offence has been committed to him or\nher, the court may order that physical examination of such person be\nconducted by a government doctor or a doctor or health worker\ndesignated by the Government of Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Even i n conducting physical examina tion pursuant to\nsub-section (2), injury examination referred to in sub -section (1)\nshall also be conducted.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The concerned doctor, expert or laboratory shall provide\na report of examination c onducted pursuant to Sections 20, 21 and\nthis Section to the concerned office or investigating authority no t\nlater than three days after the date of such examination, excluding\nthe time required for journey.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If it appears that a person held in detention was\nsubjected to hurt or torture as referred to in sub -section (2), the court\nshall order the concerned police office to have treatment of the\nperson so subjected to hurt or torture, provide an interim relief to him\nor her and take, in accordance with law, departmental action against\nthe person who so subjected him or her to hurt or torture.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If the investigating authority does not write to the\ngovernment doctor or health worker for the examination of inju ry\npursuant to sub -section (1), the concerned person may make a\npetition explaining that matter to the court, and the court may, if such\npetition is made, send a precept to the government doctor or health\nworker for such examination.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"23","title":"Expert opinion may be obtained","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"T he investigating authority\nmay, if he or she so deems necessary, be accompanied by any expert\nin the course of investigation or seek opinion of any expert on any\nmatter connected with the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"It shall be the duty of the concerned expert to give his or\nher opinion if he or she is so asked pursuant to sub-section (1).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The expert opinion given pursuant to sub -section (2 )\nshall be recorded in the case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If any expert referred to in this Section is a non -\ngovernmental person, the Government of Nepal shall provide\nexpenses to be incurred in the obtaining of his or her service.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if the investigating authority, for the reason of the sensitivity\nor complexity of any case, considers appropriate to do so, and makes\nrecommendation for obtaining the opinion of the medical bo ard or\nany other expert i n such case, the Government of Nepal may form\nsuch board.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If a board is formed pursuant to sub -section (5), the\nboard shall give opinion on that matter.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"24","title":"Identification to be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If it is necessary to identify any\nperson in connection with any case, a police employee whose rank is\nat least assistant sub -inspector of police shall cause such\nidentification to be made.\nProvided that the proceedings of a case shall not be affected\nsubstantially by the reason only that such identification has not been\nmade.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In having identification pursuant to sub -section (1), the\nperson to be identified shall be kept in a place where such person\ncannot be seen and looked, and at least four persons who resemble to\nsuch person in age, color or physical structure shall , as far as\npracticable, be dressed uniformly, with whom such person shall be\nkept together, and ev ery person making identification shall make\nidentification separately.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The form of identification shall be as referred to in\nSchedule-17.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The matter as to whether the person making\nidentification was able to make identification pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"shall be recorded and retained in the case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A police employee whose rank is at least assistant sub -\ninspector of police may cause to be made the identification of any\nexhibit, thing or object connected with any case, by executing a deed\non identification.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"25","title":"Police diary to be maintained","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Every police officer conducting\ninvestigation under this Chapter shall maintain a police diary, in the\nform referred to in Schedule-18, in which every proceeding made by\nhim or her in the course of in vestigation shall be recorded\nimmediately.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Such police officer shall record the following matters in\nthe diary maintained pursuant to sub-section (1):\n(a) The date and t ime of receipt of information about the\noffence, and the resume thereof,\n(b) The activities carried out by him or her in the course of\ninvestigation,\n(c) The place or scene which he or she h as visited in the\ncourse of investigation,\n(d) The exhibits, proofs, evidence or other necessary thi ngs\nfound in the course of investigation,\n(e) Details o f the person, if any, arrested in the course of\ninvestigation,\n(f) The name, address of each person whom he or she has\ninterrogated in the course of investigation, and matters\nstated by such person in relation to the offence,\n(g) Nature of the person arrested or inquired,\n(h) Other relevant fact or information obtained in the course\nof investigation of the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The government attorney or court may , as required,\nprocure and examine the police diary maintained pursuant to in sub-\nsection (1).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The authority higher than the concerned investigating\nauthority may, if he or she so wishes, inspect the matters set forth in\nthe diary maintained pursuant to sub -section (1) and also give\nnecessary direction in connection with the investigation.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"26","title":"Advice, opinion may be sought in relation to investigation","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The concerned investigating authority may, in conducting\ninvestigation pursuant to this Chapter, seek advice or opinion of the\ngovernment attorney on any matter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If advice or opinion is sought pur suant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":", the concerned government attorney shall give his or her advice\nor opinion.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If, in giving advice or opinion pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":", the government attorney deems that it is necessary to carry out\nfurther investigation into any matter or to collect further evidence or\nto seize any exhibit, evidence or to inquire any person into any\nmatter, the government attorney may direct the investigating\nauthority to do, or cause to be done, accordingly.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"It shall be the duty of the concerned investigating\nauthority to comply with the direction given pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":".","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"27","title":"Power of the Attorney General to give direction in the course of","content":"investigation: (1) The Attorney General may obtain necessary\ninformation about the inve stigation undergoing into any criminal\ncase to be filed by the Government of Nepal.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, upon having information pursuant to sub -section (1),\nthe Attorney General is of the opinion that investigation into any\ncriminal offence which is a state case is i nsufficient or that any\nspecial measure, method or mode required to be adopted or followed\nhave not been adopted or followed during investigation into such\noffence or that further investigation should be conducted into such\noffence, he or she may, at any t ime, give direction to the\ninvestigating authority or the departmental head of that authority in\nrespect of the investigation.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"It shall be the duty of the concerned authority to comply\nwith the direction given pursuant to sub-section (2).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"28","title":"Records of first information reports to be maintained","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The\ninvestigating authority, in making petition to the court for a remand\nto hold the arrested person in detention pursuant to sub-section (3) of\nSection 14, shall submit one copy of the first information report or\ninformation, which was made or giv en to the police office or the\ninvestigating authority , to the adjudicating authority through the\ngovernment attorney.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The adjudicat ing authority shall maintain separate\nrecords of the report or information referred to in sub-section (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"29","title":"Power to forward the matter to the concerned body","content":"Notwithstanding anything contained elsewhere in this Act, if, in the\ncourse of investigating into any offence under Schedule -1 or\nSchedule-2, it appears that the offen ce has to be investigated into\nunder other law, the matter, accompanied by the progress details of\ninvestigation, may be forwarded to the concerne d body or authority\nfor investigation into it.","children":[]},{"tier":2,"nodeType":"rule","identifier":"30","title":"Investigation into offence committed outside Nepal","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If there is\na legal provision that a case can be instituted in a court of Nepal in\nrelation to an offence that was committed or took place outside\nNepal, investigation conducted into such offence by fulfilling the\nfollowing procedures shall, n otwithstanding anything contained\nelsewhere in this Act, be deemed to have been duly conducted under\nthis Act:\n(a) Any investigation conducted in accordance with the\nprovisions of the treaty, if any, concluded with any\ncountry providing that investigation into any criminal\noffence, in respect of which a case may be instituted in a\ncourt of Nepal, can be conducted by the competent\nauthorities of each other country,\n(b) Failing a treaty referred to in clause (a), any\ninvestigation conducted by the investigating authority\ndesignated in that be half by the Government of Nepal,\nby obtaining, through diplomatic channel, consent of,\nand in cooperation with, the competent au thority of the\ncountry where the offence was committed,\n(c) In cases where any investigation cannot be conducted\npursuant to clause (a) or (b), investigation conducted by\nthe competent investigating officer of the country where\nthe offence was committed,\n(d) In cases where even the circumstance referred to in\nclause (c) does not exist, investigation conducted by the\ninvestigating authority of the area where the accused\nwas apprehended or of the area of his or her permanent\nabode if the accused is not apprehended.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the report of or documents related to the investigation\nconducted pursuant to sub -section (1) has been executed in any\nlanguage other than the Nepali language, authentic Nepali translation\nof such documents shall be submitted to the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If it appears from the investigation conduct ed pursuant\nto sub-section (1) that a case has to be filed against any person, the\nconcerned government attorney shall frame a charge sheet and file\nthe case in the court in accordance with this Chapter.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"31","title":"Investigation report to be sent","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"After the completion of\ninvestigation made into any offence under Schedule-1 or Schedule-2,\nthe investigating authority shall prepare an investigation report, in\nthe form referred to in Schedule -19, accompanie d by the originals\nand duplicates of the documents , and exhibits and evidence\ncontained in the case -file, setting out under which law any or all of\nthe persons suspected of committing the offence shall be punishable\nif it appears that there is sufficient evidence to make indictment\nagainst such accused, and setting out the relevant matter if it appears\nthat the offence has not been committed or in spite of the\ncommission of the offence, the accused cannot be traced out or that\nthere is no sufficient evidence to make indictment against any\naccused, and send such report to the concerned government attorney\noffice.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The report referred to in sub -section (1) shall be sent at\nleast fifteen days in advance of the expiry of the statute of limitation\nunder the relevant law in relation to a case not involving a detainee,\nand normally three days in advance of the day for filing a case, also\nhaving regard to the time re quired to make decision of whether or\nnot to institute the case and the time required for preparing a charge\nsheet and filing it in the court, in relation to a case involving a\ndetainee.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Upon receipt of the case -file, together with the\ninvestigation re port pursuant to sub -section (1), the concerned\ngovernment attor ney office shall study the case -file, evaluate the\nproofs and evidence collected in the course of investigation, and send\nit to the Attorney General for decision to or not to institute the case.\nProvided that where the Attorney General has delegated his or\nher power to decide to or not to institute the case to the subordinate\nofficer, such case-file shall be sent to the concerned officer.\nExplanation: For the purposes of this Section, the term\n\"subordinate officer\" means the government attorneys under the\nAttorney General, and this term also includes, unless otherwise\nprovided in the Constitution, any such officer or employee of the\nGovernment of Nepal as authorized by the Attorney General to\ninstitute any other case involving the Government of Nepal as the\nplaintiff.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If, in studying a case -file in connection with making\ndecision of whether or not to institute a c ase pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":", the government attorney deems it necessary to c ollect further\nproof and evidence or conduct further investigation or make further\ninterrogation with any person, the government attorney may direct\nthe investigating authority to collect such proof and evidence or\nconduct such further investigation or mak e interrogation with such\nperson and send the same.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If the government attorney gives direction to conduct\nfurther investigation into the of fence pursuant to sub -section (4), the\ninvestigating authority shall complete further investigation within\nfifteen days of the date of receipt of such direction.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If the investigating authority thinks that further\ninvestigation referred to in sub -section (5) cannot be completed\nwithin the time specified in that sub-section and any person is held in\ndetention, the investigating authority may release such person on\nrecognizance, with or without taking guarantee undertaken by a\nreliable person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If the investigating authority submits a report,\naccompanied by the reason, to the government attorney under this\nSection that a case cannot be instituted against any person , and any\nperson is held in detention in the course of investigation, the\ninvestigating authority shall keep holding such person in detention\nuntil the government attorney makes decision to or not to inst itute\nthe case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nChapter, where decision has been made not to institute a case on any\noffence set forth in Schedule -1 because of the absence of evidence\nbut any significant evidence is obtained subseq uently, investigation\ninto such offence may be conducted again an d the charge sheet may\nbe filed.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-3","title":null,"content":"Prosecution and Filing of Cases","children":[{"tier":2,"nodeType":"rule","identifier":"32","title":"To file charge sheet s","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If, on studying a case-file in the course of\nmaking decision to or not to institute a case pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"of Section 31, and in view of the proof and evidence collected ,\nthe concerned governm ent attorney considers that there is adequate\nevidence for instituting the case, the concerned government attorney\nshall, in relation to a case under Schedule-1 or 2, prepare a charge -\nsheet, setting out the following matters, in the form referred to in\nSchedule-20 and shall submit the charge sheet to the concerned court\nwithin the time limit:\n(a) Full name, surname, address, description, age,\noccupation or business of the accused,\n(b) Name of the father, mother, husband or wife of the\naccused,\n(c) Village Body or Municipality where the accused is\nresiding, ward number, village, str eet, block number, if\navailable,\n(d) Description setting out the actual iden tity of the\naccused, his or her photograph, duplicate copies of his\nor her citizenship or passport, driving licence or other\ndocument indicating his or her actual introduction,\n(e) Biometrics of pointing fingers of both hands of the\naccused,\n(f) If the accused is staying in a rented house, details\nincluding the name, surname and address of the house\nowner,\n(g) The contents of the information related to the offence,\n(h) The particulars of the offence,\n(i) The details of exhibits and evidence in substantiation of\nthe commission of the offence by the accused,\n(j) The charge made against the accused, and the grounds\nthereof and reasons therefor,\n(k) The relevant laws to be applied, and the reasons\ntherefor,\n(l) The demand for punishment to be imposed on the\naccused, and the reasons therefor,\n(m) The amount of compensation, if any, required to be\nawarded to the person who has sustained injury from the\noffence,\n(n) Particulars of other necessary matters, if any, related to\nthe nature of the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A charge sheet to be submitted pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"shall be accompanied by the proofs, evidence, exhibits and\nobjects collected in connection with the offence, and the accused if\nheld in detention.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the law gives any specific name to the offence alleged\nto hav e been committed by the accuse d, the charge sheet to be\nsubmitted pursuant to sub -section (1) shall mention that name in\nconnection with such offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the law in force does not give any name to the offence\npursuant to sub -section (3), name shall be so given to the offence,\nalso having regard to the elements of the offence according to the\nnature of the offen ce, that the accused can clearly understand the\ncharge made against him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If information is received that the accused has already\nbeen sentenced for any offence or the accused should be liable to\nenhanced punishment by the reason that the accused has also been\npreviously convicted of any offence, the charge sheet filed pursuant\nto sub-section (1) shall also mention the date of previous conviction\nof the accused, the name of the court award ing the punishment and\nthe case or if such matter is discovered later, it shall be mentioned as\nand when so discovered.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If the government attorney makes decision not to\ninstitute a case against any person in connection with any o ffence\npursuant to sub-section (3) of Section 31 owing to the fact that the\nevidence and proof collected for the time being in connection with\nthat offence are not sufficient enough to institute the case against that\nperson, and if such offence also involv es a matter of civil liability\nrelated to the loss of and damage to the personal property or amount\nof any person, the government attorney shall give information\nthereof to the informant or the victim of such offence , through the\nconcerned investigating authority.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If, upon receipt of information referred to in sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":", the concerned person may, notwithstanding anything contained\nin the law in force, file a case , if he or she so wishes, within sixty\ndays of the date of receipt of such notice, as if it were an offence\nunder Schedule-4.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If a case is instituted only against any person out of\nmore than one person subjected to investigation pursuant to this Act\nor if investigation has been conducted as if it were a state case and\nthe investigation discloses that such case cannot be instituted as a\nstate case pursuant to this Act but can be instituted under other Act\nand decision is made to that effect or such case can be instituted as\nan individual case, the concerned government attorney shall\nimmediately send information thereof to the concerned High Court\nGovernment Attorney Office and Office of Attorney General.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"Upon receipt of the information pursuant to sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":", the High Court Government Attorney Office shall study such\nmatter and decide to or not to institute the case, and if there appears a\nreasonable reason for instituting the case, it shall give direction,\naccompanied by the reasons therefor, to the concerned government\nattorney to institute the case; and upon receipt of such direction, such\ngovernment attorney shall file a charge sheet or supplementary\ncharge sheet and institute the case against those persons whom the\ncase was not instituted against.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"If the High Court Government Attorney Office decides\nnot to institute the case pursuant to sub -section (9), it shall give\ninformation thereof to the Office of Attorney General.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"Upon receipt of the information under sub-section (10),\nthe Office of Attorney General shall be give necessary direction to\nthe concerned government attorney as to whether or not to institute\nthe case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(12)","title":null,"content":"If information is received under sub-section (8) that case\ncan be instituted under other law and such content is found\nreasonable, the High Court Government Attorney Office shall give\ninformation thereof to the concerned person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(13)","title":null,"content":"Except as otherwise provided in this Chapter, where a\nbail/bond or guarantee has been taken from any person in the course\nof investigation and, upon investigation, decision is made not to\ninstitute the case against him or her, the bail /bond or guarantee so\nfurnished shall be returned to such person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"33","title":"Filing of charge sheet claiming for lesser punishment","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained elsewhere in this Chapter, if the\naccused of any offence assists the investigating authority in the\ncourse of conducting investigation into such offence, the\ninvestigating authority may , in consideration for such assistance,\nrecommend to the government attorney for a reduction in the\nsentence than can be imposed on such accused under the law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a recommendation is received pursuant to sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":", the government attorney may, also having regard to such\nrecommendation, file a charge sheet with conditional claims, with a\nproposal for a reduction in the sentence that can be imposed on the\naccused.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In filing a charge sheet pursuant to sub -section (2), the\ngovernment attorney may file the charge sheet proposing for a\nreduction in the sentence as follows:\n(a) If the accused pleaded guilty of the offence in\nwhole, before the investigating authority or\nprosecuting authority, a reduction of a maximum\nof twenty-five percent of the sentence that can be\nimposed on the accused,\n(b) If the accused pleaded guilty of the offence in\nwhich he or she was also invol ved and assisted in\nrevealing detailed facts as to the offence and the\nother offenders or gang involved in the offence or\nthe principal giving direction to commit the\noffence or in arresting the persons involved in the\noffence or, in the case of an y organized offence\nor offence committed in a group, in locating the\nother persons involved in that offence or the place\nwhere criminal conspiracy of such offence was\nmade, in seizing or forfeiting any motor vehicle,\nmachine, equipment or other object or arms used\nfor the comm ission of such offence, a reduction\nof a maximum of fifty percent of the sentence that\ncan be imposed on the accused.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In order to make a pray for the reduction in the sentence\nunder sub-section (2), the documents contained in the case-file of the\nconcerned case sha ll clearly demonstrate that such accused has\nrendered such assistance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, a pray cannot be made for the reduction in the sentence in\nany of the following offences or circumstances:\n(a) If the accused has once availed of the facility under this\nSection,\n(b) If the accused was sentenced to imprisonment, a period\nof three years has not lapsed after the service of such\nsentence,\n(c) If the accused has already been sentenced for t he same\noffence in which he or she is accused of.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If, after the filing of a charge sheet praying for a\nreduction in the sentence pursuant to sub -section ( 2), the accused\nmakes before the court a deposition that is different from the\ndeposition which he or she has made before the investigating\nauthority or the government attorney or furnishes hostile evidence or\ndenies committing the offence or does not assist in judicial\nproceedings, such accused shall not be entitled to get the facility\nreferred to in this Section.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"In the case referred to in sub -section (6), the\ngovernment attorney shall revoke the reduction of sentence proposed\npursuant to sub -section (1) or (2) and make a petition to the court\npraying for additional sentence, and such petition shall be an integral\npart of the same charge sheet.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"34","title":"Cases on minor offences of specific type may not be filed","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If it\nappears that it is not practicable to file a case on any minor offence\nof any specific type or it does not substantially affect public interests,\nthe government attorney may, with the approval of the Attorney\nGeneral, decide not to file a case against such person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Prior to making decision pursuant to sub-section (1), the\ngovernment attorney shall cause a bond to be executed by such\naccused undertaking not to repeat such offence in the future.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"For the purposes of this Se ction, the words \"minor\noffence of specific type\" means any of the following offences:\n(a) Offence related to pickpocketing involving the\nclaimed amount of less than one thousand rupees,\ncommitted for the first time,\n(b) Offence of begging committed for the first time,\n(c) Any other offence punishable by a sentence of a\nfine not exceeding three thousand rupees or of\nimprisonment for a term not exceeding one month\nor both the sentences, committed for the first\ntime.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Prior to making decision not to institute a case pursuant\nto this Section, the government attorney shall forfeit the claimed\namount of the offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The claimed amount forfeited pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"shall be provided to the person, if any, victimized from the\noffence and, failing such victim, to the victim relief fund established\nunder law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If a case is not filed pursuant to sub-section (1) and such\nperson commits any offence under this Act within three years from\nsuch date, such person shall be liable to the sentence to which the\nsentence that can be imposed on him or her for the previous offence\nshall also be added.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if the government attorney makes decision not to institute a\ncase, the victim party who is not satisfied with such decision may file\na case on his or her own behalf.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If decision is made not to institute a case pursuant to\nsub-section (7), a notice thereof shall be given to the victim\nimmediately; and , for that purpose, the statute of limitati on under\nlaw shall be deemed to commence from the date of receipt of the\nnotice of such decision.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"The concerned government attorney shall provide\ncopies of the documents related to the investigation conducted\npursuant to this Chapter to the person who files a case pursuant to\nsub-section (7).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"35","title":"Additional claim can be made","content":"If, based on the other relevant\nadditional evidence found a fter a case has already been filed in the\ncourt, it appears necessary to make a charge also against other\naccused in that case, in addition to the accused against whom the\ncase has already been filed , or to make additional charge against the\nperson who has already been made accused upon the filing of the\ncase, the government attorney may, setting out the reasons therefor,\ncause further investigation to be conducted, and file a case, making\nadditional claim against the other additional accused also.","children":[]},{"tier":2,"nodeType":"rule","identifier":"36","title":"Alterations in charge sheet s","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If, by the reason that additional\nevidence has been discovered in any case already filed in the court, it\nappears necessary to alter the charge made previously in that case ,\nthe concerned government attorney may, with the permission of the\nAttorney General, make a petition , accompanied by the reasons\ntherefor, to the concerned court of first instance for alteration in the\ncharge sheet.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Upon receipt of such petition, the concerned court may,\nif the contents thereof appear to be reasonable, give order to alter the\nclaim in the charge sheet in accordance with the petition.\nProvided that an order to make such alteration shall be made\nbefore the concerned court of first instance passes judgment.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"37","title":"Power to make order to correct minor errors","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If it is required\nto correct minor errors in a charg e sheet of a case filed in the c ourt,\nthe concerned government attorney may make a petition ,\naccompanied by the reason therefor, to the concerned District Court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, upo n examination of the petition made pursuant to\nsub-section (1), it appears reasonable to correct the errors, the c ourt\nmay make order for the correction of such errors.\nExplanation: For the purposes of this Section, the term\n\"minor errors\" means any typo , typing or printing related errors in\nthe name, surname, age or address of the accused.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"38","title":"Custody of exhibits, evidence and accused","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"In submitting a\ncase-file, along with the investigation report , to the government\nattorney for prosecution, the invest igating authority shall have the\ncustody of the exhibits, evidence connected with the offence and the\naccused and shall , if the concerned government attorney so orders,\nproduce the same before the concerned court at the same time.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Except as provided in sub-section (1), the concerned\npolice office shall , consequent upon the filing of a case in the court\npursuant to this Chapter, produce before the concerned government\nattorney office the additional proof, evidence, object, document or\nexhibit, if any, di scovered in conne ction with the case, and such\ngovernment attorney office shall , upon making necessary\nexamination, submit such document, exhibit or evidence to the court.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"39","title":"To retain safely","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If the government attorney makes decision not\nto institute a case pursuant to sub-section (3) of Section 31, he or she\nshall, as promptly as possible, return the exhibit, evidence and thing\nincluding the case-file to the concerned police office.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The concerned police office shall safely retain the case-\nfile, exhibit, evidence and thing received pursuant to sub -section (1)\nuntil the statute of limitation for instituting the case on such offence\nexpires.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the exhibit, evidence or thing referred to in sub -\nsection (1) is a property of any one, the police office shall return\nsuch property to its owner, upon having a deed executed by him or\nher with a bond to submit such property to the investigating authority\nor court as and when so required.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"40","title":"Copy or information to be given","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The government attorney\nshall give the concerned investigating authority and the accused a\ncopy of the decision, if any, made by him or her not to institute the\ncase pursuant to sub -section (3) of Section 31 and a copy of the\ncharge sheet, if he or she has made decision to institute the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, in any case under Schedule -1 or Schedule -2, the\nconcerned government attorney makes decision to the effect that the\nevidence is not sufficient enough to institute the case, he or she shall\ngive information of such decision to the concerned investigating\nauthority and the authority or office higher in level than such\ninvestigating authority.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"41","title":"Notice to be given to informants or victims","content":"If decision is made\nnot to institute a case in connection with any offence pursuant to sub-\nsection (3) of Section 31, the investigating authority shall, as soon as\npossible, give information the reof, accompanied by the reason\ntherefor, to the informant or victim.","children":[]},{"tier":2,"nodeType":"rule","identifier":"42","title":"Concerned person to be m ade party","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If, while proceeding with\na case, in which the Government of Nepal is plaintiff, filed under this\nAct, it seems that the case does not fall under Schedule -1 or\nSchedule-2 but any other case may be instituted in acc ordance with\nlaw, the court shall make order to that effect and give information\nthereof to the concerned person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the concerned person agrees to take over/continue the\ncase within two months from the date of receiving such information,\nthat person shall be treated as the pl aintiff and the case proceeded\nand adjudicated, based on the case -file of the same case in\naccordance with law.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"43","title":"Filing of cases","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The following authority or person may file the\nfollowing case required to be filed under this Act in the concerned\ncourt:\n(a) The concerned government attorney , in relation to a\ncase related to any offence under Schedule -1 or\nSchedule-2, in the form of a charge sheet,\n(b) The Government of Nepal, con stitutional body, court or\nany public authority, in relation to a case related to any\noffence under Schedule-3, in the form of a compliant or\nreport,\n(c) The concerned person or one who has locus standi to\nfile case , i n relation to a case related to any offence\nunder Schedule-4, in the form of a plaint.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a case is filed pursuant to sub -section (1), such case\nshall be deemed to have been filed under this Act.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"44","title":"Exemption from sentence for making allegation or complaint","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No person shall be liable to sentence for making any allegation or\ncomplaint in connection with any case under Schedule-1, Schedule-2\nor Schedule-3.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything c ontained in sub -section (1),\nif, after the case has been instituted in the court consequent upon\ninvestigation into the case based on the allegation or complaint made\nby any person, standing as a witness and showing any matter,\nevidence or proof to the belief of the Government of Nepal, police\nemployee or other authority, such matter, evidence or proof turns out\nto be false or fabricated on the basis of a report, complaint or\ndeposition made by any person or the deposition of any witness or\ninformant or any other ground, the court may examine the evidence\nfrom the same case-file and do the following:\n(a) To sentence the witness who has made a false statement\nor fabricated depos ition to imprisonment for a term not\nexceeding three months or a fine not exceeding five\nthousand rupees or both the sentences,\nProvided that such sentence of fine or\nimprisonment shall not exceed half the sentence that\nmay be imposed on the offender.\n(b) In the event of the court being of the opinion that the\ninformant has made such false allegation or produced\nfalse or fabricated evidence being guided by\npremeditation or jealousy without the existence of any\nreasonable ground for making the allegation, to cause a\nreasonable compensation, in view of the nature and\ncircumstance of the case, to be paid by such witness to\nthe defendant to be acquitted, in relation to the same\ncase.\nProvided that if such person furnishes a\nreasonable reason for the report or witness made by him\nor her to be prejudicial , no compensation shall be\nawarded.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-4","title":null,"content":"Jurisdiction of Court","children":[{"tier":2,"nodeType":"rule","identifier":"45","title":"Offences to be tried by court having jurisdiction over area where","content":"offences committed: The power to proceed and adjudicate any case\nrelated to any offence shall be vested in the court having jurisdiction\nover the area where such offence is committed.\nProvided that the Government of Nepal may , in accordance\nwith law, constitute a separate criminal court or criminal bench in\nany district for the proceeding and adjudication of such cases.","children":[]},{"tier":2,"nodeType":"rule","identifier":"46","title":"Offences connected with d ifferent areas to be tried by court","content":"having jurisdiction over any of such areas: In the following\ncircumstances, a court having jurisdiction over any area may proceed\nand adjudicate the case:","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"If any act constituting the offence is done partly in one\narea and partly in another, by a court having jurisdiction\nover any of such areas,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"If any act is done in one area and the offence arises in\nanother area as the consequence of such act, by a court\nhaving jurisdiction over any of such areas,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"If different offences take place in different areas from\nthe same event, by a court having jurisdiction over any\nof such areas where any of such offences takes place,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"If an offence is committed in several areas but it cannot\nbe determined in which area the act constituting the\noffence has been completed, by a court having\njurisdiction over any of such areas,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(e)","title":null,"content":"In the case of any offence related to kidnapping or\nhostage-taking, by a court having jurisdiction over\neither the area where such offence is committed or the\narea where the kidnapped person or hostage is held ,\nconcealed or detained,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(f)","title":null,"content":"If the offence is one committed by or against any person\nperforming a journey or one committed in relation to\nany goods being transported from one place to another,\nby a court having jurisdiction over either the area where\nthe offence begins or the area where such person visits\nin the course of journey or the area where such goods\nare seized or traverse,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(g)","title":null,"content":"If the preparation or criminal conspiracy of any offence\nis made in one area but the act constituting that offence\nis accomplished in another area, by any court having\njurisdiction over either the area where such preparation\nor c onspiracy is made or the area where the act\nconstituting such offence is accomplished,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(h)","title":null,"content":"If any offence is committed by means of any letter or\nother communication or information technology, by any\ncourt having jurisdiction over either the area where such\nletter, communication or information was sent from or\nthe area where the same was received,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(i)","title":null,"content":"If an offence is committed along the boundary between\ntwo countries, by the court adjoining to such boarder,\nExplanation: For the purposes of this clause, th e term\n\"boarder\" includes the no -man's land along the\nboundary between two countries.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(j)","title":null,"content":"In the case of an offence related to property, by the\ncourt having jurisdiction over either the area where such\noffence is committed or the area where the property\nearned from the offence is concealed, purchased, sold or\notherwise exchanged,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(k)","title":null,"content":"In the case of any case related to any offence over\nwhich universal jurisdiction can be exercised by virtue\nof any law or any treaty to which Nepal or the\nGovernment of Nepal i s a party , by such court as\ndesignated by the Government of Nepal.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"47","title":"Jurisdiction to try offences committed outside Nepal","content":"If the law in\nforce provides for punishment in res pect of any offence committed\noutside Nepal or on an aircraft or ship registered in Nepal, such\noffence shall be proceeded and adjudicated by the court of the\ndistrict where the person accused of such offence is found and by the\nDistrict Court of the area where such accused has permanent abode,\nif such accused is not found.","children":[]},{"tier":2,"nodeType":"rule","identifier":"48","title":"Proceeding and adjudication of c ases filed in two courts or","content":"bodies: (1) Where a case related to any offence, falling under the\njurisdiction of more than one court, is filed in more than one court ,\nthe case on such offence shall be proceeded and adjudicated by the\ncourt in which it has been filed earlier, and, where the case has been\nfiled on the same day, by the court designated by the court hearing\nappeals from such court where the courts are under the jurisdiction of\nthe same appeal hearing court, and by the court designated by the\nSupreme Court where the co urts are under the jurisdiction of the\ndifferent appeal hearing courts.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nwhere a case related to any one offence, falling under the jurisdiction\nof the court and a quasi -judicial body, is filed in the court and the\nquasi-judicial body, such case shall be proceeded and adjudicated by\nthe court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where a case is one which falls under the jurisdiction of\ncourts or judicial bodies of differen t type s, the case shall be\nproceeded and adjudicated by the respective court or body competent\nunder law, even if it is liable to joint proceedings under sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":", and clause (a) or (c) of sub-section (2), of Section 54. .","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"49","title":"Cases under jurisdiction of both higher and lower court s to be","content":"tried by higher court: If a case related to an offence falls under the\njurisdiction of both the higher and the lower courts pursuant to the\nlaw in force or if a case related to a person or offence which is liable\nto joint proceeding under Section 54, being under the jurisdiction of\nboth the higher and the lower courts, can be so filed or has been filed\nin such courts, the higher court shall have power to try such case.","children":[]},{"tier":2,"nodeType":"rule","identifier":"50","title":"Endorsement to be made in cases of lacking jurisdiction or","content":"failing to meet requirements: (1) If, it appears to the court, from\nthe contents of any charge sheet or complaint made to it, that the\ncourt is not competent to proceed and adjudicate the case complained\nor that the complaint does not meet the requirements, the court shall\nmake an endorsement to that effect in that charge sheet or complaint.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In the case of a complaint which is endorsed pursuant to\nsub-section (1) by the reason of the lack of jurisdiction, where the\nday on which such endorsement is made is the deadline of the statute\nof limitation, the proper court shall , notwithstanding anything\ncontained in the law in force, register the complaint in accordance\nwith law if it is made no t later than fifteen days after that day\nexcluding the time required for journey.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"51","title":"Decision as to jurisdiction and statute of limitation to be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained elsewhere in this Act, where\nthe accused, in making statement in relation to any case , or the\ndefendant, in filing a memorandum of defence, raises a question that\nthe court lacks jurisdiction or the statute of limitation has expired,\nthe court shall initiate other proceedings in such case on ly after\ndeciding such question, and if the case does not appear to fall under\nits jurisdiction, the court shall order that it be presented to the proper\ncourt.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A petition may be made to the appeal hearing court\nagainst the decision made pursuant to sub -section (1), no t later than\nthirty-five days of the date of such decision.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"A question settled pursuant to sub -section (1) or (2)\nshall not be raised again in the appeal hearing court.\nProvided that this provision shall not apply to an interlocutory\norder made in the course of proceeding of the case.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-5","title":null,"content":"Provisions Relating to Preliminary Proceedings of Cases","children":[{"tier":2,"nodeType":"rule","identifier":"52","title":"Commencement of proceedings by the court upon filing of cases","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Except as otherwise p rovided in this Act, the court shall\ncommence proceedings in a case related to any offence upon its\nfiling in the court pursuant to this Chapter.\nProvided that:\n(a) On an offence of disregarding a court order or contempt\nof court in any other manner, the court can proceed the\ncase even upon taking a summary statement or wri tten\nexplanation of the accused or upon any other petition or\nreport,\n(b) Where, in examining evidence in a case by the court,\nany party makes deposition alleging that any evidence is\na forged or fraudulent one, the case may, on the basis of\nthat deposition, be proceeded on the offence of fraud or\nforgery or on the offence of aid and abetment, making\ncriminal conspiracy or accomplice to such offence, from\nthe same case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Except in cases where the proceedings of case have\ncommenced, pursuant to clause (b) of the proviso to sub-section (1),\non the charge of committing any offence referred to in Section 81 or\n82 of Chapter -3, Section s 89, 90, 91, 92, 93, 97, 98 or 100 of\nChapter-4, of Part -2 of the Penal Code, or abetment of, criminal\nconspiracy to, or being accomp lice to, any such offence, the court\nmay, if it thinks justifiable to institute the case on the basis of a\npetition, report, deposition or any separate complaint, proceed the\ncase by executing a memorandum of order, accompanied by the\nreason therefor.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Any case set forth in sub-section (2) shall be proceeded\nand adjudicated in conjunction with the case of the main offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nChapter, except with the written approval of the Government of\nNepal or departmental head, no case shall be instituted accusing any\nemployee of the Government of Nepal of any offence alleged to have\nbeen committed by such employee while acting in the discha rge of\nhis or her official duty.\nProvided that if any employee commits any offence by doing\nany act beyond hi s or her official duty, approval of the Government\nof Nepal or departmental head shall not be required to institute a case\non such offence alleged to have been committed by him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"No case may be instituted against any person on any of\nthe offences under Schedule -1 and Schedule-2, without filing a\ncharge sheet by the government attorney.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Notwithstanding anything contained in sub -section (5),\nthe following person may make a sepa rate complaint for the\nreparation of any injury resulted from any offence:\n(a) A person who has suffered injury from the offence,\n(b) In the case of any matter requiring compliant by a\npublic servant who is deputed elsewhere or abroad in\nthe course of his or her employment, a ny of his or her\nimmediate successors,\n(c) In relation to any act or thing required to be done or\npreserved by any person by virtue of any post, office or\nany other capacity, the person holdin g such post, office\nor capacity,\n(d) In rel ation to any matter i n which a person with\ndisability, child or person over seventy-five years of age\nor person who is physically or mentally inc ompetent is\nentitled to make complaint, his or her successor living\nin the joint family and, failing such successor, any other\nsuccessor or guardian,\n(e) In relation to any offence involving any body corporate,\nthe director, member, administrator or chief executive\nofficer who is authorized to act as the chief of such\nbody.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"53","title":"Complaint may be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Except as otherwise provided in this\nAct, the followin g person may file a complaint in relation to any\noffence in the court:\n(a) A person who has suffered injury from the offence,\n(b) In the case of any matter requiring compliant by a\npublic servant who is deput ed elsewhere or abroad in\nthe course of his or her employment, any of his or her\nimmediate successors,\n(c) In relation to any act or thing required to be done or\npreserved by any person by virtue of any post, office or\nany other capacity, the person holdi ng such post, office\nor capacity,\n(d) In relation to any matter in which a person with speech\nor visual impairment, child or person over seventy -five\nyears of age or person who is physically or mentally\nincompetent is entitled to make complaint, his or her\nsuccessor living in the joint family and, failing such\nsuccessor, any other successor or guardian,\n(e) In relation to any offence involving any body corporate,\nthe director, member, administrator or chief executive\nofficer who is authorized to act as the chief of such\nbody.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A complaint referred to in sub-section (1) shall state the\nfollowing matters and be in the form referred to in Schedule-21:\n(a) The name, surname, address (including the street) ,\ndescription, age, occupation or busi ness of the accused,\nthe name of his or her father, mother, husband or wife,\n(b) The citizenship, passport, driving license of the accused\nor his or her other descriptions that could enable to find\nhim or her easily,\n(c) The Village Body or Municipality where the accused is\nresiding or staying, ward number, village, street, block\nnumber, if available , and other descriptions of the\naccused to the extent of availability,\n(d) If the accused is staying in a rented house, the name,\nsurname and address of the house owner, to the extent\nof availability,\n(e) If the accused has no permanent abode, the name,\nsurname and address of the owner of house where the\naccused is staying,\n(f) The particulars related to the offence,\n(g) Where the offender has committed more than one\noffence at the same time, each count of charge made\nagainst him or her, and evidence related thereto,\n(h) The relevant law to be applied, and the reason for the\nsame,\n(i) The sentence demanded to be imposed on the accused,\nand the ground for the same,\n(j) The injury caused from the offence, and i f\ncompensation has to be recovered from the accused , the\namount of such compensation and the ground for the\nsame,\n(k) Other necessary matters.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Any complaint referred to in sub -section (1) shall be\naccompanied by such number of copies of the complaint as that of\nthe accused and one copy each of the documentary evidence s\nintended to be produced by the complainant.\nProvided that it is not required to submit copies of the\ncomplaint and documentary evidenc es in a case in which the\nGovernment of Nepal is plaintiff.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"54","title":"Cases can be instituted together","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A case may be instituted\nagainst the following persons upon the same charge sheet, report,\ncomplaint, plaint or memorandum of order:\n(a) Persons who commi t the same offence or different\noffences on the same occasion,\n(b) Persons who commit one or more than one offence\njointly or in connivance with each other,\n(c) Persons who commit various offences related to each\nother.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In the case of the persons in volved in the following\noffence, a case may be instituted upon the same charge sheet, report,\ncomplaint, plaint or memorandum of order:\n(a) Attempt, criminal conspiracy to commit, or abetment of,\nthe offence,\n(b) Accomplice to the offence,\n(c) Offence of possessing, buying, selling, giving or taking\nany thing acquired from the offence,\n(d) Offence of possessing , buying, selling, giving or taking\nany thing with the intention of committing the offence, or\n(e) Offence of hiding any person connect ed with the\noffence or aiding such person to abscond.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"55","title":"Separate com plaint to be made in relation to each offence or","content":"accused: Except as otherwise provided in Section s 53 and 54 , a\nseparate charge sheet , complaint or memorandum of order shall be\nframed or made in relation to each offence or accused.","children":[]},{"tier":2,"nodeType":"rule","identifier":"56","title":"Government of Nepal to be made as plaintiff","content":"A case related to\nany of the offences under Schedule -1 and Schedule 2, other than a\ncase instituted upon a co mplaint referred to in sub -section (2) of\nSection 52, shall be proceeded by making the Government of Nepal\nas the plaintiff.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-6","title":null,"content":"Warrant for Arrest and Summons","children":[{"tier":2,"nodeType":"rule","identifier":"57","title":"Summons or warrant for arrest to be issued","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"After a\ncomplaint has been made pursuant to this Act, the court shall, subject\nto this Chapter, issue a summons or warrant for arrest, as required, to\nenforce the appearance of any accused who is not present along with\nthe complaint in a case related to an offence set forth in Schedule -1\nand Schedule- 2.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The court shall , pursuant to sub -section (1), issue a\nwarrant for arrest to enforce the appearance of the accused of the\nfollowing offence:\n(a) A heinous or grave offence,\n(b) An offence of attempt to, abetmen t of, or criminal\nconspiracy to , or being accomplice to, any offence set\nforth in clause (a) or offence of hiding the accused of\nsuch offence or aiding such accused to abscond.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The court may, as required, issue a summons to enforce\nthe appearance of the accused of any offence other than that referred\nto in sub-section (2).\nProvided that if the court has a reasonable reason to believe\nthat the accused has absconded and his or her arrest is unlikely or the\naccused fails to appear before the court within t he time limit\nspecified in the summons, the court may issue a warrant for arrest\npursuant to sub-section (2), in the case of such accused.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The court may issue a warrant for arrest to arrest and\nproduce any person who is bound to produce any document, e xhibit\nor evidence required to be produced before the court if there is a\nreasonable reason to believe that such person is likely to conceal or\ndestruct such document, exhibit or evidence or such person fails to\nproduce such document, exhibit or evidence b efore the court within\nthe time limit specified in the summons issued pursuant to sub -\nsection (3).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"With the issuance of a warrant for arrest pursuant to\nsub-section (4), the court may order any employee or police officer\nto search the place where the document, exhibit or evidence referred\nto in that Section is kept and produce such document , exhibit or\nevidence before the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"The employee or police officer referred to in sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"shall search any place in accordance with Section 18.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"A summons or warrant for arrest to be issued by the\ncourt under this Section to enforce the appearance of an y accused\nshall be accompanied by a notice , in the form referred to in\nSchedule-22, indicating, inter alia, the contents of the complaint.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"58","title":"Procedure for issuing w arrant for arrest","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A warrant for arrest\nto be issued by the court pursuant to this Chapter shall clearly state\nthe full name and address of the person to be arrested and the reason\nfor arrest and be in the form referred to in Schedule-23 in the case of\nan accused person and in the form referred to in Schedule-24 in the\ncase of a witness and other person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A warrant for arrest issued pursuant to sub -section (1)\nshall be signed by the concerned authority and be ar the seal of the\ncourt.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"While issuing a warrant for arrest pursuant to sub -\nsection (1), the warrant for arrest shall be directed to the police office\nof the area where the person to be arrested is or likely to be residing\nor staying.\nProvided that th e court may, if it deems so necessary, also\ndirect a warrant for arrest to the employee of the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"A warrant for arrest issued pursuant to this Section shall\nremain valid unless and until it is executed or canceled by the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A person to whom a warrant for arrest has been issued\nmay be arrested pursuant to such warrant, and while arresting a\nperson in pursuance thereof, the warrant for arrest shall be shown to ,\nand the notice sent pursuant to sub -section (7) of Section 57 shall\nalso be delivered to, that person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"A person who has been arrested under a warrant for\narrest shall immediately be produced before the concerned court as\nsoon as po ssible but no t later than twenty -four hours, excluding the\ntime required for journey.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If the person to be arrested under a warrant for arrest is\nnot found within seven days after the date of receipt by the police of\nthe warrant for arrest, the concerned police office shall continue to\nsearch that person, and, subsequent thereto, proceed to his or her\nhouse and deliver the 35-day-warrant for arrest issued to him or her,\nin the form referred to in Schedule-25, to any of his or her family\nmember of legal age, residing jointly with him or her , and retain a\nreceipt thereof in the case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If the person referred to in sub -section (7) refuses to\nacknowledge such warrant or is not found, a copy of the warrant\nshall be affixed to his or her house in presence of a member of the\nconcerned ward committee of the Local Level, and if such member is\nnot available, in presence of at least two local persons, and one copy\nthereof shall be delivered to the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"A copy of the warrant affixed to the house where the\nconcerned person is residing or staying pursuant to sub -section (8)\nshall also be delivered to the concerned ward office of the Local\nLevel and a receipt of its acknowledgement shall be retained in the\ncase-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"If a warrant is delivered to it pursuant to sub-section (9),\nthe concerned ward office of the Local Level shall, u pon receipt of\nsuch warrant, give information thereof to the concerned person and\nalso affix it to its notice board.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if a person under the warrant for arrest appears himself or\nherself before the court prior to being arrested, he or she shall be\narrested and hearing shall be held under law as to whether or not he\nor she has to be held in detention, and the warrant for arrest issued to\nhim or her previously shall be voided and information thereof given\nto the concerned authority.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(12)","title":null,"content":"If the court comes to know upon a petition by the party\nor through any other means that the person under the warrant for\narrest is staying in any district other than his or her address, the court\nmay also direct the warrant for arrest to the district where he or she is\nstaying.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(13)","title":null,"content":"If any accused does not appear within the time limit\nspecified in the warrant for arrest issued pursuant to this Chapter and\nremains absconded or the actual address of the accused cannot be\ndiscovered or the place where the accused is staying cannot be found\nout, the court may publish a notice , containing the description of\nsuch accused, in any national daily newspaper and affix the notice to\nthe notice board of the concerned court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(14)","title":null,"content":"Upon the publication of a notice pursuant to sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(13)","title":null,"content":", the accused shall be deemed to have duly received the notice,\nand any police office or employee may, at any time, arrest and\nproduce him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(15)","title":null,"content":"The court may, at any time after the affixation of the\nnotice pursuant to sub -section (8), order the attachment of any\nproperty belonging to the person under the warrant for arrest.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(16)","title":null,"content":"If an order for the attachment of property is made\npursuant to sub -section (15), the court shall affix a notice of such\nattachment to its notice board and give information thereof to th e\nconcerned Land Revenue Office or other body or organization.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(17)","title":null,"content":"If it receives a precept from the court for the attachment\nof property pursuant to such -section (16), the concerned Land\nRevenue Office or other body or organization s hall immediately\nattach such property and give information thereof to the court\nmaking such attachment order.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(18)","title":null,"content":"If a property attachment order is made by the court\npursuant to sub -section (15), such property shall, notwithstandin g\nanything contained in the law in force, be deeme d to have been\nattached with effect from the date of such order.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(19)","title":null,"content":"After the person to be arrested pursuant to this Chapter\nappears in the court, the court shall, irrespective of the stage of the\nproceeding of the case, order the concerned Land Revenue Office or\nother body or organization to immediately release the prope rty of\nsuch person which has been attached pursuant to this Section.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"59","title":"Procedure for issuing summons","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"While issuing a summons to\nan accused person pursuant to this Act, the court shall issue it,\nspecifying the date for making appearance in the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The summons referred to in sub -section (1) shall be\nissued to the accused, in the form referred to in Schedule-26, at least\nfifteen days before the date specified for his or her appearance, if it is\na case other than one under Schedule-4, and in the form referred to in\nSchedule-27, giving a time -limit of fifteen days if the case is related\nto an offence set forth in Schedule-4.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where a summons has not been served at least fifteen\ndays in advance of the time -limit specified pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"for making appearance but has been served prior to the time-limit\nspecified for making appearance, and the accused is unable to appear\non the date sp ecified, the accused may make a petition to the court,\naccompanied by the reason for failure to so appear, within fifteen\ndays of the service of the summons, for the specification of anothe r\ntime-limit for making appearance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If a petition is made pursuant to sub -section (3), the\ncourt may so specify another date for his or her appearance that such\ndate falls within a period not exceeding fifteen days from the date of\nsuch petition.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"In the case of an accused who does not appear within\nthe time -limit specified in the summons served pursuant to this\nSection, the court may, if it considers necessary to have the accused\narrested and produced before it, issue a warrant for arrest pursuant to\nthe proviso to sub-section (3) of Section of 57.\nProvided that if the accused makes a petition showing that he\nor she was not able to appear within the specified ti me-limit due to a\nforce majeure event and the court holds the contents of such petition\nto be reasonable, the court may order the extension of the time-limit\nfor a period not exceeding fifteen days , after the termination of the\nperiod of exist ence of the f orce majeure event, excluding the time\nrequired for journey.\nExplanation: For the purposes of this Act, the term \"period of\nexistence of the force majeure event\" means the following period:\n(a) If a person require d to appear before the court had to\nobserve obsequies or mourning on his or her own\naccording to his or her tradition , at the demise of any\none of him or her, a period of seven days, excluding the\ntime required for journey, after the date on which a\nperiod of fifteen days of the death of such person\nelapsed,\n(b) If a person required to appear bef ore the court is a\nwoman and delivered a child, a period of sixty days\nfrom the date of delivery , excluding the time required\nfor journey,\n(c) If the route remained closed due to flood, landslide or\nsnow-fall or means of public transportation did not ply\ndue to declaration of curfew or any other reason during\nthe time-limit specified for appearance before the court,\na period of fifteen days , excluding the time required for\njourney, from the date of resu mption of such route or\nmeans of public transportation,\n(d) If there occurred a calamity such as earthquake or\nvolcano eruption during the time -limit specified for\nappearance before the court, a period of ten days ,\nexcluding the time required for journey, from the date of\noccurrence of such calamity,\n(e) If a person required to appear before the court was\nkidnapped or taken into hostage by any one, a period of\nfifteen days , excluding the time required for journey,\nfrom the date of being released from such kidnapping or\nhostage-taking,\n(f) If a person required to appear before the court, because\nof being unconscious or unable to make movement or\nseriously ill because of any accident, and thereby being\nunable to appear within the time -limit specified for the\nsame, was admitted to a hospital recognized by the\nGovernment of Nepal for treatment, a period until he or\nshe is discharged from the hospital, not exceeding\nfifteen days in the case of a party to a case under\nSchdule-4 and not exceeding three months in the case of\na party to any other case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"In the circumstances referred to in clauses (a) and (e) of\nsub-section (5), the concerned person shall, as far as possible, give a\nnotice thereof to the court immediately.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"60","title":"Summons may be issued in the name of witness","content":"In issuing a\nsummons in the name of a witness pursuant to this Act, the court\nshall issue the summons , stating the necessary matters, in the form\nreferred to in Schedule-28.","children":[]},{"tier":2,"nodeType":"rule","identifier":"61","title":"Service of summons","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The court shall issue a summons in\ntriplicate, and the service of summons shall be executed by any\npolice employee, any employee of the court or any such other\ngovernment office as the court may direct.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A summons issued pursuant to this Act shall, to the\nextent possible, b e served personally on the person summoned, by\ndelivering it to him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Where the person summoned cannot be found , or,\ndespite being found, refuses to acknowledge the summons being\nserved pursuant to sub-section (2), the summons may be delivered to\nany of his or her joint family members, who has completed at least\neighteen years of age.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the concerned person or joint family member is not\nfound or, despite being found, such person or even such member\nrefuses to acknowledge the summons pursuant to such -section (3),\nthe serving employee shall affix one of the duplicates of the\nsummons to the house or house -door of that person in the presence\nof one member of the concerned ward of the Local L evel and of at\nleast two local persons, who as well as the serving employee shall\naffix signature or thumb impression thereon, and deliver one copy\nthereof to the concerned ward committee of the concerned Local\nLevel and submit one copy of the served summons to the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The concerned ward office of the Local Level shall affix\nto its notice board a notice corresponding to the summons received\npursuant to sub-section (4).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If at least two local persons and at least one member of\nthe concern ed ward committee of the Local L evel certify that the\nperson summoned pursuant to sub -section (5) does not reside in the\nplace specified in the summons, the summons shall be returned to the\ncourt, indicating the address of his or her residence, if any,\ndiscovered, and indicati ng the matter to that effect if such address\ncannot be discovered.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If a summons is returned pursuant to sub-section (6), the\ncourt may direct the summons to the place of his or her residence\nand, as required, issue another summons setting out the addre ss, as\nrequired, in consultation also with the plaintiff.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"While serving a summons on any office -bearer or\nemployee of the Government of Nepal or any body corporat e, the\nsummons may be served at the office where such office -bearer or\nemployee is serving.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"Where a summons is received for service pursuant to\nsub-section (8), the chief of such office or body available for the time\nbeing shall serve the summons by delivering one copy of the\nsummons to the concerned office -bearer or employee, and , as far a s\npracticable, cause the other copy to be signed by the concerned\noffice-bearer or employee, stating the manner and date of its service,\nand return that copy to the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"If a summons cannot be served pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":", such summons shall b e affixed to the notice board of the\nconcerned office or body. A report on such affixation to the notice\nboard shall be given to the concerned court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"If, in serving a summons pursuant to sub -section (8) ,\nsuch officer-bearer or employee is on leave, the concerned office or\nbody shall promptly give a notice of such service of summons to\nsuch employee.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(12)","title":null,"content":"If a summons is to be served on any body corporate, a\ncopy of the summons shall be delivered to the central or local office\nof such body, and the receipt thereof shall be submitted to the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(13)","title":null,"content":"If a summons is served at the local office pur suant to\nsub-section (12), the summons shall be deemed to have been served\nat the headquarters of such body.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(14)","title":null,"content":"In serving a summons pursuant to this Sec tion, the\nserving employee shall submit to the court a report containing the\ndate and details of the service.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(15)","title":null,"content":"If any court is required to serve a summons on a person\nwho is residing in any area outside its jurisdiction, the court shall\nsend the summons to the court of that area and cause it to be served\nthrough that court, and that court shall cause the summons to be\nserved in accordance with this Chapter and return a copy thereof to\nthe court issuing the summons.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(16)","title":null,"content":"In serving a summons pursuant to this Section, the\nnotice sent to the accused person pursuant to sub -section (7) of\nSection 57 shall also be delivered or , depending on the situation,\naffixed to the house-door, together with the summons.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"62","title":"Summons may be served t hrough print or electronic","content":"communication media: (1) If any summons cannot be served\npursuant to Section 61, the court may serve the summons by\npublishing the contents of such summons in such national daily\nnewspaper or broadcasting through electronic communication media\nas owned by the Government of Nepal.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a summons is published or broadcast pursuant to sub-\nsection (1), the summons shall be deemed to have been duly served.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"63","title":"Service of arrest for warrant","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The court shall issue a w arrant\nfor arrest in triplicate, and the warrant for arrest shall, if practicable,\nbe served personally on the person warranted.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The person warranted shall acknowledge the warrant for\narrest issued pursuant to sub-section (1)","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the person warranted cannot be found to serve the\nwarrant for warrant being served pursuant to sub -section (1), the\nwarrant may be delivered to any of his or her joint family members\nwho has completed at least eighteen years of age.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the concerned person or any joint family member is\nnot found pursuant to sub -section (3) or, despite being found, such\nperson or family member refuses to acknowledge the warrant, the\nserving employee shall affix one of the duplicates of the warrant to\nthe house -door of that person in the presence of a member of the\nconcerned ward of the Local Level and of at least two local persons,\nwho as well as the serving employee shall affix signature or thumb\nimpression thereon , and deliver one copy thereof to the concerned\nward office of the Local L evel and submit one copy of the served\nwarrant for arrest to the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The concerned ward committee of the Local Level shall\naffix to its notice board a notice corresponding to the warrant for\narrest received pursuant to sub-section (4).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If at least two local persons and at least one member of\nthe concerned ward committee of the Local Level certify that the\nperson to be arrested pursuant to the warrant for arrest issued under\nsub-section (5) does not reside in the place specified in the warrant,\nthe warrant for arrest shall be returned to the court, indicating the\naddress of his or her residence, if any, discovered, and indicating the\nmatter to that effect if such address cannot be discovered.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If a warrant for arrest is returned pursuant to sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":", the court may direct the warrant for arrest to the place of his or\nher residence and, as required, issue another warrant for arrest setting\nout the address, as required, in consultation also with the plaintiff.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"In serving a warrant for ar rest pursuant to this Section,\nthe serving employee shall submit to the court a report containing the\ndate and details of the service.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"If any court is required to serve a warrant for arrest on a\nperson who is residing in any area outside its jurisdicti on, the court\nshall send the warrant for arrest to the court of that area and cause it\nto be served through that court, and that court shall cause the warrant\nfor arrest to be served in accordance with this Chapter and return a\ncopy thereof to the court issuing it.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"If an employee making a report referred to in sub-\nsection (8) makes a report setting out the reason for not being able to\neffect the service of a warrant for arrest in pursuance of the\nprocedures set forth in this Section, the warrant for ar rest issued to\nthe concerned person may , notwithstanding anything contained\nelsewhere in this Section, be served by publishing the warrant in a\nnational daily newspaper owned by the Government of Nepal, and\nthe warrant for arrest so served shall be deemed to have been duly\nserved.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"In serving a warrant for arrest , the notice sent to the\naccused person pursuant to sub-section (7) of Section 57 shall also be\ndelivered or, depending on the situation, affixed to the house -door of\nhim or her, together with the warrant for arrest.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"64","title":"Warrant for arrest or summons may be issued to or served on","content":"accused residing in foreign country: (1) Notwithstanding anything\ncontained elsewhere in this Chapter, if a warrant for arrest is to be\nissued to or a summons is to be served on a person who is accused of\nan offence sub judice in any court and staying or residing in a foreign\ncountry, the warrant for arrest or summons may be issued to or\nserved on such person in accordance with the law in force on mutual\nlegal assistance.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the Government of Nepal receives information as to\nthe service of a warrant for arrest or summons issued pursuant to\nsub-section (1), it shall give such information to the concerned court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a warrant for arrest or summons issued pursuant to\nsub-section (1) cannot be served, such warrant or summons may be\nserved by publishing it in such national daily newspaper as owned by\nthe Government of Nepal or broadcasting it through elec tronic\ncommunication media.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If a warrant for arrest is issued or summons served\npursuant to sub -section (1), such warrant or summons shall be\ndeemed to have been duly issued or served in accordance with this\nAct.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If a warrant for arrest is issued pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"and the police of the concerned country arrests and hands over\nthe accused to any police office, the accused shall be produced\nbefore the concerned court as soon as pos sible but not later than\ntwenty-four hours, excluding the time required for journey.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, nothing shall prevent the institution of proceeding and\nadjudication of a case by the reason only that the warrant for arrest or\nsummons could not be issued to or served on any person staying or\nresiding in a foreign country, in accordance with this Section.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"65","title":"Special provisions relating to absconding persons","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"In the case\nof a person against whom a warrant for arrest has been issu ed\npursuant to this Chapter but who is not arrested because of not being\nfound or in the case of a person who is absconding and failing to\nappear before the court, the following matters shall be dealt with as\nfollows, with effect from the following day of the expiry of thirty\ndays after the date of issuance of such warrant to the day on which\nhe or she appears before the court:\n(a) If such person is an incumbent office -bearer or\nemployee of the Government of Nepal, State\nGovernment, L ocal Level , constitutio nal body or any\ngovernment office, a body corporate , educational or\nacademic institution under full or partial ownership or\ncontrol of the Government of Nepal, State Government,\nLocal Level, or any other public body, he or she shall be\ndeemed to have ipso facto been suspended from his or\nher office,\n(b) If an attachment to the property belonging to such\nperson has not been effected pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(15)","title":null,"content":"of Section 58, the attachment of the immovable\nproperty belonging to him or her s hall be effected\npursuant to that sub-section,\n(c) If it is requir ed to renew any industry, trade or business\nor income tax registration firm, license, industry etc.\nheld in the name of , or under sole ownership of, such\nperson, the act of renewal shall automatically be\nwithheld,\n(d) Transaction on secur ities held in the name of such\nperson shall ipso facto be withheld,\n(e) Facilities such as salary, allowance, gratuit y and\npension receivable by such person in accordance with\nlaw shall be deemed to have ipso facto been withheld,\n(f) Any interest, royalty or facility to be acquired by such\nperson from any intellectual property right such as a\npatent, design, trademark and copyright shall be\nconsidered to have ipso facto been withheld,\n(g) If any bank account held in the n ame of such person is\nknown, and a request is made to withhold the\ntransaction of such account, such bank account shall be\nconsidered to have ipso facto been withheld,\n(h) If it is so requested not to provide a citizenship\ncertificate, passport or land own ership registration\ncertificate to such person in accordance with law, the\nconcerned body shall not provide the citizens hip\ncertificate, passport or land ownership certificate to him\nor her,\n(i) If it is known that such person is staying or res iding\noutside Nepal, the extradition proceeding may be\ninitiated if such person can be extradited under a treaty\nto which the Government of Ne pal is a party or under\nthe law in force, and failing such circumstance, in view\nof the gravity of the offence, a request may be made\nthrough the diplomatic channel to the concerned country\nor relevant international organization to arrest such\nperson.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The court shall give a notice thereof to the concerned\nauthority or body in order to make effective the provisions referred\nto in sub-section (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"66","title":"Process may be served at court","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything\ncontained elsewhere in this Chapter, any process or notice issued by\nany court to the following person may, in the following\ncircumstance, be serv ed by delivering it to such person at the court\nitself:\n(a) In the case of an employee or office -bearer of the\nconcerned court, at the time when he or she\nmakes attendance in the court,\n(b) In the case of a party who is remanded on\nrecognizance in another case in the concerned\ncourt, at the time when the party appears on the\nappointed date for appearance,\n(c) In the case of an attorney who represents any\nparty in any case in the concerned court, at the\ntime when the attorney appears for such\nrepresentation,\n(d) In the case of a law practitioner who appears in\nthe concerned court in the course of law practice,\nat the ti me when he or she appears in the course\nof such practice, or\n(e) In the case of a person who appears as a witness,\nat the time when he or she appears in that\ncapacity.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a process or notice issued by the court in the name of\nany person referred to in sub -section (1) is tendered for delivery\nwhen the person appears in the concerned court, the person shall\nreceive it.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If any person refuses to acknowledge such process or\nnotice tendered for delivery pursuant to sub -section (2), the process\nserver shall give a report thereof to the concerned court immediately.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the content of the report made pursuant to sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"seems to be reasonable, the court shall make an order to prevent\nsuch person from representing a party, receiving the appointed date\nfor appearance in capacity of an attorney , doing law practice or\nmaking deposition in the capacity of witness in the court un til he or\nshe acknowledges such process or notice.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-7","title":null,"content":"Provisions Relating to Detention, Bail and Guarantee","children":[{"tier":2,"nodeType":"rule","identifier":"67","title":"To hold the accused in detention","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If, based on the evidence\navailable for the time being, any person accused of the following\noffence appears to be guilty of the offence or there is any reasonable\nground, based on such evidence, to believe that such person is guilty\nof the offence, the court may remand such person in detention for\ntrial, recording the reason for such detention:\n(a) Any offence punishable by the sentence of\nimprisonment for life,\n(b) Any offence under Schedule-1 or Schedule-2\nwhich is punishable by a sentence of\nimprisonment for a term exceeding three years, or\n(c) An offence of attempt to, abetment of, or criminal\nconspiracy to, or being accomplice to, the offence\nset forth in clause (a) or (b).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nthe court may, i n any of the following circumstances, remand such\naccused in detention for trial as may be punishable by a sentence of\nimprisonment in accordance with law:\n(a) If the accused pleads guilt of the charge made\nagainst him or her before the court,\n(b) If the accused charged with an offence punishable\nby a sentence of imprisonment for a term of one\nyear or more has no permanent abode in Nepal\nand there is a possibility that the accused might\nabscond and might not be apprehended\nsubsequently if he or she is not remanded in\ndetention,\n(c) If the accused , being default in making\nappearance within the time -limit in pursuance of\nthe warrant for arrest issued pursuant to sub -\nsection (1) of Section 58 , has been arrested and\nproduced accordingly, and fails to show any\nsatisfactory reason for being unable to appear in\nthe court,\n(d) If the accused was convicted of an offence and\nsentenced to imprisonment within the period of\nthree years immediately before this instant charge\nagainst him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub -section (1)\nor (2), the court may, in relation to an offence other than that\npunishable by a sentence of imprisonment for a term exceeding ten\nyears, remand on bail/bond or guarantee any accused who is a child\nor infirm due to physical or mental disease or woman with pregnancy\nof more than seven months or the aged above seventy -five years of\nage.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"68","title":"Bail /bond, guarantee or bank guarantee to be taken from the","content":"accused: (1) Except in the case referred to in Section 67, the court\nmay ask for a bail /bond, guarantee or bank guarantee from the\naccused if there exists a reasonable ground for proving the charge\nagainst the accused.\nProvided that the bank guarantee shall be unconditional and\nrenewable at such times as may be specified by the court.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The court shall remand in detention any accused who\nfails to furnish bail/bond, guarantee or bank guarantee p ursuant to\nsub-section (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"69","title":"To remand on recognizance","content":"The case shall be tried by remanding\nthe accused on recognizance to appear on appointed days when the\naccused appears in the court, in any case other than that referred to in\nSections 67 and 68.","children":[]},{"tier":2,"nodeType":"rule","identifier":"70","title":"Additional bail /bond, guarantee or bank guarantee may be","content":"demanded: (1) If it appears subsequently that the bail /bond,\nguarantee or bank guarantee taken from any accused is insufficient,\nthe court may demand additional bail /bond, guarantee or bank\nguarantee from the accused.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the accused fails to furnish such additional bail/bond,\nguarantee or bank guarantee referred to in sub -section (1), the court\nmay remand such accused in detention.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"71","title":"Power to remand in detention or on guarantee at any stage of","content":"proceedings: (1) In the course of examining evidence, the court\nmay, irrespective of the stage of the proceedings of a case, and in the\nlight of the circumstances of the case, remand the accused in\ndetention pursuant to Section 67 or demand a bail/bond, guarantee or\nbank guarantee from the accused pursuant to Section 68; and nothing\nshall be deemed t o prevent the court from remanding the accused in\ndetention or demanding a bail /bond, guarantee or bank guarantee\nfrom the accused subsequently by the reason only that the accused\nwas not remanded in detention or that a bail/bond, guarantee or bank\nguarantee was not taken from him or her earlier.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the court has any reasonable ground to prove that the\naccused remanded in detention pursuant to Section 67 or 68 is not\nguilty of the offence, the court may, irrespective of the stag e of\nproceedings of the case, hear such matter and order the release of\nsuch accused from detention.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"72","title":"Grounds for fixation of amount of bail /bond, guarantee or bank","content":"guarantee: (1) The amount of a bail/ bond, guarantee or bank\nguarantee to be taken pursuant to this Chapter shall be fixed\nreasonably, having regard to the following matters:\n(a) Nature and gravity of the offence,\n(b) Financial status and family condition of the\naccused or the offender,\n(c) Age and physical condition of the accused or the\noffender,\n(d) Whether he or she was previously convicted of\nany offence and sentenced for the same or not,\n(e) Whether he or she has committed several\noffences on the same occasion or not,\n(f) Sentence imposed or imposable on him or her,\nand compensation to be borne by him or her,\n(g) Consequences resulted from the offence,\n(h) Whether he or she has pleaded guilty of the\noffence or not,\n(i) Where the accused is a helpless or infirm person\nor pregnant wo man or woman accompanying a\nbaby whom she breast feeds.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If any party to a case makes a petition to the appeal\nhearing court showing the reason that the amount of a bail/bond,\nguarantee or bank guarantee demanded from any person under this\nAct is lesser or excessive and is not thus reasonable, such court may\nhear the matter and order the alteration or modification in the amount\nof such bail/bond, guarantee or bank guarantee.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"73","title":"Petition may be made to appeal hearing court","content":"A person who is\nnot satisfied with the order of detention, bail/bond, guarantee or bank\nguarantee made pursuant to this Chapter may make a petition to the\ncourt hearing appeal up to one level.\nProvided that in relation to a question as to the illegality of the\norder of detention made in a case involving an offence punishable by\na sentence of imprisonment for life or imprisonment for a term of\nfive years or more, a petition may also be made to the court hearing\nappeal more than one level.","children":[]},{"tier":2,"nodeType":"rule","identifier":"74","title":"Deed to be executed while taking bail /bond, guarantee or bank","content":"guarantee: (1) While taking a bail/bond from any person under this\nChapter, the court shall cause a deed to be executed by such person\nin the form referred to in Schedule-29, containing the condition that\nthe amount of ba il/bond shall be forfeited if such person fails to\nappear at the time and place specified by the court.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While taking a guarantee or bank guarantee pursuant to\nthis Act, the court shall fix the amount of guarantee and take security\nof property equal to such amount.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a person required to furnish a guarantee furnishes the\nsecurity of his or her property, the court shall cause a deed to be\nexecuted by such person in the form referred to in Schedule -30\ncontaining the condition that the amount of guarantee shall be\nrecovered from the property so furnished as security or from any\nother property belonging to him or her if he or she fails to appear at\nsuch time and place as specified by the court.\nExplanation: For the purpose s of this Chapter , the term\n\"guarantee\" also includes a bank guarantee.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If any other person furnishes his or her property as a\nguarantee for the person who is required to furnish guarantee\npursuant to this Chapter, the court shall cause a separate deed to be\nexecuted by that person in the form referred to in Schedule -31\ncontaining the condition that if that person fails to make the accused\nappear at such place and time as specified by the court, the amount\nof that guarantee shall be recovered from the property so furnished as\nguarantee or from any other property belonging to that person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If the value of the property furnished as guarantee\npursuant to this Section decreases subsequently for any reason, the\nperson who has furnished such guarantee shall submit a property\nequal to the decreased value to the court.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"75","title":"Forfeiture of bail /bond","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If a person who has furnished a\nbail/bond pursuant to thi s Chapter fails to appear in the court, the\nbail/bond furnished by him or her shall be forfeited.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If an y immovable property has been furnished as a\nbail/bond pursuant to sub -section (1), the property equal to the\namount to be paid by such person shall be sold or recovered and the\nrest property shall be returned to him or her.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"76","title":"Amount of bail /bond may be returned and guarantee released","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If the court remands the accused in detention pursuant to this\nChapter in a case filed in the court, the bail /bond or guarantee\nfurnished by him or her before detention shall be released.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Except as otherwise provided in this Act, the bail /bond\nor guarantee taken by the court from any accused in the course of the\nproceedings of the case shall be immediately returned or release d to\nthe accused if the accused is ultimately adjudged to be acquitted of\nthe offence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"77","title":"To release from detention where case not adjudged within","content":"specified period: (1) If the case cannot be adjudicated within one\nyear from the first date fixed for the ex amination of evidence in\nrelation to any accused remanded in detention for trial pu rsuant to\nthis Chapter and if such accused is still held in detention, the case\nmay be proceeded and adjudicated by remanding such accused on\nbail/bond or guarantee.\nProvided that:\n(a) This Section shall not apply to any person who is\naccused of an offence punishable by a sentence of\nimprisonment for life or imprisonment for a term\nof ten years or more if such person is held in\ndetention pursuant to Section 67.\n(b) The court may, if it thinks reasonable, proceed\nthe case by remanding a recidivist in detention.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If any court issues order to release any accused pursuant to\nsub-section (1), it shall give information thereof to the appeal hearing\ncourt not later than three days after the issue of such release order.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"78","title":"Maximum allowable period of detention","content":"Notwithstanding\nanything contained elsewhere in this Chapter, no accused shall be\nheld in detention for a period exceeding the maximum term of the\nsentence of imprisonment than can be imposed on him or her if the\ncharge made against him or her is proved.","children":[]},{"tier":2,"nodeType":"rule","identifier":"79","title":"Memorandum of order to be executed","content":"While remanding any\naccused in detention, releasing any accused held in detention or\ntaking a bail /bond or guarantee from any accused or modifying or\naltering such bail /bond or guarantee pursuant to this Chapter or\nreleasing from detention pursuant to Section 77, the court shall\nexecute a memorandum of order to that effect, accompanied by the\nreason for the same.","children":[]},{"tier":2,"nodeType":"rule","identifier":"80","title":"Warrant for detention to be given","content":"While holding any person in\ndetention for any reason whatsoever pursuant to this Act , the\ncompetent authority shall hold such person in detention by giving a\nwarrant for detention in the form referred to in Schedul e-32,\naccompanied by the reason therefor and legal ground of such\ndetention, to that person pursuant to an order for detention made\npursuant to this Chapter.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-8","title":null,"content":"Provisions Relating to Appointed Date","children":[{"tier":2,"nodeType":"rule","identifier":"81","title":"Appointment of date for appearance by assigning reason","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A\ncourt shall , in so doing, appoint the date for appearance upon\nspecifying each proceeding required to be conducted in the presence\nof parties to a case and the proceeding to be carried out on each\nappointed date for appearance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The proceeding specif ied pursuant to sub -section (1)\nshall be carried out on the appointed date.\nProvided that if the specified proceeding cannot be conducted\nfor any reason on the appointed date for appearance, the court may\nexecute a memorandum of order, assigning the reason therefor, and\nappoint another date for appearance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In a case to which the Government of Nepal is plaintiff\nor defendant, the court shall give the concerned government attorney\noffice a notice of such date for hearing or proceeding of the case as\nappointed pursuant to sub-section (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"82","title":"Book of, and receipt of acknowledgment of , appointed date for","content":"appearance: (1) The court shall maintain one book of appointed\ndate for appearance or a separate book for each case div ision, as\nrequired, in the form referred to in Schedule-33.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The concerned employee shall ment ion in the book of\nappointed date for appearance maintained pursuant to sub-section (1)\nthe date appointed for appearance and the purpose for which that\ndate is so appointed and signed it, cause the parties to the case who\nare present to affix signature or thumb impression on it, and maintain\na receipt of acknowledgement of the date for appearance in the form\nreferred to in Schedule-34, to be recorded in the case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If any party does not appear in the court on the date\nappointed for appearance pursuant to sub -section (2), the concerned\nemployee shall record that matter in the book of appointed date for\nappearance, and sign it.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained else where in this\nSection, the Government of Nepal shall not be required to be on\nrecognizance in a case in which the Government of Nepal is plaintiff.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"83","title":"Sheet of appointed date for appearance","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The court shall give a\nsheet of appointed date for appearance to the parties to each case in\nthe form referred to in Schedule-35.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The concerned employee shall state the date appointed for\nappearance and the purpose for which that date is so appointed in the\nsheet referred to in sub-section (1), and sign it.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"84","title":"Appointment of date for appearance to be made in a manner to","content":"be convenient to parties: (1) While appointing a date for\nappearance for any purpose in a case, the court shall appoint such\ndate, as far as practicable, taking into consideration of whether it\nwould be convenient to the parties to the case and the specified\npurpose could be accomplished or not.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While appointing a date for appearance pursuant to sub -\nsection (1), it shall be appointed in accordance with the schedule of\nbusiness specified in relation to the proceedings of the case.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"85","title":"To appear on appointed date for appearance","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Where a date is\nappointed by the court for appearance for any proceeding, the\naccused or defendant shall appear in the court on that appointed date\nfor appearance.\nProvided that if any party to a case makes a petition showing\nthe reason for being unable to appear in the court on the appointed\ndate for appearance , and the court holds such reason to be\nreasonable, the court may order the extension of the expired\nappointed date for appearance for a maximum period of fifteen days,\nat one time or several times no t exceeding two times, excluding the\ntime required for journey.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Where a person required to appear in the court on the\nappointed date for appearance pursuant to sub -section (1) has been\nheld in detention or imprisoned in any manner whatsoever, the\nperson shall send information of that matter to the concerned court\nthrough the prison in which he or she is so held in detention or\nimprisoned.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If information is given pur suant to sub-section (2), such\nperson shall not be deemed to have expired the appoint ed date for\nappearance during the period of such detention or imprisonment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If any person who is held in detention or imprisoned\ngives information thereof to the court pursuant to sub-section (2), the\ncourt may order the concerned prison to produce tha t person at the\ntime of trial.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"86","title":"Consequences of absence of parties on appointed date for","content":"appearance: (1) If the plaintiff does not appear on the date\nappointed for trial and proceeding in any case related to an offence\nunder Schedule-4, the court shall appoint another date for appearance\nin estimation of the time -limit that can be extended by him or her\npursuant to the proviso to sub-section (1) of Section 85.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the party to a case appears on or before the other date\nas appointed for appearance pursuant to sub-section (1) and makes a\npetition subject to the proviso to sub-section (5) of Section 59 ,\nshowing a reasonable reason for being unable to appear on the\nprevious appointed date owing to a force majeure event, the cou rt\nshall extend the appointed date for appearance of him or her and\nadjudicate the case in accordance with law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the party to a case does not appear in the court on the\nother date appointed for appearance pursuant to sub-section (1) and it\nappears or is held from the evidence contained i n the case -file that\nthe defendant has admitted the plaintiff's claims in whole or in part,\nthe court shall adjudicate the case by m aking judgment to such\nextent, and dismissing it to the extent that the claims which do not\nappear or are not held to be admitted by the defendant.\nProvided that where the plaintiff is in attendance but the\ndefendant is absent, the court shall adjudge the case accordingly, by\nexamining all proofs and ev idence adduced by the plaintiff and the\ndefendant.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Even though the accused or defendant does not appear\nin the court subsequent to a deposition or statement of defense made\nin the court pursuant to this Act, the court may proceed and\nadjudicate the case in accordance with law.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"87","title":"Power to issue warrant for arrest and attach property","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained in Section 86 , if any accused\nhas failed to appear on the previous appointed date for appearance,\nthe court may, if it is of the opinion that the accused should be\narrested and produced before it, issue a warrant for his or her arrest\npursuant to Section 58 and order the arrest of , and attachment of the\nproperty of, such accused.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If an order is made pursuant to sub -section (1), the\nconcerned police employee shall arrest the accused , and the\nconcerned Land Revenue Office or other body or organization shall\nattach the property of the accused, in pursuance of such order.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"88","title":"Remaining on recognizance after examination of evidence not","content":"necessary: (1) Notwithstanding anything contained elsewhere in this\nSection, if any party does not wish to remain on recognizance after\nthe examination of evidence, t he party may make a petition to the\ncourt for a leave to that effect.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a petition is made pursuant to sub -section (1) and the\ncourt does not consider necessary to keep him or her on\nrecognizance, it may discontinue his or her recognizance.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-9","title":null,"content":"Provisions Relating to Attorney","children":[{"tier":2,"nodeType":"rule","identifier":"89","title":"Attorney may be a ppointed","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If any party to a case is unable to\nappear in person to file a complaint , memorandum of appeal or\nstatement of d efense, submit evidence, recover the claimed amount,\ncompensation or any other thing in pursuance of judgment or do any\nother necessary act pertaining to the case, that party may appoint an\nattorney on his or her behalf, setting out the reason for the same.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contain ed in sub -section (1),\nno attorney may be appointed in the following circumstance:\n(a) If the case relates to any offence under Schedule-\n1 or Schedule-2,\n(b) If the accused who is required to make deposition\npursuant to this Act has to appear personally in\nthe court to make such deposition,\n(c) If the accused is required to be on remand\npursuant to this Act or is a person who is\nremanded in detention as a consequence of his or\nher failure to furnish such bail /bond or guarantee\nas demanded to be furnished by him or her,\n(d) If the court so thinks necessary on any reasonable\nground and orders the party to a case to appear\npersonally in the court despite the circumstance\nthat an attorney is already or may be appointed,\n(e) Except where a person who is a foreign national\nor whose nationality is not known is in detention\nor has already furnished a bail /bond or guarantee,\nif such person fails to furnish a bail /bond or\nguarantee of an amount equivalent to the sentence\nwhich can be im posed on him or her upon\njudgment in the case in accordance with law,\n(f) If there is any penalty, fine, ten percent fee, five\npercent fee imposed pursuant to a court order is\ndue and payable, upon the party being default in\npayment of the same,\n(g) If the court, showing any reasonable reason to do\nso, has passed an order disallowing the party to\nappoint an attorney.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If any person appoints an attorney in contraven tion of\nsub-section (2), the court shall void such attorney.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Any person having the following qualification may be\nappointed as an attorney:\n(a) Being competent to make contract under the law\nin force,\n(b) Not having been sentenced for for gery, fraud,\ncorruption or any other criminal offence\ninvolving moral turpitude,\nProvided that nothing contained in this\nclause shall prevent any party to a case from\nappointing any of his or her joint family relatives\nas his or her attorney.\n(c) No government claimed amount pursuant to any\ndecision or fee, court fee, penalty or fine payable\nto the court in the execution of judgment being\ndue and payable.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"In appointing an attorney pursuant to sub -section (1), a\npower of attorney shall be executed in the form referred to in\nSchedule-36, stating the following matters:\n(a) Subject matter of the case,\n(b) Full name, surname, address including street, and\nage of the person to be appointed as attorney , his\nor her citizenship number and district of issue of\ncitizenship certificate,\n(c) Matter that the person to be appointed as attorney\ndoes not suffer any disqualification referred to in\nsub-section (4),\n(d) Matter that any penalty, fine, ten p ercent fee and\nfive percent fee imposed pursuant to a court order\nis not due and payable,\n(e) The act authorized to be done by the attorney.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"A power of attorney shall be witnessed by at least two\npersons.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"A power of attorney shall bear signature or thumb\nimpression of the party appointing the attorney and the witnesses.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"90","title":"Person may become attorney of more than one person","content":"simultaneously: A person may become an attorney of more than one\nperson simultaneously.\nProvided that a person who is a n attorney of a party to a case\nshall not also become an attorney of the opposi te party to the same\ncase or a case related to that case.","children":[]},{"tier":2,"nodeType":"rule","identifier":"91","title":"Party may be attorney","content":"In any case involving more than one\nplaintiff or defendant , any one of them may be appointed as an\nattorney.\nProvided that a n attorney of one party to a case shall not also\nbecome attorney of the opposite party to the same case.","children":[]},{"tier":2,"nodeType":"rule","identifier":"92","title":"Powers and duties of attorney","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"An attorney may carry out any\nacts set forth in the power of attorney on behalf of the party\nappointing him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the court makes order to cause the appearance of the\nperson appointing attorney in person , the attorney shall cause such\nperson to make appearance in the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the concern ed person fails to appear pursuant to sub-\nsection (2), the court may void the attorney of such person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"93","title":"Revocation of attorney","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If a party who has appointed an attorney\nwishes to revoke the power of attorney executed by him or her, the\nparty may, at any time, revoke the power of attorn ey and carry out\nacts pertaining to the case in person or appoint another person as his\nor her attorney.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In the event of the revocation of the power of attorney\nand carrying out of acts pertaining to the case by a party in person,\nthe concerned party shall give information thereof through petition to\nthe court.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"94","title":"Not to arrest attorney","content":"No attorney shall be arrested for any\nsentence imposed on , or liability to be borne by , the party upon\npassing judgment in the case.","children":[]},{"tier":2,"nodeType":"rule","identifier":"95","title":"Special provision relating to permission to appoint attorney","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained in clause (a) of sub -section (2)\nof Section 89, a person in the following circumstance may make a\npetition, setting out the matter, to the court for permission to appoint\nan attorney:\n(a) If a person accused of an offence punishable by a\nsentence of imprisonment for a term of three\nyears or less is not held in detent ion and there\narises a circumstance where he or she cannot\nappear on the appointed date for appearance\nbecause of a force majeure event,\n(b) If a woman accused of an offence punishable by a\nsentence of imprisonment for a term not\nexceeding five years cannot appear in the court\non the appointed date for appearance because of\nher delivery or any other reason.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, upon a petition made pursuant to sub -section (1), the\ncourt considers its contents to be reasonable, it may, assigning the\nreasons to be recorded, grant permission to him or her to appoint an\nattorney, with or without specifying the period, subject to the other\nprovisions contained in this Chapter.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-10","title":null,"content":"Provisions Relating to Transfer and Adjournment of Cases","children":[{"tier":2,"nodeType":"rule","identifier":"96","title":"Power to transfer cases","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Supreme Court may, if there exists\na circumstance referred to in clause (1) of Article 134 of the\nConstitution of Nepal, procure a case sub-judice in any High Court\nfrom such Court, and proceed, hear and adjudicate it.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The Supreme Court may, if there exists a circumstance\nreferred to in clause (2) of Article 134 of the Consti tution of Nepal,\nmake an order that a case sub -judice in one High Court be\ntransferred to, and heard and adjudicated by, another High Court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The High C ourt may, if there exists a circumstance\nreferred to in clause (2) of Article 145 of the Constitutio n of Nepal,\nmake an order that a case sub -judice in one District Court under its\njurisdiction be transferred to, and heard and adjudicated by, another\nDistrict Court under its jurisdiction.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Decision as to whether the circumstance requ iring the\ntransfer of the case referred to in sub-section (2) or (3) exists or not\nshall be made on the basis of a petition by the concerned party to a\ncase or information from the inspection or report of the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If there is some reason that any cas e filed in any court\ncannot be heard by the judge of that court pursuant to this Act, the\nconcerned court shall submit a report, setting out such matter, to the\nappeal hearing court, and upon receipt of such report, the appeal\nhearing court may, also consi dering the convenience of the parties,\ntransfer such case to another court of equal jurisdiction that is\nsubordinate to its territorial jurisdiction.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If an order is made pursuant to sub -section (2), such\ncourt shall, in accordance with the order of th e Supreme Court,\nproceed, hear and adjudicate the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Even if any case is adjudicated by another court\npursuant to sub -section (2), (3) or (5), appeal from the judgment\nmade by such court shall lie in the court hearing appeal from the\ncourt where the plaint has been registered originally.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"97","title":"Power to adjourn cases","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If any party to a case, out of the several\ncases filed in the several courts, makes a petition to the concerned\ncourt, showing a reasonable reason that the adjudication of one case\ncannot be, or ought not to be, made until any other case is\nadjudicated, or that judgment of one case will have substantial effect\non the judgment of any other case or if it realizes that matter, on its\nown initiative, in the course of pro ceedings, the court may, for the\nreasons to be recorded, order that such case be adjourned.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If any court passes an order to adjourn any case filed in\nit pursuant to sub -section (1), the court shall adjourn all the\nproceedings of the case, by giving w ritten information thereof to the\nparties to the case, and also give information thereof to the\nconcerned court in which another case is filed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Upon receipt of the information referred to in sub -\nsection (2), the concerned court shall, upon adjudicating the related\ncase filed in it, give information thereof, accompanied by a copy of\nthe judgment, to the court adjourning the case within thirty days after\nthe date of judgment, and upon receipt of such information, the court\nadjourning the case shall resu me the proceeding s of the case by\ngiving a written notice thereof to the parties to the case and\nappointing the date for appearance, and hear and adjudicate the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained in sub -section (3),\nif such parties are also par ties to the case referred to in sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":", the court adjudging the case shall order them to appear in the\ncourt adjourning the case not later than fifteen days.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If two courts hold divergent views on which of the cases\nfiled in such courts shoul d be adjourned, the courts shall send their\nrespective report to the appeal hearing court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"In the circumstance referred to in sub-section (5), even a\nparty to the case may make petition to the concerned appeal hearing\ncourt.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If a report has been sent pursuant to sub-section (5) or a\npetition is made by the party pursuant to sub -section (6), the court\nshall act in accordance with the order of the appeal hearing court, in\nrelation to such case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If the court hearing appeal from the two courts holding\ndivergent views referred to in sub -section (5) is not the same, such\nmatter shall be submitted to the Supreme Court, and it shall be done\nas per the order of the Supreme Court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"If the court so deems necessary, it may give notice to\nand hear the concerned parties before adjourning the case or passing\nan order for adjournment pursuant to this Section.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"98","title":"To adjourn case in the event of failure of accused to appear","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If an accused against whom a warrant for arrest has been issued\npursuant to Section 57 does not appear or cannot be caused to appear\nbefore the court even within thirty -five days after the date of the\nissuance of the warrant for arrest to the accused, the court shall\nadjourn the case in the case of that accused and hear and adjudicate\nthe case, upon taking and examining evidence, in the case of the\nother accused involved in that case.\nProvided that:\n(a) In the case of an accused who does not appear\nsubsequent to a deposition made in or statement\nof defense submitted to the court, the case shall\nnot be liable to adjournment, and the court shall\nadjudicate the case upon taking and examining\nthe proof and evidence adduced by the plaintiff\nand the defendant and such other evidence as the\ncourt thinks reasonable,\n(b) In relation to a case of offence punishable by a\nsentence of imprisonment for a term of three\nyears or less, judgment shall be made in that case\nbased on the appreciation of evidence, also in the\ncase of the accused or defenda nts failing to\nappear in the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If any case is to be adjourned pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":", the court shall postpone all the proceedings of the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a case is adjourned pursuant to sub-section (1) and the\naccused appears or is caused to ap pear in the court prior to the\nadjudication of the case, the court shall revive the proceeding, give\ninformation thereof to the complainant and proceed and adjudicate\nthe case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If an accused does not appear or is not caused to appear\nin the court withi n a period of three years after the date of\nadjournment of the case pursuant to sub -section (1), the court shall\nrevive the case so adjourned and proceed and adjudicate it in the case\nof such accused.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If an accused does not appear or is not caused to appear\nin the court even until the period during which the case can be\nsubject to adjournment pursuant to sub -section (1), the proceeds\nacquired from the auction sale, under the law in force , of the\nproperty attached pursuant to sub -section (15) of Section 58 shall,\nupon the judgment in that case convicting the accused, be credited to\nthe consolidated fund of the Government of Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Where an accused appears or is caused to appear in the\ncourt prior to the adjudication of the case and the accused produces\nany evidence to the satisfaction of the court that the accused could\nnot appear by the reason that he or she was ignorant of the case\ninstituted against him or her, the court shall order that the property\nattached be returned to him or her by deducting or realizing the\nfollowing expenses:\n(a) The e xpenses incurred in attaching the property\nwhere it has not yet been sold,\n(b) The e xpenses incurred in publishing a public\nnotice for his or her appearance in the court or in\nthe case of him or her in any matter related to the\nproceedings of the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if a case filed in a court is adjourned and a report or\ninformation is received that the accused has appeared as a plaintiff or\ndefendant in any other case filed in the same court or in any other\ncourt, such case shall not be deemed to be adjourned, and the court\nmay order such accused to appear in the court to proceed such case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"Such case may be revived, proceeded and adjudicated ,\nin spite of the failure of the accused to appea r in pursuance of the\norder referred to in sub-section (7).","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-11","title":null,"content":"Provisions Relating to Examination of Evidence","children":[{"tier":2,"nodeType":"rule","identifier":"99","title":"Evidence to be produced","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"All of his or her witnesses,\ndocuments, exhibits and evidence s shall be specified in the\ncomplaint by the plaintiff, in the deposition by the accused, and in\nthe statement of defense by the defendant.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Such documents , exhibits and evidences specified\npursuant to sub-section (1) as, by the nature of such documents,\nexhibits or evidence s, should be in his or h er possession or\nobtainable by him or her shall be produced by the plaintiff with the\ncomplaint, by the defendant with the statement of defense and by t he\naccused while making deposition.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub -section (1)\nor (2), the following provisions shall apply to the following matters:\n(a) If the accused, in making deposition, or the\ndefendant, in submitting the statement of defense,\nmakes a request that another date for appearance\nbe appointed for producing any document, exhibit\nor evidence that cannot be produced immediately,\nthe court may appoint another date for appearance\nup to a period of one month,\n(b) In the case of ta king and examining evidence\nrelated to the offence of forgery or fraud pursuant\nto sub -section (3) of the Section 104, the\nprovisions of that Section shall apply,\n(c) If, during the trial of the case, there arises a\ncircumstance requiring the production of any\nadditional evidence in support or rebuttal of any\nnew fact, the concerned party may produce such\nadditional evidence with the permission of the\ncourt.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Any party to the case shall, in producing any\ndocumentary evidence pursuant to sub -section (2), submit such\nnumber of copies of the document as is more by one copy than the\nnumber of opponents.\nProvided that it shall not be required to submit copies of such\ndocument in any case under Schedule-1 or Schedule-2.\nExplanation: For the purposes of this Section, the term\n“copy” means a photocopy or any other copy of a document.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"100","title":"Originals to be returned","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If any document is produced before\nthe court pursuant to sub-section (2) of Section 99, the court shall\ncause its employee to verify whether the copy, submitted pursuant to\nsub-section (4) of the said Section, corresponds to the original or not.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The employee making verification pursuant to sub -\nsection (1) sh all, upon verification, sign each page of the document\nsetting down therein that the copy is true according to the original,\nget the party submitting the document to sign the same and\nauthenticate it with the seal of the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"After the authentication made pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":", such employee shall affix the seal of the court on, sign and date,\nthe reverse side of the original, and thereupon return it to the party\nsubmitting it.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the court so wishes, it may, as required, order the\nconcerned party to re -submit the original of a document returned\npursuant to sub-section (3).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"101","title":"Party to cause attendance of witness","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The concerned party shall\ncause the attendance of any witness of each case filed in the court on\nthe day appointed by the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nif, in any specific case in which the defendants are in attendance at\nthe time when the case is filed, the plaintiff or the defendant or both\nmay produce their respective evidence of witness b efore the court at\nthe time of filing of the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In producing a witness pursuant to sub -section (1) or","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":", the concerned investigating authority or his or her office shall\nproduce the witness of prosecution in any case under Schedule-1 or\nSchedule-2, through the government attorney office.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The evidence of a witness who fails to appear on the\ndate appointed for appearance for the examination of witness\npursuant to sub-section (1) shall not be taken into the case.\nProvided that if the witness fails to appear owing to a force\nmajeure event and the party makes a petition setting out the matter,\nthe court may appoint another date for appearance for the\nexamination of such witness.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If the process of examination of witness has not begun\nby the reason that all defendants to any case set forth in Schedule -1\nor Schedule -2 of this Act are not present, any party may, showing\nthat the production of witnesses cannot be enforced subsequently if\nthey are not produced immediately, request that such witnesses be\nproduced immediately and their depositions recorded.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If a request is made pursuant to sub-section (5) and such\nreason is reasonable, the court may, assigning the reasons for the\nsame, take deposition of such witness immediately.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"The party and oppo site party to a case in attendance\nshall be allowed to make cross -examination of the deposition made\nby the witness pursuant to sub-section (6), and if there does not exist\nsuch situation, the party in attendance subsequently may make\nrebuttal subsequently only to the extent of the contents of the\ndeposition.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"102","title":"Examination of expert witness","content":"If an expert who expresses an\nexpert opinion in any case related to a heinous or grievous offence in\nwhich the Government of Nepal is plaintiff dies or has resided\nabroad for a long time and is not able to return to Nepal or it is not\npossible to examine him or her for any other reason, expert opinion\nmay be obtained from another expert in the same field who is equal\nto or superior to such expert witness.","children":[]},{"tier":2,"nodeType":"rule","identifier":"103","title":"Cross e xamination of the co-accused","content":"If, i n examining eviden ce\npursuant to this Chapter, any co -accused makes accusation aga inst\nanother co-accused, such co-accused may make cross-examination to\nthe extent of such accusation.","children":[]},{"tier":2,"nodeType":"rule","identifier":"104","title":"Provisions relating to documentary evidence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The court shall\ncause the parties to a case to produce the originals of documentary\nevidence on the date appointed for appearance for examining\nevidence and show the document produced by one party to the other.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the other party makes a plea that the document sh own\npursuant to sub -section (1) was made by means of forgery or fraud,\nthe court shall set down such plea and record the deposition of such\nparty.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub -section (2),\nif, in the process of showing any documentary evidence produced by\none party to the other party, the other party, mentioning that he or\nshe is not able to confirm immediately whether such document is\ngenuine, forged or fraud, makes request for time for that purpose, the\ncourt may, as required, appoint a date for not more than seven days,\nand shall give informa tion thereof to the other party, and record the\ndeposition of that party on that appointed date and also examine the\nevidence produced by that party in that connection if that party states\nthat the document is forged or fraud.\nProvided that in the case of a party wh o is absent or not\nrepresented on the date appointed for appearance for the examination\nof evidence, it shall not be necessary to show the document to, or\nrecord the deposition of, that party pursuant to this Section.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained in sub -section (3),\nif any party, due to a force majeure event, remains absent on the date\nappointed for appearance for confirmin g whether a document is\ngenuine or forged, and if the party or his or her representative\nappears within fifteen days of the appointment of such date and\nwishes to express any matter about that document, such party or\nrepresentative shall be given an opport unity to make expression\naccordingly.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"105","title":"Document named as forged or fraud to be kept in the case -file","content":"In the process of showing the original of a document produced by\none party to the other party pursuant to sub -section (1) of Section\n104, if the other party names it as a forged or fraudulent document,\nthe reverse side of such original shall be signed by b oth the parties,\nby the concerned employee and bear the seal of the court and\nthereupon be sealed and recorded in the case -file safely and if there\nis no space to affix signature or thumb impression , separate paper\nshall be added to the deed with signature or thumb impression at the\njoints.","children":[]},{"tier":2,"nodeType":"rule","identifier":"106","title":"Witness to be examined on fixed day","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The deposition of all\nwitnesses in attendance on the date appointed for appearance for the\nexamination of witness shall be taken; and only where it is not\npossible because of the time factor to complete the taking of the\ndeposition of all witnesses in attendance on that day, the deposition\nof such witnesses shall be taken on the next day on which the court\nremains open.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Prior to making a deposition by a witness who appears\nto make such deposition pursuant to sub-section (1), the witness shall\ntake an oath that he or she will state not ing but the truth, in the form\nreferred to in Schedule -37 in a manner to be heard by othe rs, and\nsuch oath shall be recorded in the concerned case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The deposition of a witness taken down shall be\nrecorded in the form referred to in Schedule-38.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"107","title":"Power to examine witness on commission","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding\nanything contained elsewhe re in this Chapter, if a witness is in a\nplace outside the jurisdiction of the court in which the case is filed or\nthe attendance of such witness cannot be procured for any reason\nand, in view of the gravity of the case, it so appears necessary to\nexamine such witness on commission, the court shall give\ninformation thereof to the parties to the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If any party to the case so desires, the party may make a\npetition, accompanied by the reasons, to the court that any\ninterrogatories which the party wish es to be asked to the witness be\nincluded in the commission referred to in sub-section (1).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If any petition is made pursuant to sub -section (2) and\nthe court deems reasonable to have such interrogatories included in a\ncommission, it may order that such interrogatories be also included\nin the commission; and the interrogatories of the commission shall\nbe framed accordingly.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The form of a commission shall be as set forth in\nSchedule-39.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If, in examining a witness on commission pursuant to\nsub-section (1), any party to the case so desires, the party may appear\nin the court to which the commission is directed and examine, cross -\nexamine or re -examine the said witness in accordance with the\nprevailing law on evidence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"108","title":"Deposition to be taken before bench","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The deposition of a\nwitness to be taken pursuant to this Act shall be taken before the\nbench of the judge.\nProvided that while taking the deposition of a witness who is\nunable to appear before the court due to physical infirmity, the judge\nhimself or herself may proceed to or send an officer employee\nsubordinate to him or her to the place where such witness is residing\nor staying, and the evidence of such witness shall be taken by the\njudge or by such employee in the form of deposition.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While so taking the deposition of a witness pursuant to\nsub-section (1), the concerned parties to the case shall be given\ninformation thereof and also provided with an opportunity to make\nexamination pursuant to sub-section (5) of Section 107.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"109","title":"Witness may be examined through video conference","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If it is\nnot possible to produce before the court a witness required to be\nexamined pursuant to this Chapter because of the witness being\nphysically infirm or a child or for security reason, the concerned\nparty may, setting out that matter, make a petition to the court for the\nexamination of such witness through video conference.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the court makes an order for the examination of any\nspecific witness through video conference, the witness shall be\nexamined accordingly.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a petition referred to in sub -section (1) is made and\nthe reason set forth therein seems to be reasonable or the court makes\nan order pursuant to sub -section (2), the court may, notwithstanding\nanything contained elsew here in this Act , examine such witness\nthrough video conference.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In making video conference pursuant to sub -section (3),\nthe concerned party to the case may, with the permission of the\ncourt, appear before such conference room and examine, cross -\nexamine or re-examine the witness.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"In examining a witness pursuant to sub -section (3),\narrangement shall be made to record the matters expressed by such\nwitness, and the court shall maintain records of the video conference.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"The record of examination of a witness t hrough video\nconference shall be main tained in the form referred to in Schedule-\n40.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"110","title":"Demeanor, appearance etc. of witness may be recorded","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The\njudge may record such remarks as he or she perceives material\nrespecting the demeanor of a witness whilst under examination, and\nsuch remarks may include how was the behavior and appearance of\nthe witness, whether the witness was excited or disappointed while\nanswering the questions put to him or her and what the reflection\nwas as to the truth or untrut h of the replies made by him or her from\nhis or her facial expression.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The note made pursuant to sub -section (1) shall be\nsigned by the judge and kept in the case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The judge may take into consideration of the note\nreferred to in sub -section (1) while making appraisal of the\ndeposition of the witness as evidence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"111","title":"Witness once examined not to be re-examined","content":"A witness who has\nonce been examined shall not be examined again.\nProvided that if any matter that is essential to be inquired into\nwith such witness has been omitted and the judge, assigning the\nreasons thereof, make an order to that effect, such witness may be\nsummoned and examined again.","children":[]},{"tier":2,"nodeType":"rule","identifier":"112","title":"Summons or warrant for arrest may be issued to witness ought","content":"to be examined: (1) A party to the case may make a petition,\naccompanied by the reasons for the same, that a summons be issued\nto enforce the attendance of any witness who is related with criminal\ncase in which the Government of Nepal is plaintiff but who does not\nappear on the day a ppointed by the court for appearance for the\nexamination of evidence and the examination of such witness is\nexpedient in view of the gravity of the offence or the production of\nany document or exhibit by such witness.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a petition referred to in sub-section (1) is made and\nthe court considers such petition to be reasonable and perceives that\nthe examination of such evidence is necessary, the court may\nsummon such witness to appear before the court within a maximum\nperiod of fifteen days and examine him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a summons is issued pursuant to sub-section (2), such\nwitness shall appear within the specified time -limit, except for a\nreasonable reason.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If a witness fails to appear within the time -limit\nspecified pursuant to sub-section (3), the court may impose a fine not\nexceeding two thousand rupees on such witness , issue a warrant for\narrest and take deposition of such witness when he or she is so\narrested and brought before it.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If any witness is not found or cannot be arrested even\nupon the issuance of a warrant for arrest pursuant to sub -section (4),\nthe court shall pass judgment in the case, awarding a sentence of\nimprisonment for a term not exc eeding forty-five days, based on the\nevidence examined, subject to the enforcement of the sentence as and\nwhen such witness is arrested or found.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"A summons or warrant for arrest issued pursuant to this\nSection shall be served pursuant to Chapter-6.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"113","title":"Daily and travel allowance and security to be provided to","content":"witness: (1) The concerned police office shall provide witnesses ,\nwho appear before the court, on behalf of the G overnment of Nepal,\nin any case related to any offence under Schedule-1 or Schedule -2,\nwith such daily and travel allowance as is receivable by the non -\ngazetted first class government employee , and expert witnesses with\nsuch daily and travel allowance as is receivable by the gazetted third\nclass government employee under the law in force.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If any government employee appears before the court as\na witness or expert, the office where the employee is serving shall\nprovide him or her with the daily and travel allowance receivable by\nsuch employee under the law in force.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The Government of Nepal shall make necessary\narrangement for the security of a witness referred to in sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":".","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"114","title":"To protect witness or victim","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If any person who is a witness in\nany case related to any offence under Schedule -1 or Schedule -2\nthinks that there is a threat to his or her security while appearing\nbefore the court or after making deposition in the court, he or she\nmay make a petition, setting out the reason for the same, to the court\nfor making security arrangement.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a reque st referred to in sub-section (1) is made , the\ncourt may order the concerned body to make arrange ment for the\nsecurity of such witness.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If an order is made by the court pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":", it shall be the duty of such body to make arrangemen t for such\nsecurity.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"No question shall be raised in any court about any\nmeasure followed pursuant to the order made by the court for the\nprotection of witness pursuant to this Section.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"The police shall provide security to the victim of any\nparticular offence or witness of any case if information is obtained\nthat such person is under undue coercion, threat or having adverse\nimpact on the security of his or her body from the opponent as being\nthe witness thereof.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"115","title":"Witness or evidence may be ex amined even outside the State of","content":"Nepal: (1) If any court needs to examine any witness or evidence\nthat is outside the State of Nepal or issue a commission to that effect\nin relation to any case pending before it, the examination of such\nwitness or evidence or the issuance of such commission may be\neffected in accordance with the law in force on mutual legal\nassistance.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The form of commission to be used pursuant to sub-\nsection (1) shall be as set forth in Schedule-41.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The witness or evidence examined pursuant to sub -\nsection (1) shall be deemed to have been examined in accordance\nwith this Act.\nProvided that details of the witness or evidence so examined\nshall be certi fied in accordance with the law of the concerned\ncountry.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the examination of a witness or evidence required to\nbe examined or has been examined pursuant to this Section in a\nlanguage other than the Nepali language, an authentic translation of\nthe record of such examination or evidence into the Nepali language\nshall be submitted to the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If it is necessary to examine any witness from outside\nthe State of Nepal or make his or her deposition in the course of\ninvestigation or trial of any case, such deposition may be conducted\nby means of video conference or other similar technology as\nprescribed for that purpose.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Arrangement shall be made for keeping records of the\ndeposition made by the witness in the course of witness testimony or\ndeposition conducted in accordance with sub-section (5).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nChapter, nothing shall be deemed to prevent the trying and settling of\na case by the reason only that evidence cannot be examined pursuant\nto this Section.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-12","title":null,"content":"Provisions Relating to Withdrawal, Compromise and Mediation of\nCases","children":[{"tier":2,"nodeType":"rule","identifier":"116","title":"Not to withdraw cases","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No case once filed in the court on any\noffence under Schedule -1 or Schedule - 2 shall be capable of being\nwithdrawn.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contain ed in sub -section (1),\nany case other than any of the following cases may be withdrawn:\n(a) A case relating to the offence of forged passport\nor citizenship, immigration, corruption, human\ntrafficking and transportation, smuggling and\ntransaction of narcotic drugs, poaching of, and\nillicit trade in , wildlife, adulteration of goods of\npublic consumption with poison, murder by\nadministrating poison , in a cruel or inhumane\nway or by taking control, money laundering, or\nancient monuments protection,\n(b) A case related to the offence under Section 56 of\nChapter-2, Section 129, 130, 131 or 134 o f\nChapter-6, Section 138, 139 or 141 of Chapter-7,\nChapter-8, Section 167 of Chapter -10, Section\n206 of Chapter -16, Chapter -17, sub-section (1),","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"or (3) of Sec tion 219 of Chapter -18, Section\n230 or 231 of Chapter -19, or Section 256 of","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-22","title":"of Part-2 of the Penal Code,","content":"(c) If the w ithdrawal of a case is prejudicial to the\nproperty right of any person, the case in which\nconsent of such person is not available to that\nextent.\n(3) The Government of Nepal shall make directives with\nnecessary standards on the cases to be withdrawn pursuant to sub -\nsection (2).\n(4) If a case to be withdrawn pursuant to sub -section (2),\nthe Government of Nepal may , in consultation with the Attorney\nGeneral, make decision to its withdrawal, in accordance with the\ndirectives made pursuant to sub-section (3).\n(5) If the Government of Nepal decides to withdraw a case\npursuant to sub -section (4), the Government of Nepal shall , through\nthe Attorney General or such government attorney as authorized by\nhim or her, make a petition, accompanied by the reasons for such\nwithdrawal, to the concerned court.\n(6) If a petition is made pursuant to sub -section (5), the\ncourt shall conduct heari ng before granting permission for the\nwithdrawal of the case.\n(7) If, upon conducting hearing pursuant to sub -section (6),\nthe court deems it reasonable to make order allowing the withdrawal\nof the case, the court may make such order allowing such\nwithdrawal, assigning the reasons for the same.\n(8) Notwithstanding anything contained elsewhere in this\nSection, no case which is under consideration at the stage of appeal,\nreference, review or revision shall be subject to withdrawal.","children":[{"tier":2,"nodeType":"rule","identifier":"117","title":"Compromise may be made","content":"Any case related to any of the offences\nunder Schedule-3 and Schedule-4 may be compromised at any stage\nwhatsoever with the consent of the parties to the case.\nProvided that if, in a case related to cheating or loss of or\ndamage to any property of the public or foreign employment, both\nthe defendant and the victim make a petition to the Government of\nNepal for the execution of compromise, the Government of Nepal\nmay, if it deems it reasonable, make an order to have such\ncompromise executed through the governmen t attorney in respect of\nsuch case.","children":[]},{"tier":2,"nodeType":"rule","identifier":"118","title":"Procedures for making compromise","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The parties shall, if they\ndesire to compromise a case pursuant to Section 117 , submit to the\ncourt a joint petition, bearing signature or thumb impression of both\nthe parties, setting out the terms of compromise intended to be made\nwithin the limits of the plaintiff's claim.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a petition containing the terms of compromise is\nsubmitted to the court pursuant to sub -section (1), the court shall\nread out the petition to the parties and ask the parties making such\npetition whether they intend to enter into compromise with free will\nand consent or not.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If, in response to a question asked pursuant to sub -\nsection (2), the parties reply that they are willing to compromise with\nfree will and consent, the judge trying the case shall prepare a deed\nof compromise subject to the terms con tained in t he joint petition,\nand take signature or thumb impression of the parties and affix his or\nher signature on the deed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Except in cases where any one has been authorized by a\npower of attorney to enter into compromise pursuant to this Chapter,\nwhile entering into compromise through an attorney , a separate deed\nof consent executed by the party to that effect shall be submitted.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"119","title":"Consequences of withdrawal or compromise of case s","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If the\nGovernment of Nepal withdraws any case pursuant to S ection 116,\nno case shall be instituted again against the accused of that case in\nrespect of the same offence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the compromise of a case is made pursuant to Section\n117, no action or case shall be capable of being instituted\nsubsequently between the same parties in respect of the same matter.\nProvided that nothing contained in this sub -section shall bar\nthe making of a petition claiming that any party has not complied\nwith the terms contained in the deed of compromise.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"120","title":"Mediation may be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If the parties to any case related with\nany offence under Schedule -4 so agree or the court consid ers\nappropriate to refer such case for mediation, the court may order to\nrefer such case for mediation at any time and stage, getting the\nparties to choose th e mediato r and specifying the mediator if the\nparties fail to do so.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If an order is m ade pursuant to sub -section (1) , the\nparties to the case shall appear before such mediator.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"After the parties appear pursuant to sub -section (2), the\nmediator shall conduct mediation proceedings, and prepare a deed of\ncompromise and submit it to the court if the parties consent to enter\ninto compromise.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Upon receipt of a deed of compromise referred to in\nsub-section (3), the court shall authenticate such deed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If compromise is executed pursuant to sub -section (4),\nthe court may, in pursuance of the deed of compromise executed by\nthe parties , exempt the penalty, fine or fee imposed by the lo wer\ncourt in relation to such case.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-13","title":null,"content":"Provisions Relating to Proceedings, Hearing of, and Judgments in,\nCases","children":[{"tier":2,"nodeType":"rule","identifier":"121","title":"Charge to be read out to the accused","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"When the accused\nappears before the court, the particulars of the offence of which he or\nshe is accused, all facts related wi th such offence, the evidence\nproduced by the complainant in support of the charge and\npunishment imposable on him or her if such charge is proved shall\nbe clearly stated to him or her, and the claim made in the charge\nsheet shall be read out by the court to him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While stating and reminding the charge and punishment\nimposable on such charge pursuant to sub-section (1), the court shall\nalso state which charge is based on which proof, evidence or\ndocument, and provide him or her with opportunity to see each\nproof, evidence or document, or to obtain a copy thereof if he or she\nso wishes.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"122","title":"Deposition of the accused to be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"After reading out the\ncharge and punishment imposable on such charge to the accused\npursuant to Section 121, the court shall ask him or her whether he or\nshe has any statement to make on that charge and record his or her\ndeposition.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If any accused who has already appeared in the court\nwishes to consult a law practitioner prior to taking of his or her\ndeposition, he o r she shall be provided with an opportunity to make\nsuch consultation.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Before recording the deposition pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":", the court shall inform the accused that he or she shall not be\ncompelled to testify against himself or herself and remind ed of the\nmatter that such testimony if made by him or her may be admissible\nin evidence against him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In the process of reminding the accused of the matters\npursuant to sub -section (3), the demand, if any, made by the\ngovernment attorney offering a reduction in sentence against him or\nher and the relevant provision of the law in force shall also be stated\nto him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"In recording the deposition of the accused pursuant to\nthis Section, each question and answer to such question shall both be\nrecorded, and where deposition has been taken through video\nconference, such deposition shall also be recorded.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"After recording the deposition referred to in sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":", signature or thumb impressions of the accused shall be taken on\nsuch record and the judge also shall sign it.\nProvided that where deposition has been made through video\nconference, the judge shall authenticate such matter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If, in taking deposition of the accused pursuant to this\nSection, any matter is omitted to be inquired wi th him or her, the\ncourt may summon the appearance of such accused and take re -\ndeposition of the omitted matter from him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, in relation to a case related to any offence under Schedule-4,\na statement of defense shall be submitted in the form referred to in\nSchedule-42, within the time -limit set forth in the process issued by\nthe court.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"123","title":"Judgment to be made immediately if the accused pleads guilty of","content":"offence: (1) If any accused, pleading guilty of the offence which he\nor she is charged with, makes a statement of confession before the\ncourt, the court may, also having regard to t he truth and reliability of\nsuch statement, make judgment immediately.\nProvided that:\n(a) In spite of such statement of confession by the\naccused, if the court, in view of the evidence\ncontained in the case -file, circumstances under\nwhich the offence was committed or any other\nmatter, has any reason to believe that his or her\nconfession is not true, the court s hall not make\njudgment in the case pursuant to this Section but\nshall order the examination of further evidence in\nthe case, by executing a memorandum of order,\naccompanied by the reasons therefor,\n(b) If the accused who has confessed the offence\nwhich he or she is charged with makes a plea for\na reduction in the sentence, the court shall, stating\nall matters pertaining thereto , take his or her\ndeposition and examine evidence thereon.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, in deposing before the court, any accused makes a\nplea that is different from the plea he or she has made before the\ninvestigating authority and the plaintiff makes submission for\npermission to re -conduct investigation into the evidence or plea\nproduced or made by him or her and submit further proof or\nevidence to the court, the court may give permission to produce such\nadditional proof or evidence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If an order is made pursuant to sub-section (2), the court\nshall not adjudge the case until such additional proof or evidence is\nproduced.\nProvided that such additional proof or evidence shall be\nproduced prior to the order for taking and trying of evidence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If any accused does not confess fully the offence which\nhe or she is charged with but confesses it partially, the court shall\norder the examinatio n of further evidence to the extent only of the\nmatter which he or she has not confessed.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"124","title":"Discussion may be held between plaintiff and defendant","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If\nthe accused has not pleaded guilty of the offence pursuant to Section\n123, the court may order to hold discussion between the plaintiff and\nthe defendant in order to ascertain the matter to be adjudged in the\ncase.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If an order is made to hold discussion pursuant to sub -\nsection (1), the plaintiff, defendant and the accused, in respect of a\ncase in which the Government of Nepal is plaintiff, shall also appear\nin the court, and if such accused so wishes, his or her law practitioner\nmay also appear.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In the discussion referred to in sub -section (1), the\nplaintiff and the defendant may present claim and defense and\nevidence relevant thereto, respectively.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The court may ascertain the matter to be adjudged in the\ncase from the claim, defense and evide nce submitted by the plaintiff\nand the defendant pursuant to sub-section (3).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"125","title":"Appointment of date for appearance for examination of","content":"evidence: (1) The court shall, in any of the following circumstances,\nexecute a memorandum of order, setting out, inter alia, the matters to\nbe adjudged as ascertained pursuant to Section 124, and appoint the\ndate for appearance for the examination of evidence:\n(a) If the accused refuses to make deposition\npursuant to Section 122,\n(b) If the defendant does not submit a sta tement of\ndefense,\n(c) If the accused makes deposition or statement of\ndefense, denying wholly or part ly the charge\nmade against him or her,\n(d) If the court executes a memorandum of order for\nthe examination of evidence pursuant to clause\n(a) or (b) of th e proviso to sub -section (1) of\nSection 123,\n(e) Such other circumstance as may be held\nappropriate by the court.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While appointing the date for appearance for the\nexamination of evidence pursuant to sub -section (1), the court shall\nestimate the time required for the witnesses to appear and the\ndocumentary evidence and thing to be produced, and so appoint such\ndate that evidence is collected as soon as possible.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the plaintiff of a case makes a request for time for the\nsubmission of further evidence or proof pursuant to sub -section (2)\nof Section 123, the cou rt shall, in appointing the date for appearance\npursuant to sub-section (1), generally appoint the date for appearance\nfor the examination of evidence so that evidence is examined no t\nlater than two months after the filing of case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In making order for appointing the date for appearance\nfor the examination of evidence pursuant to sub -section (2) or (3 ),\nsuch order shall be so issued that the examination of all evidences\nrequired to be examined in the case is made at the same time as far as\npossible.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Subsequent to the order appointing the date for\nappearance pursuant to sub-section (1) or (2), the c oncerned party to\nthe case shall submit or produce such evidence or witness before the\ncourt on the appointed date for appearance as required to be\nsubmitted or produced by that party.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"126","title":"Party or witness held in detention or imprisonment to be","content":"produced: (1) If any party or witness of a case, who is held in\ndetention or imprisonment, is required to be produced to make his or\nher statement or deposition or in relation to another case relevant to\nhim or her, the court shall, setting out the reason, order the concerned\noffice to produce such party or witness before the court on the date\nappointed for appearance for that purpose.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Upon receipt of an order pursuant to sub-section (1), the\nconcerned office shall produce before the court such party or witness\naccompanied by the security personnel.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub -section (2),\nif there is a reasonable reason for not being able to produce such\nparty or witness before the court because of security or physical\ndisability, such office may, with the consent of the court, arrange for\nthe examination of him or her through video conference.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If any party or witness of a case is examined through\nvideo conference pursuant to sub -section (3), the matters stated by\nhim or her shall be recorded.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"127","title":"Order of examining evidence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Except as otherwise ordered by\nthe court, the evidence of the plaintiff shall first be examined and\nthen the evidence of the defendant shall be examined on the date\nappointed for appearance for the examination of evidence, subject to\nthe law of evidence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If one party makes an y objection immediately that any\nevidence produced by t he other party or matter depos ed by any\nwitness is not admissible in evidence or should not be taken as\nevidence or is irrelevant to the case, the judge shall immediately\ndecide whether the objection is reasonable or not.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The court shall not allow any party to produce any\nevidence which is irrelevant to the case.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"128","title":"Provisions relating to trial of pe rson of unsound mind","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If\nthere is any reasonable reason to believe that any accused person ,\nbeing of unsound mind , is incapable of making his or her defense,\nthe court may also order ca using such person to be examined and\ntreated by a licensed doctor.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, upon the examination made pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":", it appears that the accused is incapable of making his or her\ndefense because of unsound mind, the court shall adjourn the case in\nthe case of such person, by executing a memorandum of order to that\neffect.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nAct, if such accused is held in detention and the court so considers\nreasonable, it may, at the time when proceeding is conducted\npursuant to sub -section (1) or subsequent to the execution of the\nmemorandum of order pursuant to sub -section (2), release such\naccused from detention.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In releasing the accused pursuant to sub -section (3), the\ncourt shall cause his or her guardian to make a bond that he or she\nshall take care of the accused in a manner to prevent the a ccused\nfrom doi ng any kind of inju ry or harm to any other person and\nproduce the accused before the court when so ordered by the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"In releasing the accused pursuant to sub -section (4), the\ncourt may take bail /bond or guarantee from the guardian in\naccordance with Chapter-7.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Except where the accused, who is held in detention and\nis of unsound mind, is released from detention pursuant to sub -\nsection (3), the court shall order the concerned prison to take special\ncare of such accused placed in detention for trial.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If the case of the accused of unsound mind is adjourned\npursuant to sub -section (2), the court shall , whenever the accused\nbecomes of sound mind, revive the adjournment, cause the\nappearance of the accused before the court and proceed with the trial\nof the case.\nProvided that prior to so reviving the adjournment, the court\nshall cause the accused to be examined again by a licensed medical\ndoctor, and that he or she has become of sound mind shall be\ncertified by such doctor.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"The court may, if it so wishes, order the medical doctor\nwho has made certification of soundness pursuant to sub -section (1)\nor (7) to appear before the court as a witness.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if there are other defendants also, along with the person of\nunsound mind, nothing shall be deemed to bar the hearing of the case\nin the case of such other defendants.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"129","title":"Trial of case s to be conducted in open bench","content":"The court shall\nconduct the trial of cases in open bench.\nProvided that the trail of a case related to the offence of\nespionage, human trafficking and transportation, sexual offence, a\ncase involving a child as the accused or victim, violence against\nwomen, rape, incest or a case running betwe en husband and wife or\nany other case that the court has, considering it reasonable to do so,\nordered for trial in camera, may be conducted in camera , and the\ncourt may prohibit the access to such bench of any person, other than\nthe concerned parties to that case, concerned law practitioners,\nemployees of the court and such other persons as the court considers\nnecessary.","children":[]},{"tier":2,"nodeType":"rule","identifier":"130","title":"Law practitioner may be appointed by the accused for his or her","content":"defense: (1) Any person accused of any offence may appoint a law\npractitioner of his or her choice for his or her defense, rebutting the\ncharge made against him or her, and pleading the case.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If an accused who is charged with the offence\npunishable by a sentence of imprisonment for life or for a term of ten\nyears or more fails to appoint his or her law practitioner, the court\nmay, in the case of such accused, order that the law practitioner\nappointed by the court defend him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, even if any accused does not intend to appoint a law\npractitioner pursuant to sub -section (1) or refuses to have defended\nby the law practitioner appointed by the court pursuant to sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":", nothing shall be deemed to prevent proceeding the case.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"131","title":"Judgment to be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The judge shall make judgment in a case\ngenerally within one mon th after the termination of examination of\nevidence in the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If it is not possible to make judgment within the period\nreferred to in sub -section (1), information thereof , accompanied by\nthe reason for the same, shall be given to the appeal hearing court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Judgment to be made pursuant to this Section shall be in\nthe form referred to in Schedule -43 and state, inter alia , the\nfollowing matters:\n(a) Short description of the case and other necessary\nmatters relevant thereto,\n(b) Main points of pleading, if any, made by the law\npractitioner in the case,\n(c) Evidence produced by the parties to the case,\ncredibility or refutability of such evidence, the\nbasis thereof, sufficiency or insufficiency of such\nevidence,\n(d) Matters relating to the legal question , if any,\nraised by any party to the case,\n(e) Grounds for the conviction or acquittal of offence\nand the reasons for the same,\n(f) Whether the judgment is a ppealable or not, and\nthe court in which appeal shall lie,\n(g) Other necessary matters.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In making judgment pursuant to this Section, the judge\nmay read out the full text of the judgment, if prepared, and the\ndecision only if the full text is not so prepared.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If only the decision is read out pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":", the judge shall cause it to be taken down in short hand in the\ndecision book, sign it and take signature or thumb impression of the\nparties to the case who are in attendance on it.\nProvided that it shall not be necessary to cause it to be signed\nby the government attorney in a state case in which the Government\nof Nepal is plaintiff.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If a decision is read out pursuant to sub-section (5), the\njudge shall write down the judgment and keep it in the case -file\nwithin one month.\nExplanation: For the purpose s of this sub -section, the term\n\"decision read out\" means the decision read out upon sentencing.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If the judgment is not set down within the time -limit\nreferred to in sub -section (6) , the concerned par ty may make a\ncomplaint to the Chief Judge of the concerned High Court, in the\ncase of a judgment of that High Court or a court subordinate to it,\nand to the Chief Justice in the case of a judgment of the Suprem e\nCourt, no t later than three days after the expiration of such time -\nlimit.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If a complaint is made pursuant to sub-section (7), the\nconcerned Chief Judge or the Chief Justice shall give direction to the\nconcerned judge to prepare the judgment within a week.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"The court shall, as far as possible, also put the decision\nreferred to in sub-section (5) on its website immediately.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"The court shall affix the decisions prepared and\nauthenticated in each week o n its notice board and also put them on\nthe website.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"132","title":"Notice and copy of judgment to be given","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The court shall give a\nnotice of judgment in the form referred to in Schedule -44 to the\naccused or defendant who has not been involved in the proceedings\nof the case from the beginning, the accused held in detention or\nimprisonment or the accused of a case heard ex parte.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The notice referred to in sub -section (1) shall be served\nas if it were a summons , and if such notice cannot be served, it shall\nbe published in any national daily newspaper owned by the\nGovernment of Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The concerned party shall bear the expenses to be\nincurred in the publication of a notice referred to in sub-section (2) in\nrelation to any case under Schedule-4.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The information of judgment of any of the cases under\nSchedule-1, Schedule -2 and Schedule-3 shall also be given to the\nconcerned government attorney office.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"133","title":"Dismissal of case s on death","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything\ncontained elsewhere in this Act, if the accused or defendant of any\ncase dies, the court shall dismiss such case.\nProvided that if there are more than one accused or defendant,\nthe case shall not be dismissed even on the death of any one accused.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\ndespite the death of the accused or defendant in a case involving the\nclaimed amount, the court may decide to set the claimed amount\nupon examining the evidence included in the case-file and such other\nevidence as the court finds necessary to examine.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If, despite the death of any complainant in any case\nreferred to in sub -section (2), the successor to such complainant\nappears to accept and continue the case within thirty days of his or\nher death, the court may decide as to whether or not compensation\nshould be awarded by examining the evidence contained in the case-\nfile and any other evidence required to be examined.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In the event of the death of a party making appeal, or\npetition for review or revision or of a person who was originally\nconvicted of the offence in such case, the case subject to such appeal,\nreview or revision petition shall abate.\nProvided that:\n(a) In the even t of the death of any one of the same\nparty, the case shall not abate without trying the\ncase in respect of the other persons,\n(b) In respect of a case involving any claimed\namount, the successor may, if he or she so\nwishes, take over the case within thirty -five days\nfrom the date of receipt of information.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-14","title":null,"content":"Provisions Relating to Appeal and Reference for Sanction","children":[{"tier":2,"nodeType":"rule","identifier":"134","title":"Appeal to lie","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A party who is not satisfied with a j udgment or\nfinal order made by a court may make an appeal within thirty days\nfrom the date of knowledge of the judgment.\nProvided that if an appealing party makes a petition showing\nthe cause of being unable to make appe al within that time -limit and\nthe appeal hearing court considers the petition to be reasonable, it\nmay order the extension of the time -limit for a maximum of thirty\ndays.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"A person wishing to make an appeal pursuant to sub -\nsection (1) shall file it with the court which hears appeals from the\ncourt making judgment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained elsewh ere in this\nAct, if any party to a case or his or her attorney is present, or his or\nher law practitioner has made pleadings, before the court at th e time\nof hearing and judgment is made on the same day, the party to the\ncase shall be deemed to have known that such judgment has been\nmade.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, the party shall be deemed to have ipso facto known the\njudgment after the expiry of a period of one year from the date of\njudgment.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"135","title":"Filing of appeal through judgment making court or prison where","content":"one is imprisoned: (1) Notwithstanding anything contained in sub -\nsection (2) of Section 134, a ny person wishing to make appeal\npursuant to sub-section (1) of that Section may make appeal through\nthe judgment making court or also through the prison where the\nperson convicted of the offence pursuant to such judgment is\nimprisoned.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If an appeal is filed pursuant to sub -section (1), such\ncourt or prison shall, as soon as possible, forward the appeal to the\nappeal hearing court , setting out the details of the service or\npayment, if any, by the appellant of the sentence imposed on him or\nher or the bail /bond or guarantee, if any, furnished by him or her in\nconsideration for such sentence, and give information thereof to the\nappellant.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The judgment making court shall forward the case-file\nalong with the appeal pursuant to sub-section (2).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"136","title":"Procedures to be fulfilled in making appeal","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A memorandum\nof appeal shall be made in the form referred to in Schedule-45.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Every memorandum of appeal to be made pursuant to\nsub-section (1) shall clearly state, inter alia , the full name and\naddress of the appellant and that of the respondent, short description\nof the case, the matters contained in the decision of the lower court\nwith which the appellant is dissatisfied and grounds for such\ndissatisfaction, the matters to b e decided by the appeal hearing court\nand the relevant laws , and shall bear signature or thumb impression\nof the appellant.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Every memorandum of appeal to be made pursuant to\nsub-section (1) shall be accompanied by the following documents:\n(a) A copy of the judgment intended to be appealed\nagainst,\n(b) If any sentence is imposed on the appellant by the\njudgment, evidence showing that he or she has\nserved or paid such sentence or has been\nimprisoned or furnished a bail /bond or guarantee\nfor the same.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"137","title":"To remain in imprisonment while making appeal","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Any of the\nfollowing persons shall remain in imprison ment while making\nappeal:\n(a) A person who is sentenced to imprisonment for\nlife,\n(b) A person who is sentenced to imprisonment for a\nterm exceeding ten years,\n(c) A person who , upon being convicted of an y\noffence under Schedule-1 or Schedule -2, is\nsentenced to imprisonment for a term exceeding\nthree years,\n(d) A person who, having been remanded in\ndetention for trial, is convicted of the offence and\nsentenced to imprisonment,\n(e) A person who is sentenced to imprisonment and\nhas not permanent residence in Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nif a person who is above seventy-five years of age or a person who is\nrecommended by the medical board formed by the Government of\nNepal that he or she, owing to suffering from an incurable or highly\nsevere disease, cannot stay in detention or an offender who has not\nbeen held in detention by an order of the court tha t he or she is not\nrequired to be remanded in detention but is sentenced to\nimprisonment for a term not exceedin g ten years makes a petition ,\nsetting out the reason, for a leave of appeal without being held in\ndetention, and if such reason appears to be reasonable, the appeal\nhearing court may, upon taking a bail/bond or guarantee from him or\nher, grant the leave of appeal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a leave of appeal is granted pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":", such court shall execute a memorandum of order recording the\nreasons f or such leave to make appeal without being held in\ndetention and the memorandum of order shall be included in the\ncase-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Any person other than that mentioned in sub -sections","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"and (2) may make appeal by furnishing with the court passing\njudgment or the appeal hearing court a bail/bond or guarantee for the\nsentence imposed on the person by that judgment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If a person who does not furnish a bail /bond or\nguarantee pursuant to sub -section (4) is sentenced to imprisonment,\nthat person may appeal onl y being held in imprisonment for such\nsentence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If decision cannot be made on the appeal made by a\nperson who is imprisoned for being unable to furnish a bail /bond or\nguarantee pursuant to sub -section (2) or (4) within six months from\nthe date of filing of such appeal, the concerned appeal hearing court\nshall try the case by releasing that person from imp risonment after\nthe said period and holding him or her on recognizance.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"In the event of failure to make judgment within the\nperiod referred to in sub-section (6), such court shall give\ninformation thereof, accompanied by the reason therefor, to the court\nhearing appeal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection:\n(a) In the case of a person who having been held in\ndetention or imprisonment in the course of\nproceedings of the case has already served the\nsentence as commuted by the judgment, such person\nshall not be required to remain in prison or furnish a\nbail/bond or guarantee to make appeal,\n(b) No person shall be imprisoned for a period in excess\nof the sentence imposed by the judgment only by the\nreason that appeal has been made.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"In the case of a person furnishing a bail /bond or guarantee\npursuant to Chapter-7, such bail/bond or guarantee may, to the extent\nof the sufficiency of such bail/bond or guarantee, be maintained as a\nbail/bond or guarantee, for the purposes of this Section.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"In taking a bail /bond or guarantee pursuant to this\nSection, the court may, having regard to the need and propriety,\nrequire and t ake the bail /bond or guarantee also for such claimed\namount of a governmental or public body as is held recoverable by\nthe judgment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"If the bail/bond or guarantee of any property belonging\nto any person other than the appellant has been furnished, such\nproperty shall not be maintained as a bail/bond or guarantee for the\npurposes of this Section without the consent of that person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"138","title":"Calling for case file","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Except in cases where the case -file is\nreceived pursuant to sub -section (3) of Section 135, the appeal\nhearing court shall, upon the filing of an appeal, and as soon as\npossible, order the concerned court to send the case-file of such case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The conc erned court shall send the case -file to the\nappeal hearing court within three days from the date of receipt of the\norder pursuant to sub-section (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"139","title":"Appointment of date for appearance for hearing appeal","content":"Upon\nreceipt of the case-file pursuant to sub -section (3) of Section 135 or\nSection 138, the appeal hear ing court shall appoint the date for\nappearance for the hearing of the appeal.","children":[]},{"tier":2,"nodeType":"rule","identifier":"140","title":"Hearing of appeal","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The appeal hearing court shall complete the\nhearing of appeal within six months after t he date of receipt of the\ncase-file from the lower court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, while hearing the appeal pursuant to sub -section (1),\nthe appeal hearing court considers that the decision made by the\nlower court is reasonable and does not suffer any substantial\ndifference, it may dismiss the appeal, by recording its reasons for\ndoing so.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If, except for the dismissal of the appeal plea pursuant\nto sub-section (2), it appears that the pleas of the appeal should be\nheard, the appeal hearing court shall, setting out the reasons for the\nsame, appoint the date for appearance for the hearing of the appeal\nand give a notice to the respondent to rebut the pleas of appeal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In giving a notice referred to in sub -section (3), a notice\nof fifteen days shall be given, also accompanied by a copy of the\nmemorandum of appeal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"A person who has obtained a notice pursuant to sub-section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"may submit defense in writing to defend himsel f or herself and\nrebut the pleas of appeal, within the period specified by the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"The defense in writing to be submitted to the court pursuant\nto sub-section (5) shall be in the form set forth in Schedule-46.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Upon hearing the appeal pursuant to sub -section (3), the\ncourt shall decide the appeal.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"141","title":"Appeal liable to be heard ex parte in absence of respondent","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If the respondent does not appear within the time-limit of the notice\ngiven pursuant to sub -section (3) of Section 140, the appeal hearing\ncourt may appoint such another date for appearance for deciding the\nappeal as falling after at least fifteen days , and hear the appeal ex\nparte on such date and decide it.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nif the respondent makes a petition , prior to the date appointed for\nappearance pursuant to sub-section (1), showing a reasonable reason\nfor being unable to appear within the time -limit of the notice given\npursuant to sub-section (3) of Section 140, and such reason seems to\nbe reasonable, the court shall order the extension of the time-limit,\nshowing such reason, and also order the respondent to appear on the\ndate appointed pursuant to sub -section (1), and hear and decide the\nappeal.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"142","title":"Not required to be on recognizance","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If an appellant or\nrespondent does not wish to remain on recognizance in the course of\nthe appeal proceedings , he or she may make a petition to that e ffect\nto the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a petition is made pursuant to sub -section (1), the\ncourt may discontinue his or her appearance on the appointed dates,\nby getting a deed to be executed by the appellant or respondent to the\neffect that he or she will appear as and when the court so requires.\nProvided that the appellan t or respondent who is not on\nrecognizance may, if he or s he so wishes, appear on the date\nappointed for appearance for the hearing of the appeal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if, during the hearing of appeal, the court is of the opinion\nthat the appellant should be inquired into any matter or required to\nproduce any evidence in relation to the appeal, the court may order\nthe appellant to keep on appearing on the appointed dates for\nappearance.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"143","title":"Service of notice or order on appellant or respondent as if it were","content":"a summons: The notice or order to be issued by th e court to the\nappellant or respondent pursuant to Section 140, 141 or 142 shall be\nserved in accordance with Chapter-6 as if it were a summons.","children":[]},{"tier":2,"nodeType":"rule","identifier":"144","title":"Powers of appeal hearing court","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"In hearing the appeal pursuant\nto this Chapter, the appeal hearing court shall have the following\npowers:\n(a) To approve, void or reverse or partially reverse t he\njudgment of the lower court,\n(b) To reduce or enhance the extent of the sentence\ncommuted by the lower court to the offender, or to\nalter the sentence,\n(c) Where the judgment has been made without\nexamining such evidence as required to have been\nexamined, to make such examination by itself or to\norder the lower court to make such examination,\n(d) If any particular matter required to have been\nadjudged in the case has not been adjudged, to\nadjudge itself or order the lower court to adjudge\nsuch matter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If an appeal from the judgment passed by the lower\ncourt is made by any particular offender or complainant only, and the\ndecision on the appeal will render the judgment of the lower court to\nbe affected in the case of the offender or defendant not mak ing\nappeal, the appeal hearing court, in exercise of the powers set forth\nin sub -section (1), may, setting out a nd recording the reasons\ntherefor, pass judgment in accordance with law a lso in the case of\nsuch accused.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, the appeal hearing court may , as required, exercise such\npowers as may be exercised by the lower court.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"145","title":"Reference for sanction","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If any court passes judgment\ncommuting a sentence of imprisonment for a term of twenty year s or\nmore or imprisonment for life to any person, it shall refer such\njudgment for sanction, accompanied by the case -file, to the appeal\nhearing court within thirty-five days from the date of passage of such\njudgment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a reference for sanction is made pursuant to sub -\nsection (1) and even the appeal hearing court passes judgment\nconfirming the sentence of imprisonment for a term of twenty years\nor more or imprisonment for life to the accused, such judgment shall\nthen be referred to the Supreme Court for sanction.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"146","title":"Appeal against reference judgment","content":"A party, who is dissatisfied\nwith the judgment so passed by the court as to be referred to for\nsanction pursuant to Section 145, may appeal against it.","children":[]},{"tier":2,"nodeType":"rule","identifier":"147","title":"Not to pass reference ju dgment until expiration of time-limit for","content":"appeal: (1) In any case submitted for reference pursuant to Section\n145, no reference judgment shall be made until the time -limit\nallowed for preferring an appeal expires.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If an appeal is made within the time -limit referred to in\nsub-section (1), the records of reference judgment shall be crossed\noff and the case shall be heard on appeal.\nProvided that if an appeal is made by any person only, out of\nthe persons subjected to sentence, decision shall be made by virtue of\nthe same appeal also in cases of those who have not made appeal.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"148","title":"Procedures for making reference for sanction","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"In referring a\njudgment for sanction in any case pursuant to Section 145, the court\nshall forward the case-file of that case along with the reference.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the accused is held in detention in the case in which\nreference judgment is made pursuant to sub-section (1), reference\nshall also specify the date on which the accused was held in\ndetention and the name of the prison where he or she is bei ng kept,\nand details of the accused if he or she has absconded or escaped from\nthe detention.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The other procedures on the hearing of refe rence for\nsanction shall be the same as applicable to the hearing of appeal.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"149","title":"Powers of court in dealing with reference for sanction","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Any\ncourt dealing with reference may exercise such powers a s may be\nexercised by the appeal hearing court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, in examining a reference for sanction, it appears that\nthe verdict of the judgment of the lower court is not in order and any\nalteration can be made therein, the concerned parties shall be\nsummoned to appear, by giving the time-limit of fifteen days.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"150","title":"Appeal and reference judgment","content":"The appeal judgment shall be\nmade in the form referred to in Sc hedule-47, and the reference\njudgment in the form referred to in Schedule-48.\nProvided that where a single judgment has to be made on\nappeal and on reference for sanction, such judgment shall be made in\nthe form referred to in Schedule-47.","children":[]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-15","title":null,"content":"Provisions Relating to Execution of Judgments","children":[{"tier":2,"nodeType":"rule","identifier":"151","title":"To establish record of sentence","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If the court passes any\njudgment in any case, the concerned court shall establish a record of\nthe sentence, fine or the established claimed amount or compensation\npursuant to such judgment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the appeal hearing court passes judgment convicting\nany person of any offence or any person is convicted of any offence\nbeing judgment of the lower court reversed or void ed, it shall\nestablish a record thereof and send a copy of the judgment to the\nconcerned District Court for its execution.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"After establishing a record pursuant to sub-section (1) or","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":", the concerned court shall execute the judgment , and if any body\nhas to do any act for the execution of judgment, it shall order the\nbody to do such act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"While making an order pursuant to sub -section (3), if\nthe person sentenced to imprisonment is present in the court, the\ncourt shall also forward him or her to the prison; and if such person\nis neither present in th e court n or held in detention or prison, the\ncourt shall send an order, in the form referred to in Schedule-49, to\nthe concerned police office to arrest and hand over him or her to the\nprison.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If the same offender is liable to more than one sentence\nand there is a doubt as to which sentence is the higher, the prison\noffice shall write to the concerned district court and do as sanctioned\nby the district court.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"152","title":"Bodies for judgment execution","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The District C ourt wher e the\ncharge sheet or plaint has been filed shall execute the judgment on a\ncase irrespective of the tier of court making such judgment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The concerned District Court shall also execute a\njudgment on a case proceeded and adjudicated originally by the\nappeal hearing court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained els ewhere in this\nSection, if the District C ourt responsible for the execution of a\njudgment cannot be identified because of the number of defendants,\nlocation of their residence or property, the District C ourt designated\nby the appeal hearing court shall execute the judgment of such case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"The concerned bodies shall execute judgments made by\nthe judicial bodies other than the regular courts.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Notwithstanding anything contained in sub-section (4),\nthe concerned Distr ict Court shall execute the judgment pursuant to\nthis Act , unless otherwise provided by law in respect of judgment\nexecution.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"153","title":"Postponement of execution of judgment s","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The court shall\npostpone the execution of a judgment in the following circumstance:\n(a) If an appeal is made in a case whic h is appealable\npursuant to law, until the case is finally adjudicated\non appeal, or if no such appeal is made, un til the\ntime-limit allowed for preferring appeal is expired,\n(b) If the case is one requiring ref erence for sanction\npursuant to law, until the reference made for\nsanction is decided.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"When an appeal is made pursuant to clause (a) of sub -\nsection (1), the appellant shall submit a petition stating that matter to\nthe concerned court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nif a judgment is made holding any offender liable to a senten ce of\nimprisonment, such offender shall be immediately sent to\nimprisonment, except as otherwise provided in this Act.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"154","title":"Confinement in p rison","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Upon receipt of an order referred to in\nSection 151 or upon the person held to be offender being arrested by\nthe police off ice, the concerned prison office shall confine the\noffender in prison in accordance with law.\nProvided that if a child below eighteen years of age is\nconvicted of an offence, the child shall be held in a separate children\nreform home or similar other home as provided by the Government\nof Nepal.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While confining an offender in prison pursuant to sub -\nsection (1), the pr ison office shall prepare and update the record\ncontaining information, inter alia, of when the offender has been\nconfined in prison or arrested and when the service of the sentence of\nimprisonment will complete.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"155","title":"Payment of money in lieu of imprisonme nt","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If, in view of the\nage of the offender who is convicted, at the first instance, of any\noffence punishable by a sentence of imprisonment for a term of one\nyear or less, gravity of the offence, manner of commission of the\noffence and his or her conduct, as well, the court does not consider it\nappropriate to confine the offender in prison and is of the view that\nthere will be no threat to the public peace, law and order if he or she\nis released, and the court, for the reasons to be recorded, considers it\nappropriate to dispense with the requirement of undergoing\nimprisonment upon payment of a fine in lieu of imprisonment, the\ncourt may order that the offender be not liable to undergo\nimprisonment if he or she makes payment of money in lieu of\nimprisonment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Prior to issuing an order pursuant to sub -section (1), the\ncourt shall cause a deed to be executed by the offender that he or she\nwill not commit any kind of offence henceforth and will comply with\ngood conduct.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In making payment of money by an offender who is\ndispensed with the requirement of undergoing imprisonment upon\npayment of money in lieu of imprisonment pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":", the offender shall pay money by three hundred rupees a day of\nimprisonment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If any offender who i s dispensed with the requirement\nof undergoing imprisonment pursuant to sub-section (1) commits any\noffense punishable by a sentence of imprisonment within three years\nafter the date of such release, the sentence also including that of\nimprisonment imposed on him or her by the previous judgment shall\nbe executed.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if any foreign national who has been convicte d of any\noffence punishable by a sentence of imprisonment for a term of one\nyear or less and is in detention or imprisonment makes a petition for\ndispensing with the requirement of undergoing imprisonment upon\npayment of a fine in lieu of the imprisonment, and if the offence is\nnot any offence set forth in sub -section (4) of Section 159, an d the\ncourt considers app ropriate to release that offender from\nimprisonment upon payment of a fine in lieu of the imprisonment,\nthe court may order that the offender will not be liable to undergo\nimprisonment if he or she makes payment in lump sum of the\namount to be set by five hundred rupees a day.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"In making an order pursuant to sub-section (5), the court\nshall order that such person be sent out of Nepal within seven days\nand the immigration office shall send such person out of Nepal\npursuant to the court order.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"Fifty percent of the amount received pursuant to sub -\nsections (3) and (5) shall be deposited into the victim relief fund\nestablished in accordance with law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If payment of money is made pursuant to this Section,\nthe offender shall be d eemed to have served the sentence of\nimprisonment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, the record of imprisonment of the person who is dispensed\nwith the requirement of undergoing imprisonment pursuant to this\nSection shall re main valid until the period of completion of the\nservice of the sentence of imprisonment, and the court may, at any\ntime, revoke the order under this Section if he or she upholds\nconduct or commits offence, contrary to sub-sections (2) and (4).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"If an order is revoked pursu ant to sub -section (9), such\noffender shall serve the whole sentence commuted to him or her, by\nundergoing imprisonment.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"156","title":"Property to be attached","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If the property belonging to a person\nagainst whom a warrant for arrest has bee n issued pursuant to sub-\nsection (4) of Section 151 has not been attached earlier or if such\nperson cannot be arrested , the concerned police office may make a\nreport, also indicating the description of his or her property, to the\ncourt for making attachment to the property to which such person has\npartition entitlement.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a report is made pursuant to sub -section (1), the\nconcerned court shall issue an order to the concerned land revenue\noffice or other body or institution to attach the property to whic h\nsuch person has entitlement.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If, in attaching the property pursuant to sub -section (2),\nproperty more than that required to be attached has been attached,\nsuch person may make a petition to the concerned court to release\nsuch excess property attached.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If a petition is made pursuant to sub -section (3) and,\nupon examination of such petition, it appears that excess property\nhas been so attached, the court may make an order to the concern ed\nland revenue office or body or institution to release the attachment of\nsuch excess property, and if such order is made, such office or body\nshall release such property.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If an offender is liable to pay the claimed amount,\ncompensation or other amount pursuant to a judgment of the court,\nsuch amount shall , in accordance with this Chapter, be recovered\nfrom the property attached pursuant to sub -section (1), and only the\nremaining property shall be attached.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"157","title":"Property may be auctioned","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If any offender cannot be arrested\neven until six months from the date of issue of warrant for arresting\nthat offender pursuant to sub -section (4) of S ection 151, the amount\nof fine or compensation payable as per the judgment shal l be\nrecovered by receiving cash from the concerned body or institution if\nthe property a ttached pursuant to Section 156 is cash and by\nauctioning the property so attached if it is other movable or\nimmovable property and paying the amount in consideration for a\nfine or government claimed amount to the consolidated fund, and the\namount remaining upon payment of compensation, if any, shall be\nreturned to his or her successor.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the offender is arrested before terminating the record\nof sentence pursuant t o this Act and intends to pay in cash the fine,\nclaimed amount or compensation to which he or she is liable, the\nsentence of imprisonment shall be executed by returning to him or\nher the property attached pursuant to Section 156, upon recovering\nthe expens es incurred in the execution of such attachment if such\nproperty has not yet been auctioned, and the proceeds of the auction\nsale of the property upon recovering the expenses incurred in the\nexecution of such attachment and auction, if s uch property has be en\nauctioned.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"158","title":"Remission of sentence in the event of death of the person","content":"sentenced: (1) In the event of the death of a person who is convicted\nby the court of an offence and sentenced therefor, the whole sentence\nof imprisonment or fine remaining to be executed until the time of\nhis or her death shall ipso facto be remitted.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub-section (1),\nif a person liable to pay any governmenta l or personal claimed\namount, compensati on or other amount dies before making such\npayment, such amount or compensation shall, in accordance with this\nAct, be recovered from the property belonging to that person only to\nthe extent of the amount recoverable from such property.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In making recovery of any claimed amount,\ncompensation or amou nt pursuant to sub -section (2), the\ngovernmental claimed amount, compensation and personal\ncompensation and claimed amount shall be recovered in respective\norder of priority from the property to the extent of recoverability\nfrom the property of such person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"159","title":"Pardon many be made","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"A person who is sentenced by a court\njudgment to punishment for an offence may make a petition to the\nPresident, through the Ministry of Home Affairs, for the pardon,\nsuspension, alteration or reduction of that sentence.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In making a petition pursuant to sub -section (1), the\npetitioner shall attach a copy of the judgment of the court by which\nhe or she was sentenced.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a petition made pursuant to sub -section (1) is\nforwarded by the President to the Ministry of Home Affairs for\nnecessary action, the Ministry shall, having regard to the following\nmatters, make a submis sion to the Government of Nepal to decide\nwhether or not to pardon , suspend, alter or reduce the sentence\nimposed on the petitioner:\n(a) Nature of the offence, and the circumstances\nunder which the offence was committed,\n(b) Age and physical condition of the offender,\n(c) Limit/ceiling of the sentence imposed on the\noffender,\n(d) Whether or not the off ender was sentenced to\nimprisonment for committing any offence prior to\nthat punishment sentenced to him or her, and if he\nor she was so sentenced, the nature of such\noffence and the sentence served by him or her,\n(e) Whether or not the offender is held in detention.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding a nything contained elsewhere in sub -\nsection (3), no action may be taken t o pardon, suspend, alter or\nreduce the sentence imposed on the offender of any of the following\noffences:\n(a) Corruption,\n(b) Torture,\n(c) Rape,\n(d) Murder in a cruel and inhumane way or by taking\ncontrol,\n(e) Genocide,\n(f) Explosives,\n(g) Kidnapping, hostage-taking or enforced disappearance,\n(h) Human trafficking and transportation,\n(i) Money laundering, and\n(j) Narcotic drugs trafficking or transaction punishable\nby a sentence of imprisonment for a term exceeding\nthree years.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if th e case is under consideration of any court by way of\nappeal, reference for sanction, review o r revision or if the sentence\nimposed b y the judgment of a court has not become final, the\nMinistry of Home Affairs may not take action referred to in sub-\nsection (3).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Prior to making a decision pursuant to sub -section (3),\nthe Government of Nepal may cons ult the parole and probation\nboard established by law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If, while making decision pursuant to sub -section (3), the\nGovernment of Nepal has any reasonable reason for pardoning the\nwhole or any part of, suspending, altering or re ducing, the sentence\nimposed on the petitioner, it shall make a recommendation,\naccompanied by its opinion along with the grounds therefor, to the\nPresident.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If the sentence imposed on any offender is pardoned,\nsuspended, altered or reduced by the President pursuant to the\nrecommendation made by the Government of Nepal under sub -\nsection (7), the Government of Nepal shall give a notice thereof to\nthe concerned court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"After receiving the notice referred to in sub -section (8),\nthe concerned court shall accordingly void or u pdate the record s\nthereof.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"The judgment of the concerned court shall not be voided\nby the reason of pardon, alteration or reduction of the sentence\nimposed on any person granted by the President pursuant to this\nSection, and it shall not affect in any manner the sentence already\nserved or fine or claimed amount already paid by such person.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"The Government of Nepal may make necessary\nstandards for the purpose of making proposal or recommendation\npursuant to sub-sections (3) and (7).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"160","title":"Records to be voided","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The court shall, in the following\ncircumstance, void the record s of sentence established pursuant to\nsub-section (1) or (2) of Section 151, by setting out the reason s\ntherefor:\n(a) If the sentence of imprisonment has been served by\nthe offender pursuant to this Chapter,\n(b) If the sentence of imprisonment has been served by\nthe offender by labor pursuant to the law in force,\n(c) If the sentence of imprisonment or punishment is\nremitted due to the death of the offender as\nmentioned in Section 158,\n(d) If the sentence of imprisonment has been served by\nthe offender in a reform home or community center\nor by doing community ser vice in accordance with\nthe law in force,\n(e) If the sentence imposed on the offender is pardoned\nin whole pursuant to Section 159,\n(f) If the offender pays the full amount for the fine or\nclaimed amount or compensation pursuant to this\nChapter, or\n(g) If amount in lieu of imprisonment or sentence or\nclaimed amount or compensation imposed on the\noffender is recovered pursuant to this Chapter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nif any person, who is sentenced to imprisonment or required to\nundergo imprisonment for a fine or government claimed amount or\nany other amount in accordance with the law in force, fails to appear\nin the court or to undergo imprisonment in the prison or cannot be\narrested until the following period, the court shall void the records of\nsentence established in the case of such person:\n(a) Fifty years in the case of the sentence of\nimprisonment for life,\n(b) Forty years in the case of the sentence of\nimprisonment for a term exceeding ten years,\n(c) Thirty years in the case of the sentence of\nimprisonment for a term of five to ten years,\n(d) Twenty years in the ca se of the sentence of\nimprisonment for a term of one to five years,\n(e) Twelve years in the case of the sentence of\nimprisonment for a term not exceeding one year.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If a person whose record is voided pursuant to sub -\nsection (2) is found after the expiry of the said period, the court shall\nexecute the judgment in accordance with this Chapter as if the record\nwere not voided in the case of him or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"In voiding the record pursuant to sub -section ( 2), the\nproperty belonging to that person, if any, attached pursuant to this\nAct, shall be forfeited and auctioned, and the proceeds of sale by\nauction shall be credited to the consolidated fund.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"No person whose record has been void ed by the reason\nof the non -completion of the service of sentence pursuant to this\nSection shall, notwithstanding anything contained in the law in force,\nbe eligible to be appointed , nominated, designated or elected to any\npublic office until such person serves such sentence pursuant to the\njudgment awarding the sentence.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"161","title":"Period of detention undergone to be set off against sentence of","content":"imprisonment: (1) If a person who, on conviction, is sentenced to\nimprisonment by a court judgment , has remained in detention or\ncustody in the course of investigation, the period of such detention or\ncustody shall be set off against the term of imprisonment imposed on\nhim or her by the judgment , and such offender shall be imprisoned\nonly for the remaining term of imprisonment.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If any off ender who is not sentenced to imprisonment\nbut to a fine only has remained in detention or custody in the course\nof investigation, the total amount to be set by three hundred rupees a\nday of the period of his or her detention or custody shall be set off\nagainst the amount of fine payable by him or her.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"162","title":"Execution of sentence of fine","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Every person who is required to\npay a fine in accordance with the record s established pursuant to\nSection 151 shall pay the fine immediately.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything containe d in sub -section (1),\nif such person is not able to immediately pay the amount of fine but\nfurnishes a property as the guarantee for the payment of such\namount, the court may order that the amount of fine be paid up\nwithin one year in a maximum of three installments.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub -section (2),\nif the person so sentenced to fine has furnished any bail /bond or\nguarantee pursuant to Chapter 7 or Section 137, the court shall order\nthat the amount of fine be recovered from such bail /bond or\nguarantee and only the remaining amount be paid in installments.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Except in cases where the provision of payment of the\namount of fine in installments is made pursuant to sub-section (2) or\nthe service of sent ence has already been made by remaining in\ndetention or custody in the course of the proceedings of the case or\nthe amount of fine is recoverable from the bail /bond or guarantee\nfurnished pursuant to Chapter 7 or Section 137, the court shall order\nthe concerned prison to imprison the offender in lieu of the fine if he\nor she fails to pay the amount of fine immediately.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If an order is made pursuant to sub -section (4) and the\noffender who fails to pay the amount of fine pays some amount of\nfine or if the offender has remained in custody or detention in the\ncourse of the proceedings of the case and there is a situation that the\nperiod of such custody or detention undergone by him or her is to be\nset off against the period of imprisonment, the period of\nimprisonment in the default of payment of the amount of fine shall\nbe set by setting off the said period of imprisonment undergone, and\nthe offender shall be imprisoned only for the remaining period in\nproportion to the period so set and the total amount of the fine.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"163","title":"Provisions relating to government claimed amount or other","content":"amount: (1) If a judgment decrees that the claimed amount be\nrecovered, the recovery of a government claimed amount shall have\npriority over the recovery of a personal claimed amount.\nProvided that if any judgment has been made to recover a\npersonal claimed amount before making the judgment to the effect\nthat a governmental claimed amount be recovered, no priority shall\nbe given to the government claimed amount.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the government claimed amount or other amount has\nnot been recovered pursuant to the judgment or there is a situation\nthat such amount cannot be recovered, except where the pro perty\nbelonging to the offender liable to pay such claimed amount or other\namount has already been attached previously, such property shall be\nattached as soon as possible after the passage of the judgment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the offender fails to pay the claimed amount or other\namount referred to in sub-section (1) within thirty days from the date\non which the judgment becomes final, such amount shall be\nrecovered, in the case of a movable property attached pursuant to\nsub-section (2), by receiving such movable property from the body\nholding it, and in the case of an immovable property so attached, by\nauctioning such immovable property.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Such person shall be imprisoned for the government\nclaimed amount that has not been recovered even from the proceeds\nof the auction of the property pursuant to sub-section (3).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"164","title":"Imprisonment for government claimed amount","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The\nconcerned person shall pay any government claimed amount or any\nother amount held by a court judgment to be recoverable.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If such person fails to pay the government claimed\namount or other amount referred to in sub -section (1), such amount\nshall be recovered by forfeiting his or her property.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If any government claimed amount or other amount\ncould not be recovered even by making forfeiture referred to in sub-\nsection (2), the sentence of imprisonment for a term not exceeding\nthe following term for the following claimed amount or such amount\nshall be set for such person:\n(a) One month for the claimed amount of five\nthousand to ten thousand rupees,\n(b) Three months for the claimed amount of ten\nthousand to twenty-five thousand rupees,\n(c) Six months for the claimed amount of twenty-five\nthousand to fifty thousand rupees,\n(d) One year for the claimed amount of fifty\nthousand to one hundred thousand rupees,\n(e) Six months for every fifty thousand rupees over\none hundred thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"One shall be sentenced to imprisonment fo r an amount\nless than that set forth in clause (a) of sub -section (3) in a manner to\nset off three hundred rupees for each day.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, in sentencing to imprisonment for a government claimed\namount, such sentence of imprisonment shall not be set to exceed\nseven years.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"165","title":"Procedures for recovering personal claimed amount or","content":"compensation: (1) A person shall pay such personal claimed amount\nheld to be payable by him or her, compensation or other amount to\nwhich the victim or his or her successor is entitled under the\njudgment of a court to the person who is entitled to get such payment\nwithin six months from the date of judgment.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If such person fails to pay such claimed amount,\ncompensation or amount within the period referred to in sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":", he or she shall be liable to a fine not exceeding ten thousand\nrupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the person r equired to pay such claimed amount,\ncompensation or other amount within the period referred to in sub -\nsection (1), the person who is entitled to the recovery of such\nclaimed amount, compensation or other amount may make a petition\nwithin three years from the date of final judgment, showing the\nproperty owned by the person liable to pay such claimed amount,\ncompensation or other amount.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If a petition is made pursuant to sub -section (3), the\ncourt shall cause such claimed amount, compensation or other\namount to be recovered respectively by attaching and auctioning the\nsaid property.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If the person liable to pay a claimed amount,\ncompensation or other amo unt pursuant to su b-section (1) pays the\nsame to the court or if the claimed amount, compensation or other\namount is recovered from the bail /bond or guarantee if any,\nfurnished pursuant to sub-section (1) of Section 68, recovery shall be\nmade accordingly.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If the person entitled to the recovery of a claimed\namount, compensation or other amount is not able to fin d the\nproperty within the period referred to in sub -section (3), the court\nshall abate the petition, subject to the execution of recovery if he or\nshe gives intimation as and when such property is found.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If the claimed amount, compensation or other amount\ncould not be recovered pursuant to sub -section (4), the person\nentitled to recover the remaining claimed amount, compensation or\nother amount which could not be so recovered may make a petition\nfor imprisoning the offender, within thirty days from the date of\nauction sale of the property of the offender or the date of abatement\nof the petition pursuant to sub-section (6).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":"If a petition is made pursuant to s ub-section (7), the\ncourt shall convert the remaining claimed amount or other amount\ninto the term of imprisonment at the rate of three hundred rupees a\nday, and the person liable to pay such claimed amount or other\namount shall be imprisoned accordingly.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(9)","title":null,"content":"While imprisoning any person pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":", such person shall not be imprisoned for more than two years in\nthe case of a claimed amount of a particular person and for more than\nfour years in the case of a claimed amount of a public body u nder\nfull or majority ownership or control of the Government of Nepal,\nState Government or Local Level.\nProvided that while imprisoning any person for the non -\nrecovery of compensation, such person may be imprisoned for up to\nfour years.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(10)","title":null,"content":"While impris oning any person for a personal claimed\namount, compensation or other amount pursuant to sub-section (8), if\nthe claimed amount remains or is less th an three hundred rupees,\nsuch person shall be imprisoned for one day for the same.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(11)","title":null,"content":"While imprisoning a ny person pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(8)","title":null,"content":", the Government of Nepal shall bear such ration expenses as\nshould be provided under law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(12)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, i f the person required to pay a claimed amount,\ncompensation or other amount is held to have concealed or converted\nin any manner his or her property within the period set forth in sub -\nsection (1) or (3), twenty -five percent of such property shall devolve\non one who discovers it, the remaining shall be used to pay t he\nclaimed amount, compensation or other amount and further\nremaining shall be deposited in the consolidated fund ,\nnotwithstanding anything contained in the law in force.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"166","title":"Recovery of amount under judgment from bail /bond","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained elsewhere in this Chapter, if any\noffender has furnished any amount as a bail /bond pursuant to this\nAct, the fine, claimed amount, compensation or other amount\npayable by him or her by virtue of the judgment shall be recovered or\ncaused to be recovered from that amount of bail/bond to the extent it\nis covered by such amount of bail/bond.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"In making recovery pursuant to sub -section (1), it shall\nbe made in order of the following priority:\n(a) Fine,\n(b) Claimed amount,\n(c) Compensation,\n(d) Any other amount, if any.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the full recovery of the claimed amount,\ncompensation or other amount c annot be made, or caused to be\nmade, from the amount referred to in sub -section (1), only the\nremainder of the recoverable amount shall be recovered, or caused to\nbe recovered, upon taking action pursuant to this Chapter.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nChapter, except where any offender pay s immediately the fine,\nclaimed amount, compensation or other amount required to be paid\nby him or her pursuant to the judgment or its recovery can be made\npursuant to sub -section (1), the fine, compensation or other amount\nshall be recovered by auctioning the property, if any, furnished as\nsecurity/guarantee by him or her or by any other person on his or her\nbehalf in accordance with this Act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if any other person has provided his or her property as a\nbail/bond or guarantee in favour of any off ender, before auctioning\nthe property of such other person, the court shall give a notice to him\nor her to pay the fine, claimed amount, compensation or other\namount payable pursuant to the judgment within forty-five days, and\nif such person pays such amount within the said time, the property up\nto the limit of his or her bail/bond or guarantee shall be released.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"In the case of the remainder of the amount which cannot\nbe recovered from the property referred to in sub -section (3), it shall\nbe recovered by auctioning the offender’s other property ; and while\nso making recovery, recovery shall be made in priority referred to in\nsub-section (2).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"If the offender's partition share has not been set aside\nfor the purpose of making auction pursuant to sub-section (6),\nauction shall be made by setting aside his or her partition share in\naccordance with law.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"167","title":"Procedures for attachment, forfeiture or control of property","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"While attaching , forfeiting or taking control of the property of\nany offender pursuant to this Act, the concerned court shall follow\nthe following procedures:\n(a) If the property is being registered or licensed\nseparately, to give a notice of attachment to the\noffice responsible for registering, transmitting,\nissuing or renewing the license,\n(b) If the property is cash, to give a notice of\nattachment to the body holding such cash,\n(c) If the property is that crops or rent can be\nharvested in or collected from it, the court shall\norder the concerned Local L evel to collect such\ncorps or rent and pay the amount into the deposit\naccount,\n(d) If it is the property subject to speedy decay or\nspoil or livestock, the court shall cause such\nproperty to be auctioned and the proceeds of such\nauction to be paid into the deposit account.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While attaching the property of any person pursuant to\nthis Act, if that person has lent a loan to anyone else or invested it,\nthe court shall issue an order to the borrower restraining him or her\nfrom realizing the principal amount , interest or any other ret urn of\nthe said loan or investment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The court shall require the borrower to pay to it the\nprincipal amount, interest, return or similar other amount of the loan\nor investment referred to in sub-section (2).","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If any other person has right in the pro perty attached\npursuant to this Section, such person may make a complaint to the\ncourt making attachment within thirty -five days from the date of\nknowledge of such attachment, by showing his or her right in that\nproperty.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If a complaint is made pursuan t to sub -section (4), the\ncourt shall decide as to the right in the property if it is empowered by\nlaw to make such decision and sha ll forward the complaint to the\nproper court, if it has no such power.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If the court makes any decision pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":", a person who is not satisfied with such decision may make an\nappeal in accordance with law.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"168","title":"To appoint date for appearance for recovery of claimed amount,","content":"compensation or other amount: (1) While appointing a date for\nappearance for causing the recovery of the claimed amount,\ncompensation or other amount pursuant to the judgment, the date for\nappearance shall be appoint ed, by indicating the purpose for which\nthe date is so appointed.\nProvided that the government party shall not be required to be\non recognizance for a government claimed amount or compensation.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If the person entitled to have recovery does not appear\non the date for appearance appointed pursuant to sub-section (1), the\nrecovery proceedings shall be postponed on that day.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If the person entitled to have recovery of the claimed\namount, compensation or other amount makes a petition, showing a\nreasonable reason for his or her absence on the date appointed for\nappearance pursuant to sub-section (1), to the court withi n fifteen\ndays, such claimed amount, compensation or other amount as is\nrecoverable to such person under the judgment shall be recovered to\nhim or her.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If the person who is entitled to have recovery of the\nclaimed amount, compensation or ot her amount and does not appear\non the date appointed pursuant to sub -section (1) fails to make a\npetition within the period referred to in sub-section (2), the recovery\nof such claimed amount, compensation or other amount shall be\nabated for one year.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If the conc erned person makes appearance within the\nperiod referred to in sub -section (4), the recovery of the claimed\namount, compensation or other a mount recoverable under the\njudgment shall be made.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If the concerned person fails to appear within the period\nreferred to in sub-section (4), no action shall thereafter be taken in\nrelation to the recovery of such claimed amount, compensation or\nother amount.","children":[]}]}]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-16","title":null,"content":"Miscellaneous","children":[{"tier":2,"nodeType":"rule","identifier":"169","title":"Cases to be tried by District Court","content":"The case trying authority, if\nany, designated by the Government of Nepal , by a notification in the\nNepal Gazette, shall try any of such cases set forth in the Penal Code,\nand the District Court shall try the other cases.","children":[]},{"tier":2,"nodeType":"rule","identifier":"170","title":"Priority order for trying cases","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The court shall proceed , hear\nand adjudicate cases as per the following order of priority:\n(a) A case to which a person held in detention in the\ncourse of investigation is a party,\n(b) A case to which a person remanded in custody for\ntrial is a party,\n(c) A case to which a person he ld in imprisonment is a\nparty,\n(d) A case to which a person with disability or a child is a\nparty,\n(e) A case to which a person with physical disability or a\nperson of over seventy-five years of age is a party,\n(e) A case relating to violence against woman,\n(f) A case which is accorded priority in proceeding or\nhearing pursuant to law,\n(g) A case registered earlier according to the order of\nregistration of cases.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While proceeding and adjudicating any case involving\nany other persons, in addition to tho se mentioned in clauses (a), (b)\nor (c) of sub -section (1), as parties, proceeding, hearing and\nadjudication shall be made also in the case of such persons.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Out of the cases in which more than one person who are\nremanded in detention or custody are parties, the case of the person\nwho has been held in detention or custody earlier shall be proceeded,\nheard and adjudicated first.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Notwithstanding anything contained in sub -sections (1),","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"and (3), the court may, in view of the gravity and propriety of any\ncase, proceed, hear and adjudicated such case by according priority\nto it.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"171","title":"Index of documents","content":"There shall be maintained an index of\ndocuments in each case in the form referred to in Schedule-50, and\nsuch index shall record the serial number a nd d escription of the\ndocuments, according to the order of the date of registration.","children":[]},{"tier":2,"nodeType":"rule","identifier":"172","title":"Disposal of documents","content":"After the completion of five years of the\nfinal decision of a case, the cou rt shall dispose the documents other\nthan the following documents enclos ed in the case -file of the said\ncase:","children":[{"tier":3,"nodeType":"clause","identifier":"(a)","title":null,"content":"Complaint, charge sheet or plaint,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(b)","title":null,"content":"Statement of the accused or the note of defense,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(c)","title":null,"content":"Statement equivalent to the note of defense,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(d)","title":null,"content":"Originals of evidence,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(e)","title":null,"content":"Memorandum of appeal, if any,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(f)","title":null,"content":"Petition for review or revision of the case, if any,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(g)","title":null,"content":"Judgment or final decision made by the court,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(h)","title":null,"content":"Map, inventory form, statements of property,","children":[]},{"tier":3,"nodeType":"clause","identifier":"(i)","title":null,"content":"Such other documents as conside red necessary to be\npreserved in accordance with law.\nExplanation: For the purposes of this Section, the term \"final\ndecision” means the decision made by the appeal hearing court in\nrelation to a judgment appealed for, and the decision made by the\ncourt competent to make sanction in relation to a reference judgment.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"173","title":"Document to be translated","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If any document written in any\nlanguage other than the Nepali language is submitted to the court in\nthe form of evidence, the court may, as required, order the party who\nhas submitted such document to submit a n authentic translation of\nthe document in the Nepali language.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The concerned party as ordered by the court pursuant to\nsub-section (1) shall make translation of such document in the Nepali\nlanguage and submit its certified copy to the court.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If there arises any dispute as to the translation referred\nto in sub-section (2), the court may summon the presence of and\nexamine any expert in such matter.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"174","title":"Assistance of interpreter may be taken","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If it is required to take\nstatement or deposition of any accused or witness who is unable to\nunderstand or speak the Nepali language or for any other purpose,\nthe investigating authority, prosecutor or the court may take\nassistance of an interpreter of the c oncerned language or the sign\nlanguage.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The Government of Nepal shall bear the expenses\nincurred in taking assistance of the interpreter pursuant to sub -\nsection (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"175","title":"Copies to be provided","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The concerned party to a case or his or\nher law practitioner may obtain a copy of any document contained in\nthe case-file of any case, by paying such fees as provided by law.\nProvided that any law practitioner may obtain the copy of a\njudgment.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nno copy of a document that has to be kept confidential pursuant to\nlaw shall be provided.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"176","title":"Not to try case involving conflict of interest","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No judge shall\nproceed, hear and adjudicate any of the following cases:\n(a) A case involving right, interest or concern of him or\nher or his or her close relative,\nExplanation: For the purposes of this Section, the\nterm “close relative” means a person who is , by\nrelation, entitled to succeed to his or her property\nupon his or her death or maternal uncle, maternal\naunt, mother's elder sister, mother's younger sister,\nmother's elder sister's husband, mother's younger\nsister's husband, mother-in-law, father -in-law,\nfather’s sister, father’s sister' s husband, elder\nbrother-in-law, younger brother -in-law, elder sister -\nin-law, younger sister -in-law, elder sister, younger\nsister, elder sister 's husband , younger sister 's\nhusband, daughter -in-law, nephew, niece, niece's\nhusband, niece's dau ghter-in-law, maternal grand -\nfather, maternal grand-mother or any person having\nsuch relation in the family.\n(b) A case in which he or she has become an attorney,\nlaw practitioner or witness on any occasion,\n(c) A case which he or she, in capacity of the judge, has\ndecided or made a final order therein in any court,\n(d) A case in which he or she has given opinion as to\nwhether or not to institute it on any occasion,\n(e) A case involving, for any other rea son, a substantial\ninterest of him or her or any of his or her joint family\nmembers.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If there appears any circumstance referred to in sub-\nsection (1), the judge shall make order, setting out the reason\ntherefor, to the effect that he or she cannot try the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If any judge proceeds to try, hear or adjudicate any case\nin a manner contrary to sub -section (1), any party may make a\npetition, accompanied by necessary evidence, for not so trying ,\nhearing or adjudicating the case.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If a petition is made pursuant to sub -section (3), the\njudge shall, before proceeding, hearing or adjudicating the case,\nmake decision as to whether the claim of such petition is reasonable\nor not.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If, while making decision pursuant to sub -section (4),\nthe claim of petition appears reasonable or the judge himself or\nherself has made order pursuant to sub -section (2) that he or she\nshould not proceed, hear or settle the case, such case shall be referred\nto another judge , if any, in the same court and in absence of such\njudge, submission shall be made to the appeal hearing court for the\ntransfer of the case in accordance with sub-section (3) of Section 96.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"177","title":"Acts to be done by judge himself or herself","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The judge himself\nor herself shall do the following acts, out of the acts to be done by\nthe court pursuant to this Act:\n(a) Taking and recording a statement or deposition of the\naccused or of a witness,\n(b) Taking an oath of a witness,\n(c) Issuing order for remanding in custody or on bail /bond\nor guarantee,\n(d) Executing a memorandum of orders on matters to be\ndecided in the case,\n(e) Issuing an order for the examination of evidence,\n(f) Issuing an interim or interlocutory order,\n(g) Hearing of the case,\n(g) Holding preliminary and pre-trial discussion in the case,\n(i) Issuing any other kind of order as required,\n(j) Passing a judgment or final order.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Notwithstanding anything contained in sub -section (1),\nthe following matters may be carried out as follows:\n(a) An employee in the court whose rank is at least non -\ngazette first class may record the evidence or deposition\nof a witness, at the direction of the judge.\n(b) In the absence of the judge, the senior -most employee\nout of the employees present in the court may make an\norder pursuant to Chapter 6 in respect of taking\ndepositions of the accused or remanding him or her in\ncustody or taking a bail /bond or guarantee from him or\nher.\nProvided that the order made pursuant to this\nclause shall be submitted to the judge immediately\nwhen the judge attends the court, and the judge may ,\nupon examining it, uphold, void or amend that order.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The acts other than those contained in sub-section (1) or","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"may be done by any employee subordinate to the judge, at the\ndirection or on the order of the latter.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"178","title":"Procedure to be followed for releasing detainee or prisoner","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"If\nany detainee or prisoner has to be released pursuant to the judgment\nor order of the court, the court shall send such order stating the\nreasons for release, full name and address of the detainee or prisoner\nand detail of the case to the concerned prison.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Upon receipt of the order referred to in sub-section (1),\nthe concerned prison shall immediately release the detainee or\nprisoner in pursuance of such order.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Notwithstanding anything contained in sub -sections (1)\nand (2), if any detainee or prisoner to be relea sed pursuant to the\njudgment or order is present in the court, he or she shall , upon\njudgment, be released immediately and a notice thereof shall be\ngiven to the concerned prison.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"179","title":"To give notice on release of property subject to attachment","content":"In\nreleasing any property attached in accordance with this Act pursuant\nto the court judgment or order, the court shall give a notice thereof to\nthe concerned office and the person responsible for such attachment.","children":[]},{"tier":2,"nodeType":"rule","identifier":"180","title":"Pleading and appeal to be made by government attorney","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The\ngovernment attorney shall , on behalf of the Government of Nepal,\nplead and defend the cases related to the offences under Schedule -1\nand Schedule-2.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The concerned authority shall file and appeal cases\nrelated to the offences under Schedule -3, and the concerned\ngovernment attorney shall, if so requested, defend such cases.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"The government attorney shall , while pleading cases,\nplead them as per the prevailing norms on professional conduct.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"Except a s other wise provided in the law in force , the\ngovernment attorney shall have power to make appeal against or file\na petition for the review or revision of, any judgment or order passed\nor made by the court in any case referred to in sub -section (1) in the\nevent of not being satisfied with such judgment or order.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"Notwithstanding anything contained elsewhere in this\nSection, if it is necessary that any particular case , in which the\nGovernment of Nepal is plaintiff, be pleaded by any other law\npractitioner in addition to the government attorney, the concerned\nbody shall, assigning the reason therefor, obtain consent of the\nAttorney General or th e government attorney authorized by him or\nher for the same.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"Upon receiving the consent pursuant to sub -section (5),\nsuch body may appoint another law practitioner.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(7)","title":null,"content":"The law practitio ner appointed pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"shall plead the case, subject to the general direction by the\nAttorney General or the government attorney authorized by him or\nher.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"181","title":"Power of government attorney to make complaint","content":"If any decision\nor order made by any judicial or quasi -judicial body has an effect in\nthe title, interest or concern of the Government of Nepal and there is\nno authority specified by law to file the case, make appeal or review\npetition or make a complaint or petition in any other manner against\nsuch order or decision, the Attorney General or the government\nattorney designated by him or her may, subject to law, make a\ncomplaint, appeal or review or other petition to the con cerned\nauthority against such decision or order on that matter.","children":[]},{"tier":2,"nodeType":"rule","identifier":"182","title":"To register document tendered for registration in court","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The\ncourt shall immediately register a document tendered for registration\nin it and give a receipt thereof if the document is found to meet the\nrequirements of the law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a document ten dered for registration pursuant to sub -\nsection (1) is not found to meet the requirements of the law, the court\nshall return the document, by making endorsement setting out its\nfailure to meet the requirements.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"If, in relation to the matters of a document returned\nupon making endorsement pursuant to sub -section (2), the document\nis made to meet the requirements as set out by endorsement and is\ntendered for registration within the statute of limitation or time-limit\nor within seven days after the da te of endorsement if that date is the\ndeadline for the registration of such document, it shall be registered\nand proceeded with in accordance with law.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"183","title":"Identity of victim or witness may be kept secret","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding anything contained elsewhere in this Act, if the\ninvestigation authority thinks that the disclosure of the identity of a\nperson who is a victim or witness of any particular offence may be\nprejudicial to the social prestige or honor of such person or witness\nor may result in undue fear , terror or fright by the accused or other\nparty or be prejudicial to his or her body or life, the authority may\nmake a request to the court, through the government attorney, that\nthe name, surname, address of such person or witness or the name of\nhis or h er father or any other description which may disclose his or\nher identity be kept secret.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If a request is made pursuant to sub -section (1), the\ncourt may order that the name , surname and address of such victim\nor witness and his or her father's name or his or her identity be kept\nsecret.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"In disclosing the name, surname, address of the person\nor his or her father's name having been kept secret pursuant to sub -\nsection (1) at the time of hearing of the concerned case or publishing\ndetails pertaining thereto, such disclosure shall be made under fake\nname, surname, address or father's name, pursuant to the order of the\ncourt.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"184","title":"Deposition, document or deed made or executed before","content":"investigating authority may be recorded in audio-visual means:","children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Not withstanding anything contained elsewhere in this Act, the\ninvestigating authority may, in the following circumstance, record, or\ncause to be recorded, the deposition, document or deed of a victim of\nan offence, informant or witness through any audio -visual means, in\nthe presence of the government attorney:\n(a) If the investigating authority has a reasonable reason to\nbelieve that the accused may, by way of putting undue\ninfluence on, or showing fear, terror, intimidation or\nthreat to the victim of an offen ce, the informant or any\nwitness, prevent such victim, informant or witness from\nappearing before the court or compel him or her to make\nstatement or deposition contrary to the statement or\ndocument which he or she has made or executed before\nthe investiga ting authority, in spite of his or her\nappearance in the court,\n(b) If such person, informant or witness is, owing to\nphysical infirmity or be ing a child , not able to appear\nbefore the police office or government attorney office,\n(c) If a ny thing to be submitted to the court as evidence\ncannot be taken to the court from the place where that\nthing is situated.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The court may admit in evidence the audio-video means\nrecorded pursuant to sub-section (1).","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"185","title":"Performance of activities by higher level employee","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Any\nfunction or duty that is required to be or may be performed by any\ngovernment attorney, police officer or any other officer pursuant to\nthis Act may also be performed by such government attorney of\nhigher level or of the same level as designated by the Attorney\nGeneral or by such police employee of higher level or of the same\nlevel as designated by the Inspector General of Police or by any\nother officer of higher level or of the same level in the concerned\noffice.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"Any function or duty performed pursuant to sub -section","children":[]},{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"shall be deemed to have been performed by the competent\nauthority.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"186","title":"Receipt to be taken or given","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"While returning any document\nregistered in the court to any person or handing over any documen t\nby the court to any person, a receipt or proof to the effect that such\ndocument has been so returned or handed over shall be executed or\ntaken and enclosed in the case-file.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The court shall, w hile receiving any document\nsubmitted by any person to it, give a receipt thereof to that person.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"187","title":"To make assistance in witnessing and giving signature or thumb","content":"impression: (1) If any person is bound to witness any act in the\ncourse of proceedings or affixing signature or thumb impression on a\ndocument pr epared by the court pursuant to this Act, such person\nshall assist the c ourt by so being witness or affixing signature or\nthumb impression on such document.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If any person bound to witness any act or affix signature\nor thumb impression on any docume nt pursuant to sub -section (1)\nrefuses to do so, th e employee executing that act or document may\nsign and execute such document , by taking signature or thumb\nimpression of any other two persons present , setting out that matter\nand remarks, along with the reason for the failure of such person to\nwitness or sign the document.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(3)","title":null,"content":"Any document executed pursuant to sub -section (2)\nshall be deemed to have been executed in fulfillment of the\nrequirements specified by law.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(4)","title":null,"content":"If any person bound to affix his or her signature or\nthumb impression on any document executed before the court refuses\nto do so, the judge shall set out the matter, mention remarks in the\ndocument and sign it.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(5)","title":null,"content":"If any person does not assist the court by omitting to\nwitness any act or to affix signature or thumb impression on any\ndocument under this Section, the court may fine such person with a\nmaximum of five thousand rupees.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(6)","title":null,"content":"If any person, when affixing his or her signature or\nthumb impression on a document pursuant to this Act, exp resses his\nor her disagreement over any matter contained in the document, he\nor she may affix his or her signature or thumb impression on it,\nseparately stating his or her remarks.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"188","title":"Action not to be instituted","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"No question shall be raised n or any\ncase instituted in any court in respect of any decision, prosecution,\npleading and defense made by the government attorney in relation to\nany case pursuant to this Act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"No action may be taken in respect of any act done or\naction taken in good faith by the investigating authority in relation to\nthe investigation of any of the offences under Schedule -1 and\nSchedule-2.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"189","title":"Provision of investigating committee","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"Notwithstanding\nanything contained elsewhere in this Act, the following committee\nshall investigate into a complaint filed in relation to the offence\ninvestigated or prosecuted dishonestly as referred to in Section 99 of\nthe Penal Code:\n(a) Joint Attorney General of at l east gazetted\nfirst class designated by the Attorney General\n-Chairperson\n(b) At least gazetted first class officer of the\nGovernment of Nepal, as designated by the\nGovernment of Nepal\n-Member\n(c) At least gazetted first class officer of the\nNepal Police, as designated by the\nGovernment of Nepal\n-Member","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"If, in conducting investigation, the committee referred\nto in sub-section (1) finds that such investigation or prosecution has\nbeen conducted or made dishonestly, it shall write to the concerned\ngovernment attorney office to institute the case in relation thereto.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"190","title":"Power to grant permission to take over case","content":"If, in any case of the\noffence under Schedule -4 involving the recovery of any kind of\nmovable or im movable property, other than a case involving the\nrecovery of a claimed amount or sentence of imprisonment or fine,\nthe complainant dies or becomes of unsound mind or goes away and\nthe time-limit and the date appointed for appearance by the court get\nexpired, and his or he r successor makes a petition for the ext ension\nof the time -limit and appointed date for appearance, within thirty -\nfive days from the date of his or her death, being of unsound mind or\ngoing away, excluding the time required for journey, the court may\nissue an order extending the expired time -limit and appointed date\nfor appearance.","children":[]},{"tier":2,"nodeType":"rule","identifier":"191","title":"Mutual legal assistance may be effected","content":"If a summons or warrant\nfor arrest has to be issued to, or any evidence to be taken from, any\noffender of a case related to any offence to be proceeded, heard and\nadjudicated pursuant to this Act who is in a foreign country or it is\nnecessary to assist in the service of a summons or warrant for arrest\non, or take any evidence from, any accused of a case sub judice in a\nforeign court, who is in Nepal, the matter shall be dealt with in\naccordance with the mutual legal assistance law.","children":[]},{"tier":2,"nodeType":"rule","identifier":"192","title":"Documents may be exchanged through electronic means","content":"The\ndocuments referred to in this Act may be exchanged through\nelectronic means in accordance with the law in force related to\nelectronic transactions.","children":[]},{"tier":2,"nodeType":"rule","identifier":"193","title":"Not to be affected by printing or mathematical error","content":"If there is\nany mathematical or other minor error or omission in writing or\nprinting in respect of the procedures under this Act, while conducting\ninvestigation, prosecution and other proceeding of a case under this\nAct, a ll acts and proceedings related thereto shall not be deemed\nillegal by that reason alone.","children":[]},{"tier":2,"nodeType":"rule","identifier":"194","title":"Coordination committee","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"There shall be a coordination\ncommittee as follows , in order to bring effectiveness in the\ninvestigation and prosecution of cases of offence s under Schedule -1\nor Schedule-2, by making coordination, as required, between the\nbodies involved in such investigation and prosecution:\n(a) Attorney General -Chairperson\n(b) Secretary, Ministry of Law, Justice and\nParliamentary Affairs\n-Member\n(c) Secretary, Ministry of Home Affairs -Member\n(d) Inspector General of Police, Nepal Police -Member\n(e) Such government attorney of gazetted first\nclass level or above in the Office of\nAttorney General as designated by the\nAttorney General\n-Member\nsecretary","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The rules of procedures of the coordination committee\nshall be as determined by itself.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"195","title":"Departmental action to be taken","content":"A public servant who fails to do\nact or take any action required to be done or taken pursuant to this\nAct within the period, if any, specified by this Act shall be liable to\ndepartmental action in accordance with law.","children":[]},{"tier":2,"nodeType":"rule","identifier":"196","title":"Power to frame rules","content":null,"children":[{"tier":3,"nodeType":"clause","identifier":"(1)","title":null,"content":"The Government of Nepal may, in\nconsultation with the Attorney General, frame rules on matters of\ninvestigation, and the Supreme Court may frame rules on matters of\ncourt proceedings, for the implementation of this Act.","children":[]},{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"While framing rules pursuant to sub -section (1), the\nJudicial Council shall be consulted on the matters pertaining to the\nadministration of justice.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"197","title":"Power to fra me directives","content":"(1 In order to make acts to be carried\nout under this Act simple, clear and well managed , the following\nauthority may , as required, make and enforce directives on the\nfollowing matters:\n(a) The Government of Nepal, on the advice of the\nAttorney General, in respect of the investigation and\nprosecution of cases of offences under Schedule -1 or\nSchedule-2,\n(b) The Attorney General in respect of the pleading,\ndefense or legal opinion in relation to the cases related\nto offences under Schedule-1 or Schedule-2,\n(c) The Supreme Court in respect of the service of\nsummons under Chapter 6,\n(d) The Supreme Court in respect of the management of\ncourt or bench;\n(e) The Supreme Court in respect of the execution of\njudgments under Chapter 15,\n(f) The Government of Nepal, in consultation with the\nAttorney General, in respect of the withdrawal of cases\npursuant to Section 116,\n(g) The Government of Nepal, in consultation with the\nAttorney General, in respect of pardon pursuant to\nSection 159,\n(h) The S upreme Court in respect of the other court\nproceedings.","children":[{"tier":3,"nodeType":"clause","identifier":"(2)","title":null,"content":"The directives referred to in sub-section (1) shall be\ndeemed to have been issued under this Act.","children":[]}]},{"tier":2,"nodeType":"rule","identifier":"198","title":"Power to make alteration in Schedules","content":"The Government of Nepal\nmay, as required, make any alt eration in or addition to or deletion\nfrom the o ffences set forth in Schedule -1 or Schedule -2, by a\nnotification in the Nepal Gazette.","children":[]}]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-1","title":null,"content":"(Relating to clauses (d) and (l) of Section 2)\n1. Offences under the following Chapters or under the following\nSections of the following Chapters of the Penal Code:\n(a) Part-2:\n(1) Chapter-1\n(2) Chapter-2\n(3) Sections 92, 93, 94 and 102 of Chapter-4\n(4) Sections 1104, 105, 106, 110, 114, 118, 119, 120, 121,\n122, 123, 124, 125 and 126\n(5) Chapter-6\n(6) Chapter-7\n(7) Sections 151 and 152 of Chapter-8\n(8) Chapter-9\n(9) Chapter-10\n(10) Chapter-11\n(11) Chapter-12\n(12) Chapter-13\n(13) Section 192 of Chapter-14\n(14) Chapter-15\n(15) Chapter-16\n(16) Chapter-17\n(17) Sections 219, 221, 222, 223, 225, sub-section (3) of\nSection 226 of Chapter-18\n(18) Chapter-19\n(19) Chapter-20\n(20) Clauses (a) and (b) of sub-section (3) of Section 249 and\nSections 249, 250, 251, 252 and 253 of Chapter-21\n(21) Chapters-22 and 23\n(22) Clauses (a), (b) and (c) of sub -section (3) of Section\n276, and Section 278 of Chapter-25\n(23) Sections 283 (except perso nal property) and 287 of","children":[]},{"tier":1,"nodeType":"chapter","identifier":"Chapter-26","title":null,"content":"(24) Chapter-27","children":[{"tier":2,"nodeType":"rule","identifier":"2","title":"Attempt to, abetment of, conspiracy to any offence under serial","content":"number 1 above","children":[]},{"tier":2,"nodeType":"rule","identifier":"3","title":"Offence relating to human trafficking and transportation","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"4","title":"Offence under the Postal Act, 2019","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"5","title":"Offence relating to citizenship","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"6","title":"Offence relating to ancient monuments","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"7","title":"Offence relating to narcotic drugs","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"8","title":"Offence under the Essential Services Operation Act, 2014","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"9","title":"Offence under Protection and Welfare of the Disabled Act, 2039","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"10","title":"Offence under the Act Relating to Secrecy of Documents, 2039","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"11","title":"Offence relating to passport","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"12","title":"Offence relating to the protection of essential goods","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"13","title":"Offence under the Prison Act, 2019","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"14","title":"Offence under the Donation Act, 2025","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"15","title":"Offence under the Lottery Act, 2025","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"16","title":"Causing death of or grievous hurt or injury to any person by running","content":"over, hitting, blowing or accident by motor vehicle","children":[]},{"tier":2,"nodeType":"rule","identifier":"17","title":"Offence under Section 9A. of the Civil Aviation Act, 2015","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"18","title":"Offence under Section 15 of the Press and Publication Act, 2048","content":null,"children":[]},{"tier":2,"nodeType":"rule","identifier":"19","title":"Offence of forgery or fraud resulted from any offence included in","content":"this Schedule","children":[]},{"tier":2,"nodeType":"rule","identifier":"20","title":"Any such other offence as may be specified by the law in force to be","content":"included in this Schedule","children":[]},{"tier":2,"nodeType":"rule","identifier":"21","title":"Any such offence as may be included in this Sche dule by the","content":"Government of Nepal, by a notification in the Nepal Gazette","children":[]}]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-2","title":null,"content":"(Relating to clauses (d) and (l) of Section 2)\n1. Offences under the following Sections of the following Chapter of\nthe Penal Code:\n(a) Sections 107, 108, 109 , 111, 112 and 113 of Chapter-5\nof Part-2\n2. Any criminal case, which is instituted with the Government of Nepal\nbeing plaintiff, or any offence of criminal nature in which the right,\ninterest or concern of the Government of Nepal is vested, except that\nmentioned in Schedule-1.\n3. Such offen ce as may be included by the law in force in this\nSchedule.\n4. Such offence as may be specified to be tried and adjudicated under\nthis Schedule, by the Government of Nepal , by a notification in the\nNepal Gazette.\n5. Offence of attempt to, abetment of, conspiracy to , any offence under\nnumbers 1, 2, 3 and 4, and any offence related thereto under Chapter\n11.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-3","title":null,"content":"(Relating to clause (l) of Section 2)\n1. Offences under Chapter-3 of Part-2 of the Penal Code.\n2. Any criminal offence in which the Government of Nepal is\nconcerned or in which the right, interest or concern of any\nconstitutional body, court or publi c autho rity is vested, other than\nthat set forth in Schedule-1 or Schedule-2.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-4","title":null,"content":"(Relating to part (l) of Section 2)\n1. Offences under the following Chapters or under the following\nSections of the following Chapters of the Penal Code:\n(a) Part-2:\n(1) Chapter-14 except Section 192\n(2) Chapter-15\n(3) Sections 220, 224, and 226 of Chapter -18 (if a woman\nof 18 years of age or above is involved)\n(4) Clause (c) of sub -section (3 ) of Section 249, Sections\n250 and 252 of Chapter -21 (if any org anization other\nthan a person or Government of Nepal is plaintiff)\n(5) Chapter-25, except clauses (a), (b) and (c) of sub -\nsection (3) of Section 276, and Section 277\n(6) Sections 284, 286 and 287 of Chapter-26 (if a person is\nplaintiff)\n(b) Chapters-1 and 2 of Part 3\n2. Any criminal cases other than those mentioned in Schedule-1, 2 or 3.\n3. Any offences of criminal nature which are to be instituted with\npersons being plaintiff under the law in force.\n4. Offence of incest.\n5. Offences of attempt to, abetment of, conspiracy to, any offence under\nserial numbers 1, 2 and 3 above and any offences related thereto\nunder Chapter-11.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-5","title":null,"content":"(Relating to sub-sections (1) and (7) of Section 4)\nForm of First Information Report\nReport submitted to ………….\n(Name and address of the police office)\nTo be filled in by the police office:\nRegistration No.:\nRegistration date:\n1. Name, surname and address of the person making the first\ninformation report or notice:\n2. Law or case in respect whereof the information report or notice has\nbeen made:\n3. Name, surname and address (including street) of the person who has\ncommitted the offence:\n4. Name of father/mother of the person who has committed the offence:\n5. Special ide ntifying feature s of the person who has committed the\noffence:\n6, Details relating to the offence:\n(a) The place, date and time where and when the offence\nhas been committed or is being committed or going to\nbe committed:\n(b) Details of the event relating to the offence:\n(c) Nature of the offence and other details related to the\noffence:\n(d) Proof, evidence related with the offence:\n(e) Other details related to the offence:\n8. The contents of this report are true and correct ; if proved false , I\nshall bear and pay according to law.\nIf I receive a notice to appear during investigation into the case by\nthe police or trial of the case by the court, I shall appear accordingly.\nPerson making first information report or notice:\nSignature:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-6","title":null,"content":"(Relating to sub-section (3) of Section 4)\nReceipt of First Information Report or Notice\nRe: Concerning the offence related to--------------.\nA report or notice dated --------------made by ------------has been received\nand entered in the register maintained by this police office on ----------\n(date).\nSeal of the office:\nRegistration No.: Report or notice registering police\nemployee:\nSignature:\nName:\nDesignation:\nOffice:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-7","title":null,"content":"(Relating to sub-section (5) of Section 4)\nOffence Register\nGovernment of Nepal\nMinistry of Home Affairs\n……………. Police Office\nRegd\nNo.\nType\nof\ncrime\nDesignated\ninvestigating\nauthority\nDate, time\nand place of\nincident\nDate and time of\nregistration of\nreport\nDate and time of\ndeparture and arrival of\npolice for and on spot\nName,\nsurname of\ninformant\nShort\ndescription of\nthe case\nDescription of\ninjury or hurt\nName,\nsurname,\naddress,\nsex,\noccupation\nof victim\nName\nand\nsurname\nof\nfather of\naccused\nor\nsuspect\nName,\nsurname and\ndescription\nof accused\nor suspect\nDetails of\naccused\narrested\nManner of\ncommission of\noffence\nGoods or\ninstruments\nused in the\ncommission\nof offence\nD e at h H ur t O t he r s\nWitnesses and\npersons in witness of\ndeed of scene of\ncrime\nPhysical material\nevidence or exhibits\nProceeding after investigation Date of\nexamination\nof witness\nJudgment passed by court Appeal made or\nnot; if yes, date of\nRemarks\nDate of\nsubmission of\nreport of\ninvestigation\nProposed opinion\nor advice of\ninvestigating\nauthority\nCharge framed by\ngovernmental\nattorney and law\npertaining thereto\nLimitation","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-8","title":null,"content":"(Relating to sub-section (4) of Section 9)\nForm of warrant for arrest to be issued with the approval of the court\nMr./Ms.----------------\nAddress (including street):--------------\nWhereas, you have to b e arrested in the course of investigation into the\noffence of-------------------, this warrant for arrest is hereby issued pursuant\nto the approval of the ……court, dat ed….. You are hereby required to\nappear in person immediately, accompanied by the police employee carrying\nthis warrant for arrest, before --------office. Otherwise, the police will arrest\nand produce you before-------office.\nInvestigating authority's:\nSignature:\nName:\nDesignation:\nOffice:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-9","title":null,"content":"(Relating to sub-section (6) of Section 9)\nForm of Urgent Warrant for Arrest\nMr./Ms.----------------\nAddress (including street):--------------\nWhereas, you have to be arrested in the course of investigation into the\noffence of-------------------, this warrant for arrest is hereby issued.\nPolice employee's:\nName, surname:\nDesignation:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-10","title":null,"content":"(Relating to sub-section (2) of Section 13)\nForm of Warrant for Detention\nMr/Ms..................\nAddress............\nWhereas, it is required to try the case by holding you in police custody\nin the course of investigation into the offence of......, on the\nreport/information of..............;\nNow, therefore, this warrant for detention is hereby issued for holding\nyou in police custody with effect from this date.\nInvestigating authority:\nSignature:\nName:\nDesignation:\nOffice:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-11","title":null,"content":"(Relating to sub-section (4) of Section 16)\nForm of document executed by person seeing, witnessing, hearing or\nknowing the incident\nDocument executed by ------------(person), aged ------, carrying on\n………profession/occupation, son/daughter of-----------, a resident of---------\n, before Mr./Ms.---------------investigating authority of-------police office.\n1. Short description of the first information report or notice:\n2. Questions in connection with the incident:\n3. Matters set out by the person executing the document:\n4. Presence:\nSignature of the document executing person:\nDone on -----------day, --------month of----------of the year-----------.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-12","title":null,"content":"(Relating to sub-section (2) of Section 18)\nForm of Notice for Making Search\nTo,\n---------------------------------\n--------------------------------\nWhereas, in the case related to the offence of-------------, in which the\nGovernment of Nepal is plaintiff on the report of ----------- and ------------ et.\nal. is defendant, it is possible that the above -named accused might be\nresiding or staying in, or hiding any thing, good or instrument used by him\nor her in the commission of the offence or connected with the offence in,-----\n----(place);\nNow, therefore, I hereby give this notice to you t o search the said\nhouse, place.\nI request for assistance in the above act.\nInvestigating authority:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-13","title":null,"content":"(Relating to sub-section (3) of Section 18)\nForm of Search/Seizure Deed\nDeed of search of thing/ place/body of person a nd seizure of thing\nexecuted at Ward No……, ….Village Body/Municipality --------(place)\nby the Police Office--------------.\n1. Short description of the first information report or notice:\n---------------------------------------------------------------------\n2. If it is req uired to make a prior search of the authority or employee\nmaking search or seizure, details of such prior search made:\n---------------------------------------------------------------------\n3. Description and boundaries of the place where the thing/ place/person\nhas been searched or seized:\n---------------------------------------------------------------------\n4. Description of the seized thing or exhibit related to the offence:\n---------------------------------------------------------------------\n5. Name, surname, age, address and signature of every eye witness:\n(a)\n(b)\n(c)\n6. Name, surname, age, address and signature of the person in whose\npresence the deed is executed:\n(a) The owner or person in charge of the house or thing, a\nresident of -------Ward No…., …….Village\nBody/Municipality, ……….District , signing it covenanting\nthat the investigating authority has offered himself or herself\nto be searched before making search of my body , my house\nand thing, and that he or she has made search with dignity\nand no goods in the house have been misappropriated.\n(b) Name, surname, age, address and signature of the informant:\n(c) Name, surname, age, address and s ignature of the accused\nperson:\nThe investigating authority deputed to e xecute the act including\nsearch, seizure:\nOther employees:\n7. Date:\n8. Time:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-14","title":null,"content":"(Relating to sub-section (2) of Section 20)\nDeed on Scene of Crime/Corpse Examination\nDeed on scene of crime/corpse examination executed in ------------- (place)\nby the police office----------------\n1. Name, surname, description of the deceased:\nAddress:\nAge:\nSex:\n2. Short description of the report or notice:\n---------------------------------------------------------------------\n---------------------------------------------------------------------\n---------------------------------------------------------------------\n3. Description and boundaries of the scene of crime:\n---------------------------------------------------------------------\n---------------------------------------------------------------------\n---------------------------------------------------------------------\n4. Description of the corpse:\nPhysical condition of the corpse: (mention the details)\nDescription of the corpse:\nClothes- (including other physical materials on the body)\nHeight\nColor of hair Condition of hair\nCondition of face\nEyes: Open/closed\nNose Ear\nMouth Teeth and tongue\nCondition of throat\nHands: Stretched or not\nCondition of nail\nCondition of legs\nOther conditions\nBruises:\n(Site, size and measurement)\nAbrasion:\n(Site, size and measurement)\nCut wounds:\n(Site, size)\nThroat abrasion:\nOther sites (Site, size and measurement)\nChest\nCondition of the other parts of stomach\nAnal\nPenis, vagina\nIdentifying marks, if any:\nOther deformities/unusual symptoms, if any:\nSketch of the scene of crime and the corpse (if it can be made):\nNames, surnames, ages, addresses and signatures of eye witnesses:\n----------------------------------------------------------------------\n----------------------------------------------------------------------\n---------------------------------------------------------------------\nNames, surnames, ages, addresses and signatures of persons in whose\npresence the deed is executed:\n---------------------------------------------------------------------\n---------------------------------------------------------------------\n---------------------------------------------------------------------\nName, surname, age, address and signature of the informant:\nNames, surnames, ages, addresses and signatures of the accused\npersons:\nServed by:\nInvestigating authority:\nOther police employees:\n----------------------------------------------\n----------------------------------------------\n----------------------------------------------\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-15","title":null,"content":"(Relating to sub-section (5) of Section 20)\nAutopsy Report\n1. Case registration number:\n2. Police o ffice sending for autopsy (letter date and reference\nnumber):\n3. Name of the deceased:\n4. Address:\n5. Gender:\n6. Age, date of birth:\n7. Dead body identified by:\n8. Name of the accompanying police personnel:\n9. Date and time of death:\n10. Date and hour of receipt of inquest papers and dead body:\n11. Date and hour of starting autopsy:\n12. Date and hour of concluding autopsy:\n13. Name of the experts conducting autopsy:\na. ……………. c.…………….\nb. …………….. d.………………\n14. Name of the Hospital:\nRelevant d etails (mention brief history of the case regarding\ncircumstances of death and other sources of information):\nExternal Examination (general observation of the dead body):\n(1) Height (2) Weight (3) Physique:\n(4) Hairs (5) Clothes and conditions:\n(6) Special identifying features (Huliya):\n(7) Post mortem changes present:\n(a) Rigor mortis:\n(b) Livor mortis:\n(c) Algor mortis/cooling:\n(d) Different signs of decomposition:\n(8) Natural orifices:\nEyes Mouth Vagina/penis\nNose Ears Anus\nUrethra\n(9) Injuries: Name, size, and site (Ante mortem/post\nmortem/old/fresh)\nINTERNAL EXAMINATION\nHead and Neck:\n(1) Scalp, skull:\n(2) Brain and vessels:\n(3) Orbital, nasal and aural cavities:\n(4) Mouth, tongue:\n(5) Neck (larynx, thyroid and other neck structure:\n(6) Other relevant details\nChest (Thorax)\n(1) Ribs and chest wall:\n(2) Diaphragm:\n(3) Oesophagus:\n(4) Trachea and bronchi:\n(5) Pleural activities:\n(6) Lungs:\n(7) Heart and pericardial sac (a ny content in pericardial sac,\ncondition of three coronary arteries, valves and chambers\nand myocardium must be observed):\nAbdomen\n(1) Peritoneal and pelvic cavity:\n(2) Stomach intestine:\n(3) Small intestine:\n(4) Large intestine:\n(5) Liver, gall bladder, pancreas:\n(6) Spleen:\n(7) Kidney, renal pelvis:\n(8) Genital organs:\n(9) Urinary bladder and urethra:\nSpinal Column:\nSpecimen collected for analysis (mention preservative also):\nToxicology:\n(1) Stomach with contents:\n(2) Part of liver:\n(3) Kidney:\n(4) Blood:\n(5) Others, if any:\nHistopathology:\nOthers (specify):\nSpecial Examination: (Procedures like neck dissection, pelvic\ndissection, flotation test of lungs etc. must be done in relevant\ncases and findings should be documented):\nItems handed over (when and who received?)\n(1) Autopsy report:\n(2) Viscera and other samples:\n(3) Clothes and other articles:\nOpinion or conclusion\n1. Opinion or cause of death:\n(Mention cause of death in Nepali language also)\n2. Opinion on time since death:\n3. Opinion on probable type of objects or weapon causing\ninjuries:\n4. Opinion on live birth or still birth:\n5. Other opinion, if any:\nSignature of Medical Officer/Expert\n1. 2. 3.\nSignature:\nDate:\nSignature:\nDate:\nSignature:\nDate:\nName:\nSpecial qualification:\nTraining and\nexperience:\nNMC Reg. No.\nName:\nSpecial\nqualification:\nTraining and\nexperience:\nNMC Reg. No.\nName:\nSpecial\nqualification:\nTraining and\nexperience:\nNMC Reg. No.\nSeal of the Hospital:\nDate:\nNote bene:\n(1) Post mortem shall be conducted by a forensic expert, to the\nextent possible, and by a trained doctor if such expert is not\navailable.\n(2) The report shall be prepared by the autopsy conducting expert\nor doctor himself or herself.\n(3) The report shall be computer typed to the extent possible, if not\nso, be prepared in a legible manner. In addition, the original of\nthe autopsy report shall be attached.\n(4) If the specified space is not enough to contain the details,\ndetails shall also be set down in a separate sheet as well.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-16","title":null,"content":"(Relating to sub-section (1) of Section 22)\nInjury Examination Report\n(It is used in case of examination of detainee also)\n1. Case registration number:\n2. Name of the o ffice referred for injury examination (with letter ref.\nNo. and Date):\n3. Name, age, date of birth and sex of the injured person:\n4. Address:\n5. Name of the accompanying police personnel:\n6. Name of the Hospital/Health Center:\n7. Date, time and place of examination:\n8. Identification mark of the examinee:\n9. Consent for examination taken from:\nInjured person Family member or others\n10. Brief history about the incident (how and when the injuries were\nproduced?)\n11. Medical history of the examinee:\n12. General physique and vitals:\nHeight: Weight Pulse B.P:\nTemperature Respiratory Rate\nDegree of consciousness:\n13. Injuries (name, size, site, color, surrounding area, signs of treatment,\nbleeding, marks, signs of healings, any imprints and content etc.):\nA. Type of injury:\na. Simple:\nb. Grievous:\nc. Severe:\nd. Other remarks:\nB. Type of weapon/object used:\na. Blunt force\nb. Sharp force\nc. Pointed objects\nd. Projectile\ne. Heat\nf. Chemical\ng. Others (specify)\nC. Condition of the patient at the time of examination:\nD. Severity (explain the severity in terms of existing condition\nand possible complication):\nE. Investigation and reports (for example X -ray, USG, Blood,\nUrine etc.):\nF. Treatment provided (briefly):\nG. Referral (Where and Why?):\nH. Follow up (if necessary):\nI. Re-examination (whether case need s information about\ngrade of disability:\nOpinion: (Condition of examinee, severity of the injury, age of\nthe injury and possible causative objects should be considered\nto frame opinion)\nName of the Examiner:\nSignature:\nQualification: MC/NHPC\nReg. No.:\nOffice/Hospital/Health Center:\nDate:\nSeal of the Hospital/Health Center:\nNote bene:\n(1) Injury examination shall be conducted by a forensic expert, to\nthe extent possible, and by a trained doctor if such expert is not\navailable.\n(2) The report shall be prepared by the injury examination\nconducting expert or doctor himself or herself.\n(3) The report shall be computer typed to the extent possible, if not\nso, be prepared in a legible manner. In addition, the original of\nthe autopsy report shall be attached.\n(4) If the specified space is not enough to contain the details,\ndetails shall also be set down in a separate sheet as well.\nSchdule-17\n(Relating to sub-section (3) of Section 24)\nForm of Identification of Person\nDeed of identification executed by the police office…….\nI,…………………., being present at the scene of crime\nof………..committed by ……….., son of………………., a resident of Ward\nNo.…….., ………….Village Body/Municipality, ……….District………,\non……………..(date), and being called upon by the police\noffice………….to identify the offender whom I saw while committing the\noffence, have appeared in this court today. As I saw the following persons\nand noticed their color and appearance at the time of the commission of that\nincident, I hereby identify the said person as the same person/as not the same\nperson because I did not see him or her or his or her color and appearance is\ndifferent.\nName, surname and address of the identifying person:\nPlace of identification made:\nName, surname, address and designation of the identifying executing\nauthority:\nDate of identification made:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-18","title":null,"content":"(Relating to sub-section (1) of Section 25\nPolice Diary\n1. Name of investigating authority:\n2. Date appointed for conducting investigation:\n3. Name of the case:\n4. Name of the plaintiff/defendant:\n5. Description related to investigation:\n(a) Time and date of receipt of information of the offence, and\nshort description thereof:\n(b) Description of visits made by the investigating authority in the\ncourse of investigation:\nDate Place Works\nperformed by\nhim or her\nExhibits,\nproof and\nEvidence\nreceived\nIf someone\nis arrested,\ndescription\nthereof\nName, address\nof the\nperson\ninquired by\nhim or her and\nmatters stated\nby such person\nin relation to\nthe offence\nSignature Remarks","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-19","title":null,"content":"(Relating to sub-section (1) of Section 31)\nInvestigation Report\nCase No:.......... Date of filing:......... Up to ..........\n1. Date and time of receipt of information or complaint of\noffence:.......................\n2. Name and designation of investigating authority ..........................\n3. Name and address of the informant..................................\n4. Short description of the first information report or notice\n...............................\n5. Place, time and date where and whe n the offence was committed\n.......................................\n6. Time and date of the identification of the victim of the offence\ncommitted .................\n7. Place, time and date where and when the offender was arrested\n.............................................\n8. Name, surname, age and address (including street) of offender (if\nmore than one offender, write the names of all offenders\nserially).......................\n9. Name, surname and address of the offender's father, mother………..\n10. Short description of th e statement made by the accused before the\ncompetent authority..................................\n11. Place where goods related to the offence were found\n.....................................\n12. Name, surname, age and address of the victim of the offence\n....................\n13. Clear description and sketch of the scene of crime...........................\n14. Instruments or arms used in the commission of the offence\n........................\n15. Cause of incident and motive of the offender:...............\n16. Proposal opinion and punishment claimed by the investigation\nofficer:.........................\n17. If compensation is caused to be recovered, description of who is\nentitled to recover how much compensation: .....................\n18. Names, surnames and addresses of witness es who know about the\noffence; and short description of the deed made by them before the\ninvestigating authority :..........................\n19. Physical proof and evidence related to the offence:\n:......................................\n20. If any other things are to be mentioned, description thereof:\n21. Serial description of the documents....................................","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-20","title":null,"content":"(Relating to sub-section (1) of Section 32)\nForm of Charge Sheet\nTo be filled in by the court:\nRegistration No:\nRegistration date:\nA Charge Sheet\nfiled under Section 20 of Chapter-3 of the National Criminal Procedure\n(Code) Act, 2017\nin ....................... court\nNo.... of the year......\nGovernment of Nepal, on the report of...................... Plaintiff\nVersus\n(1) ............................................................. Defendant\n(2) ............................................................\n(3) .............................................................\nCase:\nDescription of the case:\n(1)\n(2)\n(3)\nCharge against the accused:\nDetails of legal provision related to the charge:\nSentence to be awarded to the accused:\nWhere the accused has confessed the offence, description thereof and\nproposed reduction in punishment for such confession:\nProof, evidence:\nProof, evidence and thing related to the offence:\nWitness:\nEye-witness:\n(1)\n(2)\n(3)\n(4)\nIf compensation is caused to be provided to the person who has sustained\ninjury from the offence, the claim for compensation:\nExhibits or other goods or things connected with the offence and can be\nadmissible in evidence:\n(1)\n(2)\n(3)\nDocuments presented:\n(1)\n(2)\n(3)\nIt is humbly prayed that the court institute proceeding s based on this charge\nsheet.\nSeal of office:\nGovernment attorney's:\nSignature:\nName:\nDesignation:\nOffice:\nDate:\nNote bene:\n(1) While framing a charge sheet, it should be so framed that the matters\nrequired to be set down pursuant to Section 32 of Chapter -3 of this\nAct are also set down.\n(2) The names, surnames, addresses of all offenders should be mentioned\nin the versus column in serial order.\n(3) The available proof, evidence and document should be set d own\nserially in the above form.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-21","title":null,"content":"(Relating to sub-section (2) of Section 53)\nForm of Complaint\nTo be filled in by the court:\nRegistration No.:\nRegistration Date:\nA Complaint\nfiled in ................under Section........of Chapter.........of the National\nCriminal Procedure (Code) Act, 2017\nCriminal case-file number ........of the year.....\n......................,aged..............,a resident of.........................Complainant\nVersus\n......................,aged..............,a resident of..........................Offender\nCase: .............\nThe description of the offence committed by the said offender is as follows.\nI humbly pray that the proceedings of case be instituted against him or her.\n1. Description of the offence:..........................\n2. Charge made against the offender................\n3. Related law:...........\n4. Sentence to be imposed on the offender: ..............\n5. Injury caused from the offence and amount recoverable from the\noffender:\n6. Where the accused has confessed the offence, description thereof and\nproposed remission of punishment for such confession:\n7. Other necessary matters:\nEvidence\nWitness:\n1.\n2.\n(Full name, age and address of the witness)\nDocuments:\n1.\n2.\nExhibits:\n1.\n2. Complainant:\n.....aged....., son/daughter/wife of.......,\na resident of.........born in..........\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-22","title":null,"content":"(Relating to sub-section (7) of Section 57)\nNotice for appearance in pursuance of the warrant for arrest\nNotice issued by.....................court\nWhereas, on the report/information of ......................, a charge sheet has been\nfiled in the case of............. (state the offence) in which the Government of\nNepal is plaintiff and you/you et al................are defendant;\nNow, therefore, the warrant for arrest issued against you is herewith\nforwarded. You are hereby required to appear in person in pursuance of this\nwarrant for arrest.\nSeal of court Concerned authority's:\nSignature:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-23","title":null,"content":"(Relating to sub-section (1) of Section 58)\nForm of warrant for arrest to be issued by the court against the\noffender\n.\nNotice issued by …………… court\nWhereas, on the report or information of ......................, a charge sheet has\nbeen filed in the case of............. (state the offence) in which the\nGovernment of Nepal is plaintiff and you/you et al................are defendant;\nNow, therefore, the warrant for arrest is issued to you. Yo u are hereby\ninformed to appear in pursuance of this warrant for arrest.\nSeal of court Concerned authority's:\nSignature:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-24","title":null,"content":"(Relating to sub-section (1) of Section 58)\nForm of warrant for arrest to be issued by the court in the name of\nwitness and other person\nA warrant for arrest issued by.............court in the name of the accused\n......................\n(Name of the officer or office)\nWhereas, the proceedings of the case have been instituted i n this court,\nagainst……………….. (name and address of the person to be arrested), on\nthe charge of…………….(offence), you are hereby directed to arrest the\nsaid person and produce him or her before this court within seven days,\nexcluding the time required for journey. In the event of the failure to\nproduce the said person within the said period, you are required to serve this\nwarrant for arrest and the notice sent along with it on the eighth day and give\ninformation thereof to this court, and to keep on searching the person to be\narrested, arrest him or her wherever found and produce him or her before\nthis court.\nThe concerned authority's signature:\nDate:\nSeal of the court:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-25","title":null,"content":"(Relating to sub-section (7) of Section 58)\n35-day warrant for arrest issued by the court\nWhereas, in the case of...............(state the offence) in which the Government\nof Nepal is plaintiff on the information report of ...................... and you/ you\net al ................are defendant, a warrant for arrest has been issued for\narresting you but you have not been arrested;\nNow, therefore, this 35-day warrant for arrest has also been posted. If you\nvoluntarily appear or are arrested and produced befor e this court within\nthirty-five days excluding the time required for journey, you shall be heard\nand tried in accordance with law. If you remain absconding thereby expiring\nthe time-limit, the case shall be tried in accordance with law; and you shall\nnot be entitled to make a complaint subsequently.\nDate:\nSeal of court: Concerned authority's:\nSignature:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-26","title":null,"content":"(Relating to sub-section (2) of Section 59)\nForm of summons issued in the name of accused\nA summons issued by............in the name of................a resident of............\nWhereas, a charge sheet has been filed in this court against you on the\ncharge of.........(offence) and the matter shall be heard\non................day.................date..............month...............year;\nNo, therefore, you are hereby required to appear in this court. If you fail to\nappear on that day, a warrant shall be issued to arrest you, and action shall\nbe instit uted in accordance with the law . The complaint against you is\nattached herewith.\nConcerned authority's:\nSignature:\n(Copies of documents attached)\n1............................\n2. ...........................\n3. ...........................\n4. ...........................\n(Seal of the court)\nDate: .............","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-27","title":null,"content":"(Relating to sub-section (2) of Section 59)\nForm of summons to be issued in individual criminal case\nA summons issued by............in the name of................a resident of............\nWhereas, a complaint has been filed in this court against you on the charge\nof.........(offence);\nNow, therefore, this summons is hereby issued to you. You are hereby\nrequired to appear in this court within thirty days after the issuance of this\nsummons. You are hereby informed that if you fail to appear within the said\nperiod, action shall be instituted in accordance with the law.\nConcerned authority's:\nSignature:\n(Copies of documents attached)\n1............................\n2. ...........................\n3. ...........................\n4. ...........................\n(Seal of the court)\nDate: .............","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-28","title":null,"content":"(Relating to Section 60)\nForm of summons issued in the name of witness\nA summons issued by............in the name of................a resident of............\nWhereas, it is required to examine you on the matter of the case of............in\nwhich ..................is plaintiff and ..............is defendant;\nNow, therefore, you are hereby required to appear in this court at.......o'clock\nin the morning on the------day of the month of..........the year........ If you fail\nto appear, the matter shall be dealt with in accordance with law.\nConcerned authority's:\nSignature:\n(Seal of the court)\nDate: ............","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-29","title":null,"content":"(Relating to sub-section (1) of Section 74)\nForm of deed to be executed by person furnishing bail/bond\nWhereas, in the case of…………(of the year……) in which the Government\nof Nepal is plaintiff on the report of..............and …………(defendant), a\nbail/bond of…………… has been demanded by the order of the\n………..court dated…………;\nNow, therefore, I have made this petition for permission to furnish a\nbail/bond of …………….rupees in cash or of the following property. I shall\nappear at all times as and when the court so specifies, and if I fail to do so, I\nhereby agree to the forfeiture of the bail /bond to the extent the sum of\nmoney payable by me.\nName, surname and address of the person furnishing bail/bond:\nName, surname and address of father and grand-father:\nDescription of the property:………","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-30","title":null,"content":"(Relating to sub-section (3) of Section 74)\nForm of deed to be executed by person furnishing property as\nguarantee\nWhereas, in the case of…………(of the year……) in which the Government\nof Nepal is plaintiff on the report of.......... ....and …………(defendant), a\nguarantee of…………… has been demanded by the order of the\n………..court dated…………;\nNow, therefore, I have made this petition for permission to furnish a\nguarantee of …………….rupees in cash or of the following property. I shall\nappear at all times as and when the court so specifies, and if I fail to do so, I\nhereby agree to the forfeiture of the guarantee to the extent the sum of\nmoney payable by me or the sentence imposed on me.\nName, surname and address of the person furnishing guarantee:\nName, surname and address of father and grand-father:\nDescription of the property:………","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-31","title":null,"content":"(Relating to sub-section (4) of Section 73)\nForm of deed to be executed if other person than the accused/defendant\nfurnishes guarantee\nWhereas, in the case of…………(of the year……) in which the Government\nof Nepal is plaintiff on the report of..............and …………(de fendant), a\nguarantee of…………… has been demanded from him/her, by the or der of\nthe ………..court dated…………, and I………………….. being agreed to\nfurnish a sum of…………rupees in cash or the following property as the\nguarantee in his or her favor;\nNow, therefore, I hereby appear to furnish the guarantee . I hereby covenant\nthat I shall cause him or her (the accused/defendant) to appear at the time\nappointed by the court; and in the case of my default, I hereby agree to the\nrecovery of the sentence imposable on, or any amount payable by, him or\nher from the said guarantee or any other property.\nName, surname and address of the guarantor/surety:\nName, surname and address of father and grand-father:\nDescription of the property:………\nSignature:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-32","title":null,"content":"(Relating to Section 80)\nForm of Warrant for Detention\nMr/Ms..................\nAddress............\nWhereas, it is required to try the case by holding you in police custody in the\ncourse of the offence of …………….., in which the Government of Nepal is\nplaintiff on report of.............., and you, et.al, are defendant;\nNow, therefore, this warrant for detention is hereby issued for holding you in\npolice custody with effect from this date.\nThe concerned authority:\nSignature:\nName:\nDesignation:\nOffice:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-33","title":null,"content":"(Relating to sub-section (1) of Section 82)\nForm of Book of Appointed Date for Appearance\nBook of appointed date for appearance maintained by the ..............\nYear........\nMonth,\ndate, day\nSN Case Name of the\ncomplainant,\nappellant or\napplicant\nName of the\naccused or\nrespondent\nPurpose for\nwhich date for\nappearance is\nappointed\nRemarks\nSignature:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-34","title":null,"content":"(Relating to sub-section (2) of Section 82)\nForm of Acknowledgment of Appointed Date for Appearance\nBook of appointed date for appearance maintained by the ..............\nYear........\nPlaintiff Defendant\nCase:\nDate:\nWhereas, the case will be enlisted in the cause list for final hearing/\n…………..proceeding will be conducted on……..(date);\nNow, therefore, I hereby sign binding myself to appear in this court/office\nat………hours, on the……..day of the month of …….of the year 20…….\nPlaintiff….. Defendant….","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-35","title":null,"content":"(Relating to sub-section (1) of Section 83)\nForm of Memorandum of Appointed Date for Appearance\nMemorandum of appointed date for appearance issued by...............in\nthe name of................\nCase......................year....................No.................\nVersus..................\nWhereas, the date of ........has been appointed as the date for appearance for\nthe purpose of ................;\nNow, therefore, you are hereby required to appear at........o'clock on the said\nday.\nSignature of the employee appointing the due date.\nWhereas, the date of ........has been appointed as the date for appearance for\nthe purpose of ................;\nNow, therefore, you are hereby required to appear at........o'clock on the said\nday.\nSignature of the employee appointing date for appearance.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-36","title":null,"content":"(Relating to sub-section (5) of Section 89)\nForm of Power of Attorney\nI have appointed Mr./Ms . .......................as my attorney to carry out the act\nof.....................on my behalf, in the case of.......... with................ He or she\ndoes not suffer any disqualification for being an attorney.\nDate:\nThumb impressions Signature:\nRight Left ...........(Full name)\n...........(Full address)\n………(Citizenship No.)\nI hereby consent to act as an attorney of Mr./ Ms. ..............., a resident\nof..............., as mentioned above. I shall perform the said act with honesty. I\ndo not suffer any disqualification for being an attorney.\nDate:\nThumb impressions Signature:\nRight Left ...........(Full name)\n...........(Full address)\n………(Citizenship No.)\nIt is true and correct that this power of attorney has been drawn up and\nsigned in our presence.\nWitnesses:\n(1) Writer witness, age of ......years, a resident of..................\nThumb impressions: Signature:\nRight Left\n(2) Writer witness, age of ......years, a resident of..................\nThumb impressions\nSignature:\nRight Left","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-37","title":null,"content":"(Relating to sub-section (2) of Section 106)\nForm of oath to be taken by witness\nI............hereby take an oath in the name of the God/ swear with truth and\nhonesty that in the case of...............versus............, I shall give true statement\nof whatever I have seen, known and heard; that I shall not conceal or l ie any\nmatter; and that I shall give true answers to all questions asked by the court\nand by or on behalf of the parties to the case, to the extent of whatever I\nhave seen, known and heard.\nSignature of oath taking person:\nSignature of oath administering person:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-38","title":null,"content":"(Relating to sub-section (3) of Section 106)\nForm of taking deposition of witness\nCase................\nNumber............of the year.........\nVersus..........\nDeposition of witness...................\nQuestions and answers of the questions\nQuestion: What is your and your father's name?\nAnswer:\nWhat is your age? What is your occupation? Where do you live?\nAnswer:\nSignature of the person making deposition:\nSignature of the person/judge taking deposition:\nNote: The questions and answers thereof shall be recorded on the same order\nas examined, cross-examined or re-examined by the parties to the case; and\nif the court has asked the witness any question at the beginning, in the\nmeanwhile or at the end, that question and the answer thereof shall also be\nset down according to the serial order.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-39","title":null,"content":"(Relating to sub-section (4) of Section 107)\nForm of Commission\nA commission sent by...............\nCase.............\nof the year.....\nDate......................\nComplainant..................\nVs.\nAccused.......................\nDeposition of witness...............\nQuestion: What is your and your father's name?\nAnswer:\nWhat is your age? What is your occupation? Where do you live?\nAnswer:\nSignature of parties:\nSignature of the person making deposition:\nSignature of the person/judge taking deposition:\nNote: The questions and answers thereof shall be recorded on the same order\nas examined, cross-examined or re-examined by the parties to the c ase; and\nif the court has asked the witness any question at the beginning, in the\nmeanwhile or at the end, that question and the answer thereof shall also be\nset down according to the serial order.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-40","title":null,"content":"(Relating to sub-section (6) of Section 109)\nForm of deed of record of examination of witness through video\nconference\nWe, the undersigned, hereby covenant that it is true and correct that , in the\ncase of………….in which …………….is plaintiff and ……….is defendant,\nbeing …………, the witness of the plaintiff/ defendant, unable to appear in\nthe court , the said witness was examined in our presence through video\nconference by the order of the …….court dated………\nIn presence of:\nName, surname and signature of the Local Level member or representative:\nName, surname and signature of the local person:\nName, surname and signature of the witness:\nName, surname and signature of the employee deputed by the court:\nName, surname and signature of the technical employee:\nName, surname and signature of the plaintiff, defendant o r his or her\nattorney:\nName, surname and signature of the legal practitioner of the\nplaintiff/defendant, if any:\nPlace:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-41","title":null,"content":"(Relating to sub-section (2) of Section 115)\nForm of commission to be used for examination of witness abroad\nA commission sent by...............\nIn the case............. (plaintiff) and …….(defendant)\nIn the name of the witness……….., residing in ……..(country)\nof the year.....\nDate......................\nComplainant..................\nVs.\nAccused.......................\nDeposition of witness...............\nQuestion: What is your and your father's name?\nAnswer:\nWhat is your age? What is your occupation? Where do you live?\nAnswer:\nName of the country where commission was executed:\nSignature of the person making deposition:\nSignature of the authority taking deposition:\nNote: The questions and answers thereof shall be recorded on the same order\nas examined, cross-examined or re-examined by the parties to the case; and\nif the court has asked the witness any question at the beginning, in the\nmeanwhile or at the end, that question and the answer thereof shall also be\nset down according to the serial order.","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-42","title":null,"content":"(Relating to sub-section (8) of Section 122)\nForm of statement of defense\nTo be filled by the court\nRegistration No.:\nRegistration Date.:\nSubmitted to:\nForm of statement of defense\nCriminal case file number...........of the year......\nAccused................, age of ......years, a resident of .........\nVersus\nComplainant, .................., age of ......years, a resident of .........\nCase:...............\nIn connection with the charge made against me by the said complainant, my\nstatements or pleas are as follows:\n1...................................\n2...................................\n3..................................\nEvidence\n1...................................\n2...................................\n3..................................\nDocuments\n1...................................\n2...................................\nMr./Ms. .............. age of ......years, son/daughter/wife of Mr./Ms............\nDate:\nSignature/thumb impressions of the accused:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-43","title":null,"content":"(Relating to sub-section (3) of Section 131)\nForm of Judgment\n...........Court\nBranch of...........\nJudgment\nCase..............Number...............of the year....................\n..........................................\nVersus\n......................................\n1.........................................................................................................................\n...........................................................................................................................\n(Main points of the complaint)\n2.........................................................................................................................\n...........................................................................................................................\n(Main points of the deposition of the accused or statement of defense)\n3.........................................................................................................................\n...........................................................................................................................\n(The matters to be decided by the court)\n4.........................................................................................................................\n...........................................................................................................................\n(Decision of the court along with the reasons for the same)\n5.........................................................................................................................\n...........................................................................................................................\n(Punishment sentenced to the party or witness)\n6.........................................................................................................................\n...........................................................................................................................\n(Other necessary matters)\nDate: Signature of the judge:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-44","title":null,"content":"(Relating to sub-section (1) of Section 132)\nForm of notice of judgment\nBy...........\nNotice of judgment\nNotice of judgment given to ...............(full name and address of the party)\nCase..............Number...............of the year....................\n..........................................\nVersus\n......................................\nWhereas, judgment (main contents of the decision) has been passed by this\ncourt in the aforesaid case...............on (date);\nNow, therefore, a notice of the judgment is hereby given to you.\n(Seal of the court)\nSignature of authority sending the notice:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-45","title":null,"content":"(Relating to sub-section (1) of Section 136)\nForm of memorandum of appeal\nTo be filled by the court\nRegistration No.:\nRegistration Date.:\nSubmitted to:\nMemorandum of appeal\nFirst/second appeal number...........of the year......\n................, age of ......years, a resident of ........\nAppellant/complainant/accused\nVersus\n.................., age of ......years, a resident of .........\nRespondent/complainant/accused\nCase:...............\nWhereas, the..........................has passed judgment in the aforesaid\ncase..............awarding punishment of.......... to me/us and ordering the\nrecovery of the claimed amount or compensation from me/us;\nNow, therefore, I/we have made this appeal on the matters with which\nI/we am/are not satisfied, by serving the sentence awarded by the judgment/\nfurnishing a bail /bond/guarantee for the same. My/our statements are as\nfollows:\n1................\n2................\n3................\n4................\nThe appellant's:\nSignature or thumb impression:\nDate: Name:\nDate:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-46","title":null,"content":"(Relating to sub-section (6) of Section 140)\nForm of Counterclaim\nTo be filled by the court\nRegistration No.:\nRegistration Date:\nSubmitted to:\nCounterclaim\nFirst/second appeal number...........of the year......\n................, age of ......years, a resident of .......\nRespondent/complainant/accused\nVersus\n.................., age of ......years, a resident of .........\nAppellant/complainant/accused\nCase:...............\nWhereas, I/we have got a notice from the ………court in the said case to\nsubmit a counterclaim;\nNow, therefore, I/we have submitted this counterclaim. My/our statements\nare as follows:\n1................\n2................\n3................\n4................\nRespondent's:\nDate: Name:\nAddress:\nSignature or thumb impression:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-47","title":null,"content":"(Relating to Section 150)\nForm of Appellate Judgment\n...........Court\nBranch of...........\nAppellate Judgment\nCase..............Number...............of the year....................\n..........................(full name, surname and address of the appellant)\nVersus\n..........................(full name, surname and address of the respondent)\n1.........................................................................................................................\n...........................................................................................................................\n(Main points of the appellant)\n2.........................................................................................................................\n...........................................................................................................................\n(Main points of the respondent)\n3.........................................................................................................................\n...........................................................................................................................\n(Main points of the judgment from which appeal has been made)\n4.........................................................................................................................\n..........................................................................................................................\n(The matters to be decided by the court)\n5.........................................................................................................................\n........................................................................................................................\n(Decision of the court along with the reasons for the same)\nDate: Signature of the judge:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-48","title":null,"content":"(Relating to Section 150)\nForm of Reference Judgment\n...........Court\nBranch of...........\nReference Judgment\nCase..............Number...............of the year....................\n..........................................\nVersus\n......................................\n1.........................................................................................................................\n...........................................................................................................................\n(Main points of the complaint)\n2.........................................................................................................................\n...........................................................................................................................\n(Main points of the deposition of the accused/statement of defense)\n3.........................................................................................................................\n...........................................................................................................................\n(The matters to be decided by the court)\n4.........................................................................................................................\n...........................................................................................................................\n(Judgment of the court making the reference for sanction)\n5.........................................................................................................................\n........................................................................................................................\n(Decision of the court along with the reasons for the same)\nDate: Signature of the judge:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-49","title":null,"content":"(Related to sub-section (4) of Section 151)\nForm of order for arrest in pursuance of judgment\nOrder\nissued by.........\nDirected to the police office..........\nWhereas, the punishment of .............has been sentenced by the judgment of\nthis court dated...............to Mr./Ms......................, a resident of .................;\nand the said person has absconded;\nNow, therefore, it is hereby ordered that the said person be arrested as soon\nas possible and handed over to the prison office................\nDate.....\nSignature of the judge:\nSeal of the court:","children":[]},{"tier":1,"nodeType":"schedule","identifier":"Schedule-50","title":null,"content":"(Relating to Section 171)\nForm of index of documents\n.............................................versus.......................................\nCase:\nCase-file number.........of year........\nSerial\nnumber of\ndocuments\nShort\ndescription of\ndocuments\nName of\nparties\nsubmitting\ndocuments\nDate of\nsubmission of\ndocuments\nSignature of\nemployee\nSignature of preparer:\nSignature of certifier:","children":[]}]}$LEGAL_ab96e86c97ce3a$::jsonb
